#include <stdio.h>
#include <stdlib.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <mcp3004.h>
#include <time.h>

#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define SPI_SPEED 1000000

int main(void)
{
    int fd;
    unsigned int value;
    struct timespec ts;

    // Initialize wiringPi library
    if (wiringPiSetup() == -1)
    {
        printf("Failed to initialize wiringPi library\n");
        return 1;
    }

    // Initialize SPI
    fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (fd == -1)
    {
        printf("Failed to initialize SPI\n");
        return 1;
    }

    // Initialize MCP3004
    if (mcp3004Setup(100, ADC_CHANNEL) == -1)
    {
        printf("Failed to initialize MCP3004\n");
        return 1;
    }

    // Main loop
    while (1)
    {
        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);

        // Read from ADC
        value = analogRead(ADC_CHANNEL);

        // Print value and timestamp
        printf("%ld.%ld: %d\n", ts.tv_sec, ts.tv_nsec, value);

        // Sleep for 1 second
        delay(1000);
    }

    return 0;
}

