#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <ads1115.h>
#include <Adafruit_I2C.h>

#define SENSOR_ADDR 0x48 // ADS1115 address
#define SDA_PIN 2 // SDA pin
#define SCL_PIN 3 // SCL pin
#define GAIN ADS1115_GAIN_TWOTHIRDS // Programmable gain
#define DATA_RATE ADS1115_RATE_128 // Data rate
#define SENSOR_CHANNEL ADS1115_CHANNEL_0 // Sensor channel

Adafruit_I2CDevice *i2c_dev = NULL;
ADS1115 ads(SENSOR_ADDR, i2c_dev);

void handle_sigint(int sig) {
    printf("Exiting...\n");
    ads.end();
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    if (!ads.begin_I2C(SDA_PIN, SCL_PIN)) {
        printf("Failed to initialize ADS1115\n");
        return 1;
    }

    ads.setGain(GAIN);
    ads.setDataRate(DATA_RATE);
    ads.setMode(ADS1115_MODE_SINGLESHOT);

    while (1) {
        int16_t adc_reading = ads.analogRead(SENSOR_CHANNEL);
        if (adc_reading < 0) {
            printf("Failed to read from ADS1115\n");
            return 1;
        }

        float current = ads.computeVolts(adc_reading);
        printf("Current: %f A\n", current);

        usleep(500000); // Sleep for 500ms
    }

    return 0;
}

