#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <time.h>
#include <signal.h>
#include <stdio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define FLAME_SENSOR_PIN 4
#define ADC_PIN 0
#define ADC_CE_PIN 8

int keepRunning = 1;

void sigintHandler(int sig) {
    keepRunning = 0;
}

int main() {
    signal(SIGINT, sigintHandler);

    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        printf("Failed to setup SPI\n");
        return 1;
    }

    pinMode(FLAME_SENSOR_PIN, INPUT);
    pinMode(ADC_CE_PIN, OUTPUT);

    digitalWrite(ADC_CE_PIN, LOW);

    FILE *file = fopen("flame_data.csv", "w");
    if (file == NULL) {
        printf("Failed to open file\n");
        return 1;
    }

    while (keepRunning) {
        time_t now = time(NULL);
        int flameDetected = digitalRead(FLAME_SENSOR_PIN);

        digitalWrite(ADC_CE_PIN, HIGH);
        unsigned char data[3] = {0x01, (char)(ADC_PIN << 6), 0x00};
        wiringPiSPIDataRW(SPI_CHANNEL, data, 3);
        digitalWrite(ADC_CE_PIN, LOW);

        int analogReading = (data[1] << 8) | data[2];

        if (fprintf(file, "%ld,%d,%d\n", now, flameDetected, analogReading) < 0) {
            printf("Failed to write to file\n");
            fclose(file);
            return 1;
        }

        fflush(file);
        sleep(1);
    }

    fclose(file);
    return 0;
}

