#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <bcm2835.h>
#include <ADS1115.h>

#define FLAME_SENSOR_GPIO 4
#define HEAT_SENSOR_CHANNEL ADS1115_SINGLE_ENDED_0
#define BUZZER_GPIO 27
#define DEBOUNCE_DELAY 50
#define POLLING_DELAY 100

volatile sig_atomic_t running = 1;

void handle_signal(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *flame_sensor, *buzzer;
    ADS1115 ads1115;
    FILE *log_file;
    int flame_value, heat_value;
    char log_message[100];
    time_t timestamp;

    signal(SIGINT, handle_signal);

    if (!bcm2835_init()) {
        fprintf(stderr, "Failed to initialize bcm2835 library\n");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    flame_sensor = gpiod_chip_get_line(chip, FLAME_SENSOR_GPIO);
    buzzer = gpiod_chip_get_line(chip, BUZZER_GPIO);

    if (!ads1115_init(&ads1115, 1)) {
        fprintf(stderr, "Failed to initialize ADS1115\n");
        return 1;
    }

    log_file = fopen("fire_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (running) {
        flame_value = gpiod_line_get_value(flame_sensor);
        usleep(DEBOUNCE_DELAY * 1000);
        if (flame_value && gpiod_line_get_value(flame_sensor)) {
            heat_value = ads1115_read(&ads1115, HEAT_SENSOR_CHANNEL);
            if (heat_value < 0) {
                fprintf(stderr, "Failed to read from ADS1115\n");
                continue;
            }
            if (heat_value > 60000) {
                sprintf(log_message, "%ld: Temperature exceeded 60°C\n", time(&timestamp));
                fputs(log_message, log_file);
            }
            gpiod_line_set_value(buzzer, 1);
            usleep(2000000);
            gpiod_line_set_value(buzzer, 0);
            if (heat_value > 60000) {
                sprintf(log_message, "%ld: Fire detected!\n", time(&timestamp));
                fputs(log_message, log_file);
            }
        } else if (flame_value) {
            sprintf(log_message, "%ld: Flame detected!\n", time(&timestamp));
            fputs(log_message, log_file);
        }
        usleep(POLLING_DELAY * 1000);
    }

    fclose(log_file);
    gpiod_line_release(buzzer);
    gpiod_chip_close(chip);
    bcm2835_close();
    ads1115_cleanup(&ads1115);

    return 0;
}

