#include <stdio.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define THRESHOLD 1000 // Define your threshold here

int spi_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void handle_signal(int signum) {
    gpiod_line_set_value(line, 0);
    close(spi_fd);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    uint8_t mode = 0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    while (1) {
        uint8_t tx_data[3] = {0x01, 0x80, 0x00};
        uint8_t rx_data[3] = {0, 0, 0};

        struct spi_ioc_transfer tr = {
            .tx_buf = (unsigned long)tx_data,
            .rx_buf = (unsigned long)rx_data,
            .len = 3,
            .delay_usecs = 0,
            .speed_hz = 1000000,
            .bits_per_word = 8,
        };

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            perror("Failed to transfer SPI data");
            return 1;
        }

        uint16_t adc_value = (rx_data[1] << 8) | rx_data[2];
        if (adc_value == 0 || adc_value == 0xFFF) {
            printf("Sensor absent\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

        FILE *file = fopen("current_log.txt", "a");
        if (file) {
            fprintf(file, "%s,%d\n", timestamp, adc_value);
            fclose(file);
        }

        if (adc_value > THRESHOLD) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        sleep(1);
    }

    return 0;
}

