#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <wiringPiI2C.h>
#include <wiringPi.h>

#define ADS1115_ADDRESS 0x48  // replace with your ADS1115 I2C address
#define MICS4514_ADDRESS 0x28  // replace with your MICS4514 I2C address

#define COEF_A 0.0  // replace with your calibration coefficient A
#define COEF_B 0.0  // replace with your calibration coefficient B
#define COEF_C 0.0  // replace with your calibration coefficient C

int fd;

void handle_signal(int signum) {
    printf("Exiting...\n");
    close(fd);
    exit(0);
}

int main() {
    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    fd = wiringPiI2CSetup(ADS1115_ADDRESS);
    if (fd == -1) {
        printf("Failed to setup I2C\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int raw_reading = wiringPiI2CReadReg16(fd, 0x00);
        if (raw_reading == -1) {
            printf("Failed to read from I2C\n");
            return 1;
        }

        double concentration = COEF_A * pow(raw_reading, COEF_B) + COEF_C;

        FILE *file = fopen("co_log.txt", "a");
        if (file == NULL) {
            printf("Failed to open file\n");
            return 1;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(file, "%s,%f\n", time_str, concentration);
        fclose(file);

        delay(5000);
    }

    return 0;
}

