#define SPI_CHANNEL 0
#define SAMPLE_RATE 1000
#define SAMPLE_WINDOW 100
#define THRESHOLD 0.5
#define LED_PIN 27

FILE *file;

void handle_sigint(int sig) {
    fclose(file);
    digitalWrite(LED_PIN, LOW);
    exit(0);
}

float compute_rms(int *samples, int n) {
    long sum = 0;
    for (int i = 0; i < n; i++) {
        sum += samples[i] * samples[i];
    }
    return sqrt(sum / n);
}

int main() {
    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    if (wiringPiSPISetup(SPI_CHANNEL, SAMPLE_RATE) == -1) {
        printf("Failed to setup SPI\n");
        return 1;
    }

    pinMode(LED_PIN, OUTPUT);
    signal(SIGINT, handle_sigint);

    file = fopen("audio_events.csv", "w");
    if (file == NULL) {
        printf("Failed to open file\n");
        return 1;
    }

    int samples[SAMPLE_WINDOW];
    while (1) {
        for (int i = 0; i < 2; i++) {
            digitalWrite(8 + i, i == 0 ? HIGH : LOW);
            for (int j = 0; j < SAMPLE_WINDOW; j++) {
                samples[j] = wiringPiSPIDataRD(SPI_CHANNEL, (unsigned char*)&samples[j], 1);
                delay(1);
            }
            float rms = compute_rms(samples, SAMPLE_WINDOW);
