#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <wiringPi.h>
#include <Adafruit_ADS1015.h>

#define LED_PIN 17
#define BUFFER_SIZE 100
#define SAMPLE_RATE 10
#define THRESHOLD 50.0

Adafruit_ADS1115 ads;
float buffer[BUFFER_SIZE];
int bufferIndex = 0;

void handle_signal(int signum) {
    printf("Exiting...\n");
    digitalWrite(LED_PIN, LOW);
    ads.powerDown();
    exit(0);
}

float readSensor() {
    int16_t adc_raw = ads.readADC_SingleEnded(0);
    if (adc_raw == ADS1115_ERROR) {
        printf("Error reading from sensor\n");
        exit(1);
    }
    return ads.computeVolts(adc_raw);
}

float averageBuffer() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer[i];
    }
    return sum / BUFFER_SIZE;
}

int main() {
    signal(SIGINT, handle_signal);

    if (wiringPiSetup() == -1) {
        printf("Error setting up wiringPi\n");
        return 1;
    }

    pinMode(LED_PIN, OUTPUT);

    if (ads.begin(0x48) == false) {
        printf("Error initializing ADS1115\n");
        return 1;
    }

    ads.setRate(SAMPLE_RATE);

    while (1) {
        float current = readSensor();
        buffer[bufferIndex++] = current;
        if (bufferIndex == BUFFER_SIZE) {
            bufferIndex = 0;
        }

        float avg = averageBuffer();
        if (avg > THRESHOLD) {
            digitalWrite(LED_PIN, HIGH);
        } else {
            digitalWrite(LED_PIN, LOW);
        }

        delay(1000 / SAMPLE_RATE);
    }

    return 0;
}

