#include <wiringPiI2C.h>
#include <wiringPi.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>

#define SENSOR_ADDR 0x29
#define SLEEP_TIME 1
#define MAX_FAILURES 3

int fd;
int failures = 0;
FILE *file;

void cleanup(int signum) {
    fclose(file);
    close(fd);
    exit(0);
}

int main() {
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to setup wiringPi: %s\n", strerror(errno));
        return 1;
    }

    fd = wiringPiI2CSetup(SENSOR_ADDR);
    if (fd == -1) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    if (wiringPiI2CWriteReg8(fd, 0x80, 0x03) == -1) {
        fprintf(stderr, "Failed to initialize sensor: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    file = fopen("color_log.csv", "a+");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        int id = wiringPiI2CReadReg8(fd, 0x92);
        if (id != 0x44) {
            failures++;
            if (failures >= MAX_FAILURES) {
                fprintf(stderr, "Sensor ID mismatch, exiting...\n");
                cleanup(0);
            }
            fprintf(stderr, "Warning: Sensor ID mismatch, retrying...\n");
            continue;
        }

        int clear = wiringPiI2CReadReg8(fd, 0x94);
        int red = wiringPiI2CReadReg8(fd, 0x96);
        int green = wiringPiI2CReadReg8(fd, 0x98);
        int blue = wiringPiI2CReadReg8(fd, 0x9A);

        if (clear == -1 || red == -1 || green == -1 || blue == -1) {
            failures++;
            if (failures >= MAX_FAILURES) {
                fprintf(stderr, "Failed to read sensor data, exiting...\n");
                cleanup(0);
            }
            fprintf(stderr, "Warning: Failed to read sensor data, retrying...\n");
            continue;
        }

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(file, "%d-%02d-%02d %02d:%02d:%02d,%d,%d,%d,%d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, clear, red, green, blue);
        fflush(file);

        failures = 0;
        delay(SLEEP_TIME * 1000);
    }

    return 0;
}

