#define GPIO_BASE 8
#define GPIO_CE0 GPIO_BASE + 0
#define GPIO_MISO GPIO_BASE + 9
#define GPIO_MOSI GPIO_BASE + 10
#define GPIO_SCLK GPIO_BASE + 11

