#define MCP3008_CMD_SINGLE 0x01
#define MCP3008_CMD_DIFF 0x02
#define MCP3008_CMD_DUAL 0x03

int fd;

void cleanup(int signum) {
    close(fd);
    digitalWrite(GPIO_CE0, LOW);
    exit(0);
}

int main() {
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to setup wiringPi: %s\n", strerror(errno));
        return 1;
    }

    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "Failed to setup SPI: %s\n", strerror(errno));
        return 1;
