    fprintf(file, "Timestamp,Moisture1,Moisture2\n");

    while (1) {
        unsigned char data[3] = {MCP3008_CMD_BASE | MCP3008_CMD_SINGLE, 0x00, 0x00};
        unsigned char result[3] = {0, 0, 0};

        digitalWrite(GPIO_CE0, LOW);
