#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDR 0x5A // MLX90817 sensor address
#define LOG_FILE "pressure_log.csv"

int fd;
FILE *log;

void cleanup(int signum) {
    fflush(log);
    fclose(log);
    close(fd);
    exit(0);
}

int main() {
    unsigned char buffer[2];
    float pressure;
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    fprintf(log, "Timestamp,Pressure\n");
    fflush(log);

    while (1) {
        buffer[0] = 0x00; // Pressure command
        if (write(fd, buffer, 1) != 1) {
            perror("Failed to write to the i2c bus");
            return 1;
        }

        sleep(1);

        if (read(fd, buffer, 2) != 2) {
            perror("Failed to read from the i2c bus");
            continue;
        }

        pressure = (buffer[0] << 8 | buffer[1]) / 10.0; // Convert to kPa

        time(&now);
        timeinfo = gmtime(&now);
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", timeinfo);

        fprintf(log, "%s,%.2f\n", timestamp, pressure);
        fflush(log);
    }

    return 0;
}

