#define BMP_ADDR 0x77
#define FILE_NAME "pressure_log.txt"

Adafruit_ADS1115 ads(ADS_ADDR);
Adafruit_BMP280 bmp(BMP_ADDR);

void handle_sigint(int sig) {
    printf("\nCleaning up and exiting...\n");
    fclose(fopen(FILE_NAME, "w")); // Clear the log file
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    if (!ads.begin(SDA_GPIO, SCL_GPIO)) {
        printf("Failed to initialize ADS1115\n");
        return 1;
    }

    if (!bmp.begin()) {
        printf("Failed to initialize BMP280\n");
        return 1;
    }

    FILE *file = fopen(FILE_NAME, "w");
    if (file == NULL) {
        printf("Failed to open file\n");
        return 1;
    }

    while (1) {
        int16_t adc_value = ads.readADC_SingleEnded(0);
        float pressure = bmp.sealevelPressure(adc_value, 1013.25); // Assuming sea level pressure is 1013.25 hPa

        if (pressure < 0 || pressure > 100000) {
            printf("Invalid pressure reading: %f\n", pressure);
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        fprintf(file, "%s,%f\n", timestamp, pressure);
        fflush(file);

        sleep(1);
    }

    fclose(file);
    return 0;
}

