        data[1] = (TMP36_CHANNEL << 6); // Channel number
        data[2] = 0; // Dummy byte

        digitalWrite(GPIO_CE0, HIGH);
        wiringPiSPITransfer(SPI_CHANNEL, data, result, 3);
        digitalWrite(GPIO_CE0, LOW);

        int raw_temp = ((result[1] & 0x03) << 8) | result[2];
        float temp_celsius = raw_temp * 0.0048828125; // Convert to Celsius

        if (temp_celsius < -40 || temp_celsius > 125) {
            fprintf(stderr, "Temperature out of range: %.2f\n", temp_celsius);
            continue;
        }

        time_t now = time(NULL);
        fprintf(log_file, "%ld,%.2f\n", now, temp_celsius);
        fflush(log_file);

        sleep(1);
    }

    return 0;
}

