#include <unistd.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <signal.h>
#include <time.h>

#define SLAVE_ADDRESS 0x53  // Si1172 slave address
#define I2C_CHANNEL 1      // I2C channel

int fd;                    // I2C file descriptor
FILE *file;                // File for logging

void signal_handler(int signum) {
    fclose(file);
    close(fd);
    exit(0);
}

int main() {
    // Initialize I2C
    if (wiringPiSetup() == -1) {
        printf("Failed to initialize wiringPi: %s\n", strerror(errno));
        return 1;
    }

    fd = wiringPiI2CSetup(SLAVE_ADDRESS);
    if (fd == -1) {
        printf("Failed to initialize I2C: %s\n", strerror(errno));
        return 1;
    }

    // Open log file
    file = fopen("biometric_log.csv", "w");
    if (file == NULL) {
        printf("Failed to open file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        printf("Failed to register signal handler: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        int raw_hr, raw_spo2;
        int error_flag = 0;

        // Read raw HR and SpO2 values
        raw_hr = wiringPiI2CReadReg8(fd, 0x02);
        if (raw_hr == -1) {
            error_flag = 1;
        }

        raw_spo2 = wiringPiI2CReadReg8(fd, 0x03);
        if (raw_spo2 == -1) {
            error_flag = 1;
        }

        // Write to log file
        if (fprintf(file, "%ld,%d,%d,%d\n", time(NULL), raw_hr, raw_spo2, error_flag) < 0) {
            printf("Failed to write to file: %s\n", strerror(errno));
            return 1;
        }

        fflush(file);

        // Sleep for 1 second
        sleep(1);
    }

    return 0;
}

