#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_FULL_SCALE 1023
#define FLOW_SENSOR_MIN 0.0
#define FLOW_SENSOR_MAX 5.0
#define FILE_NAME "flow_log.csv"

int main(void)
{
    int fd;
    unsigned int adc_value;
    float flow_rate;
    char timestamp[20];
    FILE *file;

    if (wiringPiSetup() == -1)
    {
        fprintf(stderr, "Failed to setup wiringPi: %s\n", strerror(errno));
        return 1;
    }

    fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (fd == -1)
    {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return 1;
    }

    file = fopen(FILE_NAME, "w");
    if (file == NULL)
    {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        return 1;
    }

    while (1)
    {
        adc_value = wiringPiSPIDataRW(SPI_CHANNEL, 0);
        if (adc_value == -1)
        {
            fprintf(stderr, "Failed to read from SPI device: %s\n", strerror(errno));
            continue;
        }

        if (adc_value == 0 || adc_value == ADC_FULL_SCALE)
        {
            fprintf(stderr, "Sensor absent\n");
            continue;
        }

        flow_rate = (float)adc_value / ADC_FULL_SCALE * (FLOW_SENSOR_MAX - FLOW_SENSOR_MIN) + FLOW_SENSOR_MIN;

        if (flow_rate < FLOW_SENSOR_MIN || flow_rate > FLOW_SENSOR_MAX)
        {
            fprintf(stderr, "Out of range flow rate: %f\n", flow_rate);
            continue;
        }

        time_t rawtime;
        struct tm *timeinfo;

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(file, "%s.%06ld,%f\n", timestamp, rawtime % 1000000, flow_rate);
        fflush(file);

        delay(1000);
    }

    fclose(file);
    close(fd);

    return 0;
}

