    digitalWrite(MP1_CS, HIGH);
    digitalWrite(MP2_CS, HIGH);
    wiringPiSPIDataRW(SPI_CHANNEL, NULL, 0);
    wiringPiTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s <gain1> <gain2>\n", argv[0]);
        return 1;
    }

    gain1 = atoi(argv[1]);
    gain2 = atoi(argv[2]);

    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(MP1_CS, OUTPUT);
    pinMode(MP2_CS, OUTPUT);

    digitalWrite(MP1_CS, HIGH);
    digitalWrite(MP2_CS, HIGH);

    if (wiringPiSPISetup(SPI_CHANNEL, SPEED) == -1) {
        printf("Failed to setup SPI\n");
        return 1;
    }

    signal(SIGINT, cleanup);

    while (1) {
        unsigned char data[3] = {0x01, 0x80, 0x00};
        unsigned char result[3] = {0, 0, 0};

        digitalWrite(MP1_CS, LOW);
        wiringPiSPIDataRW(SPI_CHANNEL, data, 3);
        wiringPiSPIDataRW(SPI_CHANNEL, result, 3);
        digitalWrite(MP1_CS, HIGH);

        digitalWrite(MP2_CS, LOW);
        wiringPiSPIDataRW(SPI_CHANNEL, data, 3);
        wiringPiSPIDataRW(SPI_CHANNEL, result, 3);
        digitalWrite(MP2_CS, HIGH);

        printf("%d,%d\n", result[2], result[2]);
    }

    return 0;
}

