#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <wiringPiSPI.h>
#include <gpiod.h>

#define CHANNEL 0
#define SPEED 1000000
#define MOISTURE_CHIP "gpiochip0"
#define MOISTURE_LINE 24
#define FILE_NAME "moisture_log.txt"

int fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void signal_handler(int signum) {
    printf("Closing SPI handle and terminating driver library...\n");
    close(fd);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((fd = wiringPiSPISetup(CHANNEL, SPEED)) < 0) {
        perror("wiringPiSPISetup failed");
        return 1;
    }

    chip = gpiod_chip_open_by_name(MOISTURE_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name failed");
        return 1;
    }

    line = gpiod_chip_get_line(chip, MOISTURE_LINE);
    if (!line) {
        perror("gpiod_chip_get_line failed");
        return 1;
    }

    while (1) {
        int value;
        char buffer[50];
        time_t now = time(NULL);
        struct tm *ptm = gmtime(&now);

        value = wiringPiSPIDataRW(CHANNEL, 0);

