        root = json_object_new_object();
        json_object_object_add(root, "timestamp", json_object_new_string(timestamp));
        json_object_object_add(root, "percentage", json_object_new_double(percentage));

        json_object_array_add(array, root);

        if (fprintf(file, "%s\n", json_object_to_json_string(root)) < 0) {
            perror("Failed to write to file");
            return 1;
        }
        fflush(file);

        nanosleep(&ts, NULL);
    }

    json_object_put(root);
    json_object_put(array);

    fprintf(file, "]");
    fflush(file);
    fclose(file);

    digitalWrite(GPIO_LED, 0);
    mcp3008Cleanup();

    return 0;
}

