#define SPI_CHANNEL 0
#define SPI_SPEED 500000

int fd;

void send_email(char* email, char* msmtp_config) {
    char command[MAX_BUFFER];
    sprintf(command, "echo 'Plant moisture is below threshold' | msmtp --config=%s %s", msmtp_config, email);
    if (system(command) != 0) {
        fprintf(stderr, "Failed to send email\n");
    }
}

void handle_signal(int signum) {
    printf("Exiting...\n");
    close(fd);
    exit(0);
}

int main(int argc, char* argv[]) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to setup wiringPi: %s\n", strerror(errno));
        return 1;
    }

    fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (fd == -1) {
        fprintf(stderr, "Failed to setup SPI: %s\n", strerror(errno));
        return 1;
    }

    char data[3] = {1};  // Start bit
    data[1] = (ADC_CHANNEL << 6) | 0x80;  // Channel and start bit
    data[2] = 0x00;  // Dummy byte

    while (1) {
        wiringPiSPIDataRW(SPI_CHANNEL, data, 3);

        int raw_adc = ((data[1] & 0x03) << 8) | data[2];
        float voltage = raw_adc * 3.3 / 1023.0;
        float moisture_percent = 100.0 - (voltage * 100.0 / 3.3);

        time_t now = time(NULL);
