        if (file == NULL) {
            fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
            return 1;
        }

        fprintf(file, "%s, %.2f\n", timestamp, moisture_percent);
        fclose(file);

        if (moisture_percent < 30.0) {
            send_email(argv[1], argv[2]);
        }

        sleep(60);
    }

    return 0;
}

