#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define PCF8591_ADDR 0x48
#define AIN0_REG 0x40

int fd;

void sigint_handler(int sig) {
    printf("Exiting...\n");
    close(fd);
    exit(0);
}

int main() {
    unsigned char buf[2];
    int res;

    signal(SIGINT, sigint_handler);

    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    while (1) {
        buf[0] = AIN0_REG;
        res = write(fd, buf, 1);
        if (res != 1) {
            perror("Failed to write to the i2c bus");
            return 1;
        }

        usleep(100000);  // wait for 100ms

        res = read(fd, buf, 1);
        if (res != 1) {
            perror("Failed to read from the i2c bus");
            return 1;
        }

        printf("AIN0: %d\n", buf[0]);
    }

    return 0;
}

