    signal(SIGTERM, stop);

    while (1) {
        unsigned char data[3] = {0};
        unsigned char result[3] = {0};

        data[0] = 0x01;  // Start bit
        data[1] = 0x80 | ((ADC_CHANNEL & 0x07) << 3);  // Single-ended input, channel 0
        data[2] = 0x00;  // Dummy byte

        wiringPiSPIDataRW(ADC_CHANNEL, data, 3);

        int raw = ((data[0] & 0x03) << 8) | data[1];
        int value = (raw * 1023) / 1024;

        if (value < THRESHOLD) {
            digitalWrite(GPIO_PIN, HIGH);
            sleep(WATERING_TIME);
            digitalWrite(GPIO_PIN, LOW);

            time_t now = time(NULL);
