#define ADS1115_GAIN 4096  // PGA gain
#define HALL_EFFECT_CHANNEL 0  // AIN0
#define LED_PIN 17  // GPIO17

Adafruit_ADS1115 ads;
float threshold = 100.0;

void handle_signal(int signum) {
    digitalWrite(LED_PIN, LOW);
    ads.end();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc > 1) {
        threshold = atof(argv[1]);
    }

    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(LED_PIN, OUTPUT);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (!ads.begin(ADS1115_ADDR)) {
        printf("Failed to initialize ADS1115\n");
        return 1;
    }

    ads.setGain(ADS1115_GAIN);

    while (1) {
        int16_t value = ads.readADC_SingleEnded(HALL_EFFECT_CHANNEL);
        float field = value * 0.0001875;  // Convert to Gauss

        printf("Magnetic field: %.2f Gauss\n", field);

        if (field > threshold) {
            for (int i = 0; i < 20; i++) {
                digitalWrite(LED_PIN, HIGH);
                delay(50);
                digitalWrite(LED_PIN, LOW);
                delay(50);
            }
        }

        delay(100);
    }

    return 0;
}

