#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <wiringPi.h>
#include <mraa.h>
#include <MQTTClient.h>

#define HYSTERESIS_LOWER_LIMIT 30
#define HYSTERESIS_UPPER_LIMIT 35
#define SENSOR_CHANNEL 0
#define PUMP_GPIO 17
#define MQTT_PUMP_CONTROL_TOPIC "pump_control"
#define MQTT_SOIL_MOISTURE_TOPIC "soil_moisture"
#define MQTT_BROKER "tcp://mqtt.broker.url:1883"

mraa_spi_context spi;
MQTTClient client;

void handle_sigint(int sig) {
    syslog(LOG_INFO, "Received SIGINT, cleaning up...");
    digitalWrite(PUMP_GPIO, LOW);
    mraa_spi_stop(spi);
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    closelog();
    exit(0);
}

void handle_sigterm(int sig) {
    syslog(LOG_INFO, "Received SIGTERM, cleaning up...");
    digitalWrite(PUMP_GPIO, LOW);
    mraa_spi_stop(spi);
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    closelog();
    exit(0);
}

void on_message(void* context, char* topic, int topic_len,
                MQTTClient_message* message) {
    if (strcmp(topic, MQTT_PUMP_CONTROL_TOPIC) == 0) {
        if (strcmp((char*)message->payload, "pump_on") == 0) {
            digitalWrite(PUMP_GPIO, HIGH);
        } else if (strcmp((char*)message->payload, "pump_off") == 0) {
            digitalWrite(PUMP_GPIO, LOW);
        }
    }
    MQTTClient_freeMessage(&message);
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    openlog("soil_moisture_monitor", LOG_PID, LOG_USER);

    if (wiringPiSetup() == -1) {
        syslog(LOG_ERR, "Failed to setup wiringPi");
        return 1;
    }

    pinMode(PUMP_GPIO, OUTPUT);

    spi = mraa_spi_init(0);
    if (spi == NULL) {
        syslog(LOG_ERR, "Failed to initialize SPI");
        return 1;
    }

    mraa_spi_frequency(spi, 1000000);

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_create(&client, MQTT_BROKER, "SoilMoistureMonitor",
                      MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        return 1;
    }

    MQTTClient_subscribe(client, MQTT_PUMP_CONTROL_TOPIC, 0);

    while (1) {
        uint16_t adc_value = mraa_spi_read(spi, SENSOR_CHANNEL);
        if (adc_value == -1) {
            syslog(LOG_ERR, "Failed to read from ADC");
            return 1;
        }

        int moisture_percent = (adc_value / 1023.0) * 100;
        if (moisture_percent < HYSTERESIS_LOWER_LIMIT) {
            digitalWrite(PUMP_GPIO, HIGH);
        } else if (moisture_percent > HYSTERESIS_UPPER_LIMIT) {
            digitalWrite(PUMP_GPIO, LOW);
        }

        MQTTClient_message pub_msg = MQTTClient_message_initializer;
        pub_msg.payload = &moisture_percent;
        pub_msg.payloadlen = sizeof(moisture_percent);
        pub_msg.qos = 0;
        pub_msg.retained = 0;
        MQTTClient_publishMessage(client, MQTT_SOIL_MOISTURE_TOPIC,
                                  &pub_msg, NULL);

        sleep(60);
    }

    return 0;
}

