#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>
#include <signal.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 8

#define VDD 3.3
#define VREF 3.3

#define CS_PIN 8

int fd;

void handle_sigint(int sig) {
    printf("\nClosing SPI device...\n");
    close(fd);
    exit(0);
}

int main() {
    unsigned char data[2] = {0x01, 0x80};
    unsigned char result[2] = {0, 0};
    struct spi_ioc_transfer spi;
    int ret;

    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to setup wiringPi: %s\n", strerror(errno));
        return 1;
    }

    pinMode(CS_PIN, OUTPUT);
    digitalWrite(CS_PIN, HIGH);

    if ((fd = open(SPI_DEV, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return 1;
    }

    spi.tx_buf = (unsigned long)data;
    spi.rx_buf = (unsigned long)result;
    spi.len = 2;
    spi.delay_usecs = 0;
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = SPI_BITS;
    spi.cs_change = 0;

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) == -1) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        digitalWrite(CS_PIN, LOW);
        ret = ioctl(fd, SPI_IOC_MESSAGE(1), &spi);
        digitalWrite(CS_PIN, HIGH);

        if (ret == -1) {
            fprintf(stderr, "Failed to send SPI message: %s\n", strerror(errno));
            return 1;
        }

        unsigned int raw_value = (result[0] << 8) | result[1];
        float voltage = (float)raw_value * VDD / (float)((1 << 10) - 1);

        printf("Raw value: %d, Voltage: %.2fV\n", raw_value, voltage);

        usleep(500000);
    }

    return 0;
}

