#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <time.h>
#include <stdio.h>
#include <signal.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define GPIO_RELAY 17
#define GPIO_SENSOR 0
#define DEBOUNCE_DELAY 1000

int main() {
    // Setup GPIO and SPI
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to setup wiringPi\n");
        return 1;
    }
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "Failed to setup SPI\n");
        return 1;
    }
    pinMode(GPIO_RELAY, OUTPUT);
    pinMode(GPIO_SENSOR, INPUT);

    // Setup signal handler for SIGINT
    struct sigaction action;
    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    // Main loop
    while (1) {
        if (digitalRead(GPIO_SENSOR) == LOW) {
            delay(DEBOUNCE_DELAY);
            if (digitalRead(GPIO_SENSOR) == LOW) {
                digitalWrite(GPIO_RELAY, HIGH);
                log_event();
                delay(1000);
                digitalWrite(GPIO_RELAY, LOW);
            }
        }
        delay(100);
    }

    return 0;
}

void sigint_handler(int sig) {
    // Cleanup GPIO and SPI
    digitalWrite(GPIO_RELAY, LOW);
    close(SPI_CHANNEL);
    // Exit program
    exit(0);
}

void log_event() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    FILE *file = fopen("door_events.log", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    fprintf(file, "%d-%02d-%02d %02d:%02d:%02d - Door opened\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec);
    fclose(file);
}

