    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (fd == -1) {
        printf("Failed to setup SPI\n");
        return 1;
    }

    while (1) {
        int retry_count = 0;
        while (retry_count < 5) {
            unsigned char data[3] = {1, (8 + ADC_CHANNEL) << 4, 0};
            wiringPiSPIDataRW(SPI_CHANNEL, data, 3);

            int adc_value = (data[1] & 3) << 8 | data[2];
            if (adc_value >= 0 && adc_value < ADC_RESOLUTION) {
                float moisture_percentage = (float)adc_value / ADC_RESOLUTION * 100;

                time_t now = time(NULL);
