                    printf("Failed to open file\n");
                }

                delay(5000);
                break;
            } else {
                delay(1000 << retry_count);
                retry_count++;
            }
        }

        if (retry_count == 5) {
            FILE *file = fopen(FILE_NAME, "a");
            if (file != NULL) {
                fprintf(file, "%s, Error\n", timestamp);
                fclose(file);
            } else {
                printf("Failed to open file\n");
            }
        }
    }

    return 0;
}

