int read_ldr() {
    uint8_t tx[] = {1, (8 + ADC_CHANNEL) << 4, 0};
    uint8_t rx[3];

    if (write(fd, tx, sizeof(tx)) != sizeof(tx)) {
        perror("SPI write");
        return -1;
    }

    if (read(fd, rx, sizeof(rx)) != sizeof(rx)) {
        perror("SPI read");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

double read_ultrasonic() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(1);
    gpioWrite(TRIG_PIN, 0);

    int start = gpioRead(ECHO_PIN);
