    while (start == 0 && timeout-- > 0) {
        start = gpioRead(ECHO_PIN);
    }

    timeout = 1000000;
    while (end == 0 && timeout-- > 0) {
        end = gpioRead(ECHO_PIN);
    }

    if (timeout <= 0) {
        return -1;
    }

    return (double)(end - start) / 1000000 * 34000 / 2;
