    signal(SIGTERM, handle_signal);

    // Set up wiringPi
    wiringPiSetup();
    pinMode(MOTOR1_ENABLE, PWM_OUTPUT);
    pinMode(MOTOR2_ENABLE, PWM_OUTPUT);
    pinMode(MOTOR1_DIRECTION, OUTPUT);
    pinMode(MOTOR2_DIRECTION, OUTPUT);

    // Set up SPI
    fd = wiringPiSPISetup(ADC_MODE, ADC_SPEED);
    if (fd == -1) {
        printf("Failed to setup SPI\n");
        return 1;
    }

