        digitalWrite(MOTOR2_DIRECTION, speed1 < speed2);
        pwmWrite(MOTOR1_ENABLE, speed1);
        pwmWrite(MOTOR2_ENABLE, speed2);

        // Accelerate
        for (int i = 0; i <= 100; i++) {
            pwmWrite(MOTOR1_ENABLE, speed1 * i / 100);
            pwmWrite(MOTOR2_ENABLE, speed2 * i / 100);
            delay(ACCELERATION_TIME / 100);
        }

        // Hold
        delay(ACCELERATION_TIME);

        // Decelerate
        for (int i = 100; i >= 0; i--) {
            pwmWrite(MOTOR1_ENABLE, speed1 * i / 100);
            pwmWrite(MOTOR2_ENABLE, speed2 * i / 100);
            delay(DECELERATION_TIME / 100);
        }

        // Pause
        delay(PAUSE_TIME);

        // Reverse direction
        digitalWrite(MOTOR1_DIRECTION, !digitalRead(MOTOR1_DIRECTION));
        digitalWrite(MOTOR2_DIRECTION, !digitalRead(MOTOR2_DIRECTION));
