void cleanup(int signum) {
    bcm2835_gpio_write(GPIO_CE0, LOW);
    bcm2835_spi_end(spi_fd);
    fclose(log_file);
    exit(0);
}

int main() {
    struct timespec deadline;
    clock_gettime(CLOCK_MONOTONIC_RAW, &deadline);
    deadline.tv_nsec += 1000000;

    if (bcm2835_init() != 1) {
        printf("Failed to initialize BCM2835 library\n");
        return 1;
    }

    bcm2835_gpio_fsel(GPIO_CE0, BCM2835_GPIO_FSEL_OUTP);
    bcm2835_gpio_fsel(GPIO_MOSI, BCM2835_GPIO_FSEL_OUTP);
    bcm2835_gpio_fsel(GPIO_MISO, BCM2835_GPIO_FSEL_INPT);
    bcm2835_gpio_fsel(GPIO_SCLK, BCM2835_GPIO_FSEL_OUTP);

    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        printf("Failed to open SPI device\n");
        return 1;
    }

