#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <gpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_DELAY 0
#define SPI_MODE 0
#define ADC_CHANNELS 3

struct gpiod_chip *chip;
struct gpiod_line *cs_line;

void cleanup(int signum) {
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    int fd, ret;
    uint16_t raw[ADC_CHANNELS];
    uint8_t tx[3], rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = SPI_DELAY,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    cs_line = gpiod_chip_get_line(chip, 8);
    gpiod_line_request_output(cs_line, "adxl335", 0);

    fd = open(SPI_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    ret = ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret == -1) {
        perror("Failed to set SPI mode");
        return 1;
    }

    while (1) {
        gpiod_line_set_value(cs_line, 0);
        for (int i = 0; i < ADC_CHANNELS; i++) {
            tx[0] = 0x06 | ((i & 0x07) >> 2);
            tx[1] = ((i & 0x03) << 6);
            tx[2] = 0;
            ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
            if (ret < 1) {
                perror("Failed to read from SPI device");
                return 1;
            }
            raw[i] = (rx[1] << 8) | rx[2];
        }
        gpiod_line_set_value(cs_line, 1);

        // Convert raw values to g and print
        printf("X: %f g, Y: %f g, Z: %f g\n", raw[0]*3.3/1023, raw[1]*3.3/1023, raw[2]*3.3/1023);
        usleep(100000);
    }

    return 0;
}

