#include <stdio.h>
#include <stdlib.h>
#include <wiringPi.h>
#include <signal.h>

#define SENSOR1 4
#define SENSOR2 17
#define SENSOR3 27

#define HIGH 1
#define LOW 0

#define MIN_MAG_FIELD -100.0
#define MAX_MAG_FIELD 100.0

FILE *file;

void sigintHandler(int sig) {
    fclose(file);
    digitalWrite(SENSOR1, LOW);
    digitalWrite(SENSOR2, LOW);
    digitalWrite(SENSOR3, LOW);
    exit(0);
}

int main() {
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(SENSOR1, INPUT);
    pinMode(SENSOR2, INPUT);
    pinMode(SENSOR3, INPUT);

    signal(SIGINT, sigintHandler);

    file = fopen("magnetic_log.txt", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        return 1;
    }

    while (1) {
        int sensor1State = digitalRead(SENSOR1);
        int sensor2State = digitalRead(SENSOR2);
        int sensor3State = digitalRead(SENSOR3);

        if (sensor1State == -1 || sensor2State == -1 || sensor3State == -1) {
            fprintf(stderr, "Failed to read GPIO state\n");
            continue;
        }

        double sensor1Field = sensor1State == HIGH ? 3.3 : 0.0;
        double sensor2Field = sensor2State == HIGH ? 3.3 : 0.0;
        double sensor3Field = sensor3State == HIGH ? 3.3 : 0.0;

        if ((sensor1Field < MIN_MAG_FIELD || sensor1Field > MAX_MAG_FIELD) ||
            (sensor2Field < MIN_MAG_FIELD || sensor2Field > MAX_MAG_FIELD) ||
            (sensor3Field < MIN_MAG_FIELD || sensor3Field > MAX_MAG_FIELD)) {
            fprintf(stderr, "Warning: One or more magnetic field values out of range\n");
            continue;
        }

        fprintf(file, "%.2f,%.2f,%.2f\n", sensor1Field, sensor2Field, sensor3Field);
        fflush(file);

        delay(100);
    }

    return 0;
}

