#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <stdio.h>
#include <signal.h>
#include <time.h>

#define PUMP_GPIO 17
#define ADC_CHANNEL 0
#define ADC_SPEED 500000
#define ADC_MODE 0
#define THRESHOLD 30

int fd;

void handle_signal(int signum) {
    digitalWrite(PUMP_GPIO, LOW);
    FILE *log_file = fopen("watering.log", "a");
    time_t now = time(NULL);
    fprintf(log_file, "Program terminated at %s", ctime(&now));
    fclose(log_file);
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *log_file = fopen("watering.log", "w");
    time_t now = time(NULL);
    fprintf(log_file, "Program started at %s", ctime(&now));
    fclose(log_file);

    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(PUMP_GPIO, OUTPUT);
    digitalWrite(PUMP_GPIO, LOW);

    if ((fd = wiringPiSPISetup(ADC_CHANNEL, ADC_SPEED)) < 0) {
        printf("Failed to setup SPI\n");
        return 1;
    }

    while (1) {
        unsigned char data[3] = {0};
        data[0] = 0x01;  // Start bit
        data[1] = 0x80 | (ADC_CHANNEL << 6);  // Single-ended input, channel 0
        data[2] = 0x00;  // Dummy byte

        if (wiringPiSPIDataRW(ADC_CHANNEL, data, 3) == -1) {
            printf("Failed to read from ADC\n");
            continue;
        }

        int raw_value = (data[1] << 8) | data[2];
        int percentage = (raw_value / 1023.0) * 100;

        log_file = fopen("watering.log", "a");
        now = time(NULL);
        fprintf(log_file, "Moisture level: %d%% at %s", percentage, ctime(&now));
        fclose(log_file);

        if (percentage < THRESHOLD) {
            if (digitalRead(PUMP_GPIO) == LOW) {
                digitalWrite(PUMP_GPIO, HIGH);
                log_file = fopen("watering.log", "a");
                now = time(NULL);
                fprintf(log_file, "Pump turned on at %s", ctime(&now));
                fclose(log_file);
            }
        } else {
            if (digitalRead(PUMP_GPIO) == HIGH) {
                digitalWrite(PUMP_GPIO, LOW);
                log_file = fopen("watering.log", "a");
                now = time(NULL);
                fprintf(log_file, "Pump turned off at %s", ctime(&now));
                fclose(log_file);
            }
        }

        delay(60000);
    }

    return 0;
}

