#define TOPIC       "home/led_control"
#define QOS         0
#define TIMEOUT     10000L
#define GPIO_PIN    17

volatile MQTTClient client;
volatile int keepRunning = 1;

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        keepRunning = 0;
        MQTTClient_disconnect(client, 1000);
        digitalWrite(GPIO_PIN, LOW);
        MQTTClient_destroy(&client);
        exit(0);
    }
}

void onMessage(void *context, char *topicName, int topicLen, MQTTClient_message *message) {
    char* payload = (char*)message->payload;
    // Parse JSON and set LED state
    // This is a simplified example and assumes that the payload is a single boolean value
    if (strlen(payload) == 5 && strncmp(payload, "true", 4) == 0) {
        digitalWrite(GPIO_PIN, HIGH);
    } else if (strlen(payload) == 5 && strncmp(payload, "false", 5) == 0) {
        digitalWrite(GPIO_PIN, LOW);
    } else {
        fprintf(stderr, "[%ld] Invalid payload: %s\n", time(NULL), payload);
    }
}

int main(int argc, char* argv[]) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    MQTTClient_create(&client, ADDRESS, CLIENTID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if (wiringPiSetup() == -1) {
        fprintf(stderr, "[%ld] Failed to setup wiringPi\n", time(NULL));
        return 1;
    }

    pinMode(GPIO_PIN, OUTPUT);
    digitalWrite(GPIO_PIN, LOW);

    int retry_interval = 1;
    while (keepRunning) {
        if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "[%ld] Failed to connect to MQTT broker\n", time(NULL));
            sleep(retry_interval);
            retry_interval = retry_interval < 60 ? retry_interval * 2 : 60;
            continue;
        }

        MQTTClient_subscribe(client, TOPIC, QOS, onMessage, NULL);

        while (keepRunning && MQTTClient_waitForCompletion(client, TIMEOUT) != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "[%ld] Connection lost\n", time(NULL));
            break;
        }

        MQTTClient_unsubscribe(client, TOPIC);
        MQTTClient_disconnect(client, 1000);
        retry_interval = 1;
    }

    return 0;
}

