#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_SENSOR 17
#define GPIO_LED 18
#define DELAY_MS 100

struct gpiod_chip *chip;
struct gpiod_line *sensor_line, *led_line;

void cleanup(int signum) {
    gpiod_line_release(sensor_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    sensor_line = gpiod_chip_get_line(chip, GPIO_SENSOR);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get line for sensor\n");
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        fprintf(stderr, "Failed to get line for LED\n");
        return 1;
    }

    int ret = gpiod_line_request_input(sensor_line, "ky-038-sensor");
    if (ret < 0) {
        perror("Failed to request input for sensor");
        return 1;
    }

    ret = gpiod_line_request_output(led_line, "ky-038-led", 0);
    if (ret < 0) {
        perror("Failed to request output for LED");
        return 1;
    }

    while (1) {
        int value = gpiod_line_get_value(sensor_line);
        if (value < 0) {
            perror("Failed to read sensor value");
            return 1;
        }

        printf("Sound level: %d\n", value);

        if (value == 0) {
            gpiod_line_set_value(led_line, 1);
            usleep(1000000);
            gpiod_line_set_value(led_line, 0);
        }

        usleep(DELAY_MS * 1000);
    }

    return 0;
}

