#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    char buffer[100];
    FILE *file;
    int ret, val;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Opening chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        perror("Getting line");
        return 1;
    }

    ret = gpiod_line_request_falling_edge_events(line, "vibration-monitor");
    if (ret < 0) {
        perror("Requesting event");
        return 1;
    }

    file = fopen("/var/log/vibration_shutdown.log", "a");
    if (!file) {
        perror("Opening log file");
        return 1;
    }

    while (!stop) {
        ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            perror("Waiting for event");
            break;
        }

        ret = clock_gettime(CLOCK_REALTIME, &ts);
        if (ret < 0) {
            perror("Getting time");
            break;
        }

        val = gpiod_line_event_read_value(line);
        if (val < 0) {
            perror("Reading event");
            break;
        }

        sprintf(buffer, "%ld.%ld: Vibration detected\n", ts.tv_sec, ts.tv_nsec);

        fputs(buffer, file);
        fflush(file);

        printf("%s", buffer);

        system("sudo shutdown -h now");
    }

    fclose(file);

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

