#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <bmp280.h>

#define SDA_GPIO 2
#define SCL_GPIO 3

bmp280_t bmp280;

void handle_signal(int signum) {
    bmp280_close(&bmp280);
    fclose(altitude_log);
    exit(0);
}

int main() {
    FILE *altitude_log;
    struct timespec sleep_time = {5, 0};
    int32_t temp, press, alt;
    char timestamp[20];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (bmp280_init(&bmp280, BMP280_I2C_BUS, SDA_GPIO, SCL_GPIO) < 0) {
        fprintf(stderr, "Failed to initialize BMP280\n");
        return 1;
    }

    if ((altitude_log = fopen("altitude_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open altitude_log.txt\n");
        bmp280_close(&bmp280);
        return 1;
    }

    while (1) {
        if (bmp280_read_temp(&bmp280, &temp) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        if (bmp280_read_press(&bmp280, &press) < 0) {
            fprintf(stderr, "Failed to read pressure\n");
            continue;
        }

        alt = bmp280_calc_altitude(press);

        if (clock_gettime(CLOCK_REALTIME, &timestamp) == -1) {
            fprintf(stderr, "Failed to get timestamp\n");
            continue;
        }

        fprintf(altitude_log, "%s,%d\n", timestamp, alt);
        fflush(altitude_log);

        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

