#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define BUFFER_SIZE 120
#define GPIO_PINS 4
#define GPIO_PINS_ARRAY {8, 9, 10, 11}

float buffer[BUFFER_SIZE];
int buffer_index = 0;
FILE *file;

void signal_handler(int signum) {
    if (file != NULL) {
        fclose(file);
    }
    if (wiringPiSPIDataRW(SPI_CHANNEL, NULL, 0) == -1) {
        printf("Failed to close SPI device\n");
    }
    if (wiringPiSetupGpio() == -1) {
        printf("Failed to close GPIO driver\n");
    }
    exit(signum);
}

int main() {
    if (wiringPiSetupGpio() == -1) {
        printf("Failed to initialize GPIO driver\n");
        return 1;
    }

    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        printf("Failed to open SPI device\n");
        return 1;
    }

    int gpio_pins[] = GPIO_PINS_ARRAY;
    for (int i = 0; i < GPIO_PINS; i++) {
        pinMode(gpio_pins[i], OUTPUT);
        digitalWrite(gpio_pins[i], LOW);
    }

    if ((file = fopen("temp_log.dat", "wb+")) == NULL) {
        printf("Failed to open file\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        unsigned char data[3] = {1};  // Start bit
        unsigned char result[3] = {0};

        digitalWrite(gpio_pins[0], HIGH);  // CE0
        delay(1);

        if (wiringPiSPIDataRW(SPI_CHANNEL, data, 3) == -1) {
            printf("Failed to read from SPI device\n");
            digitalWrite(gpio_pins[0], LOW);
            continue;
        }

        digitalWrite(gpio_pins[0], LOW);

        float temp = ((result[1] & 3) << 8) + result[2];
        temp *= 0.0048828125;  // Convert to °C

        buffer[buffer_index++] = temp;
        if (buffer_index == BUFFER_SIZE) {
            buffer_index = 0;
        }

        printf("Temperature: %.2f °C\n", temp);

        if (file != NULL) {
            fseek(file, 0, SEEK_SET);
            fwrite(buffer, sizeof(float), BUFFER_SIZE, file);
            fflush(file);
        }

        delay(5000);
    }

    return 0;
}

