#define GPIO_PIN 17
#define GPIO_CHIP "gpiochip0"
#define POLL_INTERVAL 1

struct gpiod_chip *chip;
struct gpiod_line *line;

void cleanup(int signum) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    int ret = gpiod_line_request_input(line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to set line as input\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line\n");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        FILE *file = fopen("flame_events.log", "a");
        if (file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }

        fprintf(file, "%s,%d,%d\n", timestamp, GPIO_PIN, value);
        fclose(file);

        if (value == 1) {
            printf("Alarm: Flame detected\n");
        }

        sleep(POLL_INTERVAL);
    }

    return 0;
}

