#define IN2 18
#define ENA 27

#define RAIN_THRESHOLD 5

volatile sig_atomic_t stop;

void handle_signal(int signum) {
    stop = 1;
}

int main() {
    FILE *file;
    int fd, value;
    double rain_level;
    struct timespec ts;
    char buffer[256];

    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to setup wiringPi: %s\n", strerror(errno));
        return 1;
    }

    if ((fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED)) < 0) {
        fprintf(stderr, "Failed to setup SPI: %s\n", strerror(errno));
        return 1;
    }

    if ((file = fopen("rain_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        return 1;
    }

    pinMode(IN1, OUTPUT);
    pinMode(IN2, OUTPUT);
    pinMode(ENA, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetClock(2);
    pwmSetRange(255);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        uint8_t data[3] = {MCP3008_CMD, 0x00, 0x00};
        uint8_t result[3] = {0, 0, 0};

        if (wiringPiSPIDataRW(SPI_CHANNEL, data, 3) == -1) {
