        }

        value = ((data[1] & 0x03) << 8) | data[2];
        rain_level = (value / 1023.0) * 100;  // Convert to percentage

        clock_gettime(CLOCK_REALTIME, &ts);
        sprintf(buffer, "%ld.%ld,%f\n", ts.tv_sec, ts.tv_nsec, rain_level);

        if (fputs(buffer, file) == EOF) {
            fprintf(stderr, "Failed to write to file: %s\n", strerror(errno));
            break;
        }

        fflush(file);

        if (rain_level > RAIN_THRESHOLD) {
            digitalWrite(IN1, LOW);
            digitalWrite(IN2, HIGH);
            pwmWrite(ENA, 150);
            delay(3000);
        } else {
            digitalWrite(IN1, HIGH);
            digitalWrite(IN2, LOW);
            pwmWrite(ENA, 150);
            delay(3000);
        }

        delay(1000);
    }

    pwmWrite(ENA, 0);
    fclose(file);
    wiringPiSPIDestroy(fd);

    return 0;
}

