    signal(SIGTERM, handle_signal);

    while (1) {
        int value = digitalRead(GPIO_PIN);

        if (value == -1) {
            if (retries < MAX_RETRIES) {
                printf("Failed to read GPIO pin, retrying...\n");
                retries++;
                delay(1000);
                continue;
            } else {
                printf("Failed to read GPIO pin after %d retries\n", MAX_RETRIES);
                break;
            }
        }

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
