#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <wiringPiSPI.h>
#include <gpiod.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MLX91211_VREF 5.0
#define ADC_RESOLUTION 1024
#define ADC_VREF 3.3
#define ADC_CHANNEL 0
#define GPIO_LINE 8

volatile sig_atomic_t stop;

void intHandler(int signum) {
    stop = 1;
}

int main() {
    struct timespec ts = {0, 100000000};
    char buffer[256];
    FILE *file;
    int adcValue;
    double current;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get line");
        return 1;
    }

    ret = gpiod_line_request_output(line, "mlx91211", 0);
    if (ret < 0) {
        perror("Failed to set line as output");
        return 1;
    }

    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) < 0) {
        perror("Failed to setup SPI");
        return 1;
    }

    signal(SIGINT, intHandler);

    file = fopen("current_log.txt", "a");
    if (!file) {
        perror("Failed to open file");
        return 1;
    }

    while (!stop) {
        adcValue = wiringPiSPIDataRW(SPI_CHANNEL, 0, 0, 0);
        if (adcValue < 0) {
            perror("Failed to read from SPI");
            return 1;
        }

        current = (double)adcValue * MLX91211_VREF / ADC_RESOLUTION;
        if (current < 0 || current > 5.0) {
            fprintf(stderr, "Warning: measured voltage is outside 0-5V\n");
            continue;
        }

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        strftime(buffer, sizeof(buffer), "%F %T", &tm);
        fprintf(file, "%s %.2fA\n", buffer, current);
        fflush(file);

        nanosleep(&ts, NULL);
    }

    fclose(file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

