    if (!chip) {
        perror("Open chip failed");
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    line2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!line1 || !line2) {
        perror("Get line failed");
        return 1;
    }

    int ret = gpiod_line_request_input(line1, "my_app");
    if (ret < 0) {
        perror("Request input failed");
        return 1;
    }

    ret = gpiod_line_request_input(line2, "my_app");
    if (ret < 0) {
        perror("Request input failed");
        return 1;
