#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <wiringPi.h>

#define PIR_PIN 17
#define DEBOUNCE_DELAY 200
#define POLL_DELAY 50

int running = 1;

void handle_signal(int signum) {
    running = 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    openlog("security_cam", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Starting security camera");

    if (wiringPiSetupGpio() == -1) {
        syslog(LOG_ERR, "Failed to initialize wiringPi");
        return 1;
    }

    pinMode(PIR_PIN, INPUT);
    pullUpDnControl(PIR_PIN, PUD_DOWN);

    syslog(LOG_INFO, "Ready to monitor motion");

    while (running) {
        int current_state = digitalRead(PIR_PIN);
        int last_state = current_state;
        int debounce_count = 0;

        while (debounce_count < DEBOUNCE_DELAY / POLL_DELAY) {
            if (current_state != last_state) {
                debounce_count = 0;
            } else {
                debounce_count++;
            }

            last_state = current_state;
            delay(POLL_DELAY);
            current_state = digitalRead(PIR_PIN);
        }

        if (current_state == HIGH) {
            syslog(LOG_INFO, "Motion detected");

            time_t rawtime;
            struct tm *timeinfo;
            char buffer[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S.jpg", timeinfo);

            char path[100] = "/home/pi/security_cam/";
            strncat(path, buffer, sizeof(path) - strlen(path) - 1);

            pid_t pid = fork();

            if (pid == 0) {
                execl("/usr/bin/libcamera-still", "libcamera-still", "-o", path, NULL);
                syslog(LOG_ERR, "Failed to capture image");
                exit(1);
            } else if (pid < 0) {
                syslog(LOG_ERR, "Failed to fork process");
            } else {
                int status;
                waitpid(pid, &status, 0);

                if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
                    syslog(LOG_INFO, "Image captured successfully");
                } else {
                    syslog(LOG_ERR, "Failed to capture image");
                }
            }
        }
    }

    closelog();
    return 0;
}

