#include <sys/socket.h>
#include <signal.h>

#define CAMERA_DEVICE "/dev/video0"
#define PACKET_SIZE 65000
#define NUM_BUFFERS 4

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s <target IP> <target port>\n", argv[0]);
        return 1;
    }

    // Open the camera device
    int fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open camera device");
        return 1;
    }

    // Configure the camera
    // ...

    // Allocate and map the buffers
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        return 1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Failed to query buffer");
            return 1;
        }

        void *mem = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
