    if (gpio == TILT_UP_PIN && level == 0) {
        tilt = (tilt + POS_STEP <= MID_POS + POS_RANGE) ? tilt + POS_STEP : MID_POS + POS_RANGE;
    } else if (gpio == TILT_DOWN_PIN && level == 0) {
        tilt = (tilt - POS_STEP >= MID_POS - POS_RANGE) ? tilt - POS_STEP : MID_POS - POS_RANGE;
    } else if (gpio == PAN_LEFT_PIN && level == 0) {
        pan = (pan - POS_STEP >= MID_POS - POS_RANGE) ? pan - POS_STEP : MID_POS - POS_RANGE;
    } else if (gpio == PAN_RIGHT_PIN && level == 0) {
        pan = (pan + POS_STEP <= MID_POS + POS_RANGE) ? pan + POS_STEP : MID_POS + POS_RANGE;
