        } else if (gpioRead(DOWN_BUTTON) == 0) {
            pan = (pan - PWM_STEP > PWM_MIN) ? pan - PWM_STEP : PWM_MIN;
        }

        if (gpioRead(LEFT_BUTTON) == 0) {
            tilt = (tilt - PWM_STEP > PWM_MIN) ? tilt - PWM_STEP : PWM_MIN;
        } else if (gpioRead(RIGHT_BUTTON) == 0) {
            tilt = (tilt + PWM_STEP < PWM_MAX) ? tilt + PWM_STEP : PWM_MAX;
        }

