#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_SERVO 17
#define TILT_SERVO 18
#define PWM_FREQ 50
#define NEUTRAL_DUTYCYCLE 1500000
#define STEP_SIZE 5
#define MIN_ANGLE 0
#define MAX_ANGLE 180

void cleanup(int signum);

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        exit(1);
    }

    gpioSetSignalFunc(SIGINT, cleanup);

    gpioSetPWMfrequency(PAN_SERVO, PWM_FREQ);
    gpioSetPWMfrequency(TILT_SERVO, PWM_FREQ);

    gpioSetPWMdutycycle(PAN_SERVO, NEUTRAL_DUTYCYCLE);
    gpioSetPWMdutycycle(TILT_SERVO, NEUTRAL_DUTYCYCLE);

    int pan_angle = 90;
    int tilt_angle = 90;

    while (1) {
        char c = getchar();

        if (c == 'q') {
            break;
        }

        if (c == 'a' && pan_angle > MIN_ANGLE) {
            pan_angle -= STEP_SIZE;
        } else if (c == 'd' && pan_angle < MAX_ANGLE) {
            pan_angle += STEP_SIZE;
        } else if (c == 'w' && tilt_angle > MIN_ANGLE) {
            tilt_angle -= STEP_SIZE;
        } else if (c == 's' && tilt_angle < MAX_ANGLE) {
            tilt_angle += STEP_SIZE;
        }

        int pan_dutycycle = NEUTRAL_DUTYCYCLE + (pan_angle * 1000);
        int tilt_dutycycle = NEUTRAL_DUTYCYCLE + (tilt_angle * 1000);

        gpioPWM(PAN_SERVO, PWM_FREQ, pan_dutycycle);
        gpioPWM(TILT_SERVO, PWM_FREQ, tilt_dutycycle);

        usleep(100000);
    }

    cleanup(0);

    return 0;
}

void cleanup(int signum) {
    gpioSetPWMdutycycle(PAN_SERVO, NEUTRAL_DUTYCYCLE);
    gpioSetPWMdutycycle(TILT_SERVO, NEUTRAL_DUTYCYCLE);

    gpioTerminate();

    exit(0);
}

