#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

#define OLED_ADDR 0x3C // I2C address of the SSD1306 OLED display
#define THERMAL_ZONE "/sys/class/thermal/thermal_zone0/temp"
#define STAT_FILE "/proc/stat"

int fd;

void sigint_handler(int sig) {
    printf("Exiting...\n");
    digitalWrite(1, LOW); // Turn off the OLED display
    close(fd); // Close the I2C file descriptor
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler); // Set up the SIGINT handler

    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to setup wiringPi: %s\n", strerror(errno));
        return 1;
    }

    fd = wiringPiI2CSetup(OLED_ADDR);
    if (fd == -1) {
        fprintf(stderr, "Failed to setup I2C: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        FILE *thermal_file = fopen(THERMAL_ZONE, "r");
        if (thermal_file == NULL) {
            fprintf(stderr, "Failed to open thermal zone file: %s\n", strerror(errno));
            return 1;
        }

        float cpu_temp;
        fscanf(thermal_file, "%f", &cpu_temp);
        fclose(thermal_file);

        FILE *stat_file = fopen(STAT_FILE, "r");
        if (stat_file == NULL) {
            fprintf(stderr, "Failed to open stat file: %s\n", strerror(errno));
            return 1;
        }

        unsigned long user, nice, system, idle;
        fscanf(stat_file, "cpu %lu %lu %lu %lu", &user, &nice, &system, &idle);
        fclose(stat_file);

        // Calculate CPU usage percentage
        unsigned long total = user + nice + system + idle;
        unsigned long cpu_usage = (total - idle) * 100 / total;

        // Write to the OLED display
        char buffer[32];
        sprintf(buffer, "CPU Temp: %.2f C\nCPU Usage: %lu %%", cpu_temp, cpu_usage);
        int result = wiringPiI2CWrite(fd, buffer);
        if (result == -1) {
            fprintf(stderr, "Failed to write to I2C: %s\n", strerror(errno));
            return 1;
        }

        delay(1000); // Wait for 1 second
    }

    return 0;
}

