#include <gpiod.h>
#include <wiringPiI2C.h>

#define GPIO_LINE 17
#define I2C_BUS 1
#define I2C_ADDR 0x27

volatile sig_atomic_t stop;

void interrupt_handler(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i2c_fd;
    int count = 0;
    int flow_rate, total_volume = 0;

    signal(SIGINT, interrupt_handler);
    signal(SIGTERM, interrupt_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    if (gpiod_line_request_falling_edge_events(line, "water-flow-sensor") < 0) {
        perror("Failed to request GPIO line");
        return 1;
    }

    i2c_fd = wiringPiI2CSetup(I2C_ADDR);
    if (i2c_fd < 0) {
        perror("Failed to setup I2C");
        return 1;
    }

    while (!stop) {
        struct timespec ts = {.tv_sec = 0, .tv_nsec = 100000000L};
        int event_count = gpiod_line_event_wait(line, &ts);

        if (event_count < 0) {
            perror("Failed to wait for GPIO event");
            return 1;
        }

        if (event_count > 0) {
            count++;
            flow_rate = count;
            total_volume += flow_rate;
            count = 0;

            printf("Current flow rate: %d ml/s, Total volume: %d ml\n", flow_rate, total_volume);

            if (count % 10 == 0) {
                int result = wiringPiI2CWrite(i2c_fd, flow_rate);
                if (result < 0) {
                    perror("Failed to write to I2C");
                    return 1;
                }
            }
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

