#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <signal.h>

#define GPIO_BASE 0x3F200000
#define GPIO_LENGTH 0x10000
#define GPIO_EXPORT "/sys/class/gpio/export"
#define GPIO_UNEXPORT "/sys/class/gpio/unexport"
#define GPIO_DIRECTION "/sys/class/gpio/gpio%d/direction"
#define GPIO_VALUE "/sys/class/gpio/gpio%d/value"

volatile unsigned int *gpio;

void cleanup(int signum) {
    for (int i = 17; i <= 20; i++) {
        printf("Unexporting GPIO %d\n", i);
        FILE *f = fopen(GPIO_UNEXPORT, "w");
        fprintf(f, "%d", i);
        fclose(f);
    }
    munmap((void *)gpio, GPIO_LENGTH);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);

    int fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("Failed to open /dev/mem");
        return 1;
    }

    gpio = (unsigned int *)mmap(NULL, GPIO_LENGTH, PROT_READ | PROT_WRITE, MAP_SHARED, fd, GPIO_BASE);
    if (gpio == MAP_FAILED) {
        perror("Failed to map GPIO memory");
        return 1;
    }

    for (int i = 17; i <= 20; i++) {
        printf("Exporting GPIO %d\n", i);
        FILE *f = fopen(GPIO_EXPORT, "w");
        fprintf(f, "%d", i);
        fclose(f);

        char direction_path[32];
        sprintf(direction_path, GPIO_DIRECTION, i);
        printf("Setting direction of GPIO %d\n", i);
        f = fopen(direction_path, "w");
        fprintf(f, "out");
        fclose(f);
    }

    while (1) {
        for (int i = 17; i <= 20; i++) {
            gpio[i] = 0;
            usleep(800);
            gpio[i] = 1;
        }
        for (int i = 20; i >= 17; i--) {
            gpio[i] = 0;
            usleep(800);
            gpio[i] = 1;
        }
    }

    return 0;
}

