    printf("Exiting...\n");
    close(fd);
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    // Stub for proprietary initialization sequence
    printf("Stub for proprietary initialization sequence\n");

    // Verify sensor model ID
    int sensor_id = i2c_smbus_read_byte_data(fd, SENSOR_ID);
    if (sensor_id != SENSOR_ID) {
        printf("Invalid sensor model ID: 0x%x\n", sensor_id);
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *ptm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", ptm);

        // Stub for reading distance measurements
        int distance = i2c_smbus_read_word_data(fd, 0x00);
        if (distance < 0) {
            perror("Failed to read distance");
            return 1;
        }

        printf("%s: %d\n", timestamp, distance);
        usleep(100000); // Sleep for 100ms
    }

    return 0;
}

