#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>

#define MLX75031_I2C_ADDR 0x33 // I2C address of the sensor
#define MLX75031_REG_TOF 0x00 // Register for Time-of-Flight data

int fd; // I2C file descriptor
FILE *file; // File descriptor for the log file

void handle_sigint(int sig) {
    printf("\nClosing I2C handle and log file...\n");
    close(fd);
    fclose(file);
    exit(0);
}

int main() {
    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        printf("Failed to initialize wiringPi\n");
        return 1;
    }

    // Open I2C bus
    fd = wiringPiI2CSetup(MLX75031_I2C_ADDR);
    if (fd == -1) {
        printf("Failed to open I2C bus\n");
        return 1;
    }

    // Open log file
    file = fopen("depth_log.csv", "a+");
    if (file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    // Check if file is empty and write CSV header
    fseek(file, 0, SEEK_END);
    if (ftell(file) == 0) {
        fprintf(file, "Timestamp,Distance\n");
    }

    // Main loop
    while (1) {
        int distance;
        time_t now = time(NULL);

        // Read distance data
        distance = wiringPiI2CReadReg8(fd, MLX75031_REG_TOF);
        if (distance == -1) {
            printf("Failed to read distance data, retrying...\n");
            fprintf(file, "%ld,%d\n", now, -1);
            fflush(file);
            continue;
        }

        // Write distance data to log file
        fprintf(file, "%ld,%d\n", now, distance);
        fflush(file);

        // Sleep for 100ms
        delay(100);
    }

    return 0;
}

