#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>

#define SENSOR_ADDR 0x60 // replace with your sensor's I2C address
#define SAMPLE_RATE 500 // sample rate in milliseconds

int fd;
FILE *file;

void sigint_handler(int sig) {
    fflush(file);
    fclose(file);
    close(fd);
    exit(0);
}

int main() {
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to setup wiringPi: %s\n", strerror(errno));
        return 1;
    }

    fd = wiringPiI2CSetup(SENSOR_ADDR);
    if (fd == -1) {
        fprintf(stderr, "Failed to setup I2C: %s\n", strerror(errno));
        return 1;
    }

    if (wiringPiI2CWriteReg8(fd, 0x02, 0x01) == -1) { // write to command register to initialize sensor
        fprintf(stderr, "Failed to initialize sensor: %s\n", strerror(errno));
        return 1;
    }

    file = fopen("biometric_log.txt", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        int prox, light;
        time_t now = time(NULL);
        struct tm *ptm = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%FT%T%z", ptm);

        prox = wiringPiI2CReadReg8(fd, 0x03); // replace with your proximity register
        light = wiringPiI2CReadReg8(fd, 0x04); // replace with your light register

        if (prox == -1 || light == -1) {
            fprintf(stderr, "Failed to read from sensor: %s\n", strerror(errno));
            continue;
        }

        fprintf(file, "%s,prox=%d,light=%d\n", timestamp, prox, light);
        fflush(file);

        delay(SAMPLE_RATE);
    }

    return 0;
}

