#include <pigpio.h>
#include <stdio.h>
#include <time.h>
#include <signal.h>

#define TRIG 17
#define ECHO 27
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define WATER_DISTANCE 15

FILE *logFile;

void signalHandler(int signum) {
    fclose(logFile);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    gpioSetMode(TRIG, PI_OUTPUT);
    gpioSetMode(ECHO, PI_INPUT);

    logFile = fopen("distance_log.txt", "w");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        gpioTrigger(TRIG, 10, 1); // Send 10 us trigger pulse

        int startTime = gpioTick();
        if (startTime < 0) {
            fprintf(stderr, "Failed to get start time\n");
            return 1;
        }

        int echoTime = gpioWaitForEdge(ECHO, PI_TIMEOUT, startTime + 300000); // Wait up to 30 ms for echo
        if (echoTime < 0) {
            fprintf(logFile, "%d: Timeout\n", (int)time(NULL));
            continue;
        }

        int distance = (echoTime / 1000) * 340 / 2; // Calculate distance in cm

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(logFile, "%d: Invalid distance: %d cm\n", (int)time(NULL), distance);
            continue;
        }

        fprintf(logFile, "%d: %d cm", (int)time(NULL), distance);

        if (distance < WATER_DISTANCE) {
            fprintf(logFile, " - Time to water the plant!");
        }

        fprintf(logFile, "\n");

        time_t sleepTime = distance / 10; // Sleep for distance/10 seconds
        if (sleepTime < 1) sleepTime = 1; // Minimum sleep time is 1 second

        time_t start = time(NULL);
        while (time(NULL) - start < sleepTime) {
            gpioDelay(1); // Delay for 1 microsecond
        }
    }

    return 0;
}

