#include <fcntl.h>
#include <unistd.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDR 0x53
#define PROXIMITY_REG 0x00

volatile sig_atomic_t running = 1;

void sig_handler(int signum) {
    running = 0;
}

int main() {
    int file_i2c;
    int length;
    unsigned char buffer[2];
    char filename[20];
    FILE *file_csv;
    struct timespec ts;
    time_t t;
    struct tm *tm;
    char timestamp[50];

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    file_i2c = open(I2C_DEVICE, O_RDWR);
    if (file_i2c < 0) {
        fprintf(stderr, "Failed to open the i2c bus\n");
        return 1;
    }

    if (ioctl(file_i2c, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access or talk to slave\n");
        return 1;
    }

    sprintf(filename, "heartrate.csv");
    file_csv = fopen(filename, "a");
    if (file_csv == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        return 1;
    }

    while (running) {
        length = 1;
        if (write(file_i2c, &PROXIMITY_REG, length) != length) {
            fprintf(stderr, "Failed to write to the i2c bus\n");
            return 1;
        }

        length = 2;
        if (read(file_i2c, buffer, length) != length) {
            fprintf(stderr, "Failed to read from the i2c bus\n");
            return 1;
        }

        t = time(NULL);
        tm = localtime(&t);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

        fprintf(file_csv, "%s,%d\n", timestamp, buffer[1] * 256 + buffer[0]);
        fflush(file_csv);

        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += 100;
        while (clock_nanosleep(CLOCK_REALTIME, TIMER_ABSTIME, &ts, NULL) && running) {
            // loop until the next 100ms
        }
    }

    fclose(file_csv);
    close(file_i2c);

    return 0;
}

