#define GPIO_DEVICE "/dev/gpiochip0"
#define GPIO_LINE_1 17
#define GPIO_LINE_2 18
#define FILE_NAME "obstacle_log.txt"
#define DELAY 100000 // 100ms

struct gpiod_chip *chip;
struct gpiod_line *line1, *line2;
FILE *file;

void signal_handler(int signum) {
    fclose(file);
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_DEVICE);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_LINE_1);
    line2 = gpiod_chip_get_line(chip, GPIO_LINE_2);
    if (!line1 || !line2) {
        perror("Failed to get GPIO line");
        return 1;
    }

    int ret = gpiod_line_request_input(line1, "obstacle_detector");
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        return 1;
    }

    ret = gpiod_line_request_input(line2, "obstacle_detector");
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        return 1;
    }

    file = fopen(FILE_NAME, "w");
    if (!file) {
        perror("Failed to open file");
        return 1;
    }

    while (1) {
        int value1 = gpiod_line_get_value(line1);
        int value2 = gpiod_line_get_value(line2);
        if (value1 < 0 || value2 < 0) {
            fprintf(stderr, "Failed to read GPIO line\n");
        } else {
            time_t t = time(NULL);
            fprintf(file, "%ld,%d,%d\n", t, value1, value2);
            fflush(file);
        }
        usleep(DELAY);
    }

    return 0;
}

