#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x70 // I2C address of the sensor
#define GPIO_PIN 17 // GPIO pin number
#define FILE_NAME "distance_log.txt" // Log file name

int fd; // I2C file descriptor

void signal_handler(int signum) {
    printf("Exiting...\n");
    digitalWrite(GPIO_PIN, LOW);
    close(fd);
    exit(0);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    // Set up GPIO pin
    pinMode(GPIO_PIN, OUTPUT);

    // Initialize I2C
    fd = wiringPiI2CSetup(I2C_ADDR);
    if (fd == -1) {
        printf("Failed to setup I2C\n");
        return 1;
    }

    // Open log file
    FILE *file = fopen(FILE_NAME, "w");
    if (file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    while (1) {
        // Read distance from sensor
        int distance = wiringPiI2CReadReg8(fd, 0x00);
        if (distance == -1) {
            printf("Failed to read from sensor\n");
            return 1;
        }

        // Get current time
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        // Write to log file
        fprintf(file, "%s,%d\n", timestamp, distance);
        fflush(file);

        // Turn on LED if distance is below 20 cm
        if (distance < 20) {
            digitalWrite(GPIO_PIN, HIGH);
        } else {
            digitalWrite(GPIO_PIN, LOW);
        }

        // Wait for 100 ms
        delay(100);
    }

    return 0;
}

