#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>

#define I2C_BUS "/dev/i2c-1"
#define WHO_AM_I_REG 0x0F
#define DISTANCE_REG 0x30
#define DEFAULT_THRESHOLD 100
#define GPIO_LINE 17

int fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void cleanup(int signum) {
    gpiod_line_release(line);
    close(fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    if (argc > 1) {
        threshold = atoi(argv[1]);
    }

    signal(SIGINT, cleanup);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, WHO_AM_I_REG) < 0) {
        perror("Failed to select I2C slave");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    while (1) {
        char buf[2];
        if (read(fd, buf, 2) != 2) {
            perror("Failed to read from I2C bus");
            return 1;
        }

        int distance = (buf[0] << 8) | buf[1];
        printf("Distance: %d mm\n", distance);

        if (distance < threshold) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        FILE *log = fopen("tof_log.txt", "a");
        if (log) {
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            fprintf(log, "%d-%02d-%02d %02d:%02d:%02d, %d mm\n",
                    tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                    tm->tm_hour, tm->tm_min, tm->tm_sec, distance);
            fclose(log);
        }

        usleep(50000);
    }

    return 0;
}

