#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define OMRON_ADDR 0x28 // Omron B5L-LD50-07050 I2C address
#define CYCLE_DELAY 100000 // 100ms delay between cycles
#define SAMPLE_COUNT 10 // Number of samples per cycle
#define DISTANCE_THRESHOLD 1000 // Threshold for intrusion detection

int fd;
FILE *logFile;

void handle_sigint(int sig) {
    fclose(logFile);
    close(fd);
    exit(0);
}

int main() {
    unsigned char command[2] = {0x00, 0x03}; // Command frame
    unsigned char response[15]; // Response frame
    int i, j;
    float avgDistance;
    time_t rawtime;

    signal(SIGINT, handle_sigint);

    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, OMRON_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    logFile = fopen("intrusion_log.txt", "w");
    if (logFile == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        avgDistance = 0;
        for (i = 0; i < SAMPLE_COUNT; i++) {
            if (write(fd, command, 2) != 2) {
                perror("Failed to write to the i2c bus");
                return 1;
            }

            usleep(10000); // Wait for at least 10ms

            if (read(fd, response, 15) != 15) {
                perror("Failed to read from the i2c bus");
                return 1;
            }

            if (response[0] != 0x42) {
                fprintf(stderr, "Invalid response header\n");
                return 1;
            }

            avgDistance += (response[11] << 8) | response[12];
        }

        avgDistance /= SAMPLE_COUNT;

        if (avgDistance < DISTANCE_THRESHOLD) {
            time(&rawtime);
            fprintf(logFile, "%s: Average distance: %.2f mm\n", ctime(&rawtime), avgDistance);
            fflush(logFile);
        }

        usleep(CYCLE_DELAY);
    }

    return 0;
}

