#include <signal.h>
#include <Adafruit_VL53L0X.h>

#define I2C_BUS "/dev/i2c-1"
#define ADDR 0x29 // VL53L0X address

Adafruit_VL53L0X sensor = Adafruit_VL53L0X();

void cleanup(int signum) {
    sensor.close();
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    int file_i2c = open(I2C_BUS, O_RDWR);
    if (file_i2c < 0) {
        fprintf(stderr, "Failed to open the i2c bus: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(file_i2c, I2C_SLAVE, ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access or talk to slave: %s\n", strerror(errno));
        return 1;
    }

    if (!sensor.begin(file_i2c)) {
        fprintf(stderr, "Failed to initialize the VL53L0X sensor\n");
        return 1;
    }

    uint8_t id = sensor.getModelID();
    if (id != 0xEA) {
        fprintf(stderr, "Model ID mismatch: %02X\n", id);
        return 1;
    }

    while (1) {
        if (sensor.isReady()) {
            uint16_t distance = sensor.readRangeContinuousMillimeters();
            if (distance >= 0) {
                time_t now = time(NULL);
                struct tm *timeinfo = localtime(&now);
                printf("%d-%02d-%02d %02d:%02d:%02d Distance: %d mm\n",
                       timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
