#include <time.h>

#define TRIG 17
#define ECHO 18

void sig_handler(int signum) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    gpioSetMode(TRIG, PI_OUTPUT);
    gpioSetMode(ECHO, PI_INPUT);

    while (1) {
        gpioWrite(TRIG, 1);
        gpioDelay(10); // 10 us
        gpioWrite(TRIG, 0);

        unsigned int start_tick, end_tick;
        while (gpioRead(ECHO) == 0) {
            start_tick = gpioTick();
            if (start_tick > 200000) { // 200 ms
                printf("Timeout waiting for echo start\n");
                break;
            }
        }

        while (gpioRead(ECHO) == 1) {
            end_tick = gpioTick();
            if (end_tick > 220000) { // 220 ms
                printf("Timeout waiting for echo end\n");
                break;
            }
        }

        if (end_tick > start_tick) {
            float distance = (end_tick - start_tick) * 1.0 / 1000000.0 * 34000.0 / 2.0; // speed of sound is 340 m/s, divide by 2 to account for round trip
            if (distance > 0 && distance < 38) {
                time_t now = time(NULL);
                printf("%ld: %.2f cm\n", now, distance);
            } else {
                printf("Invalid pulse duration\n");
            }
        }

        gpioDelay(1000000); // 1 second
    }

    return 0;
}

