#define GPIO_LINE 17
#define THRESHOLD 1000 // 1 meter in mm
#define MAGIC_WORD 0xDEADBEEF
#define UART_DEVICE "/dev/serial0"

struct gpiod_chip *chip;
struct gpiod_line *line;

void handle_signal(int signum) {
    gpiod_line_release(line);
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    int err = gpiod_line_request_output(line, "alert_led", 0);
    if (err) {
        perror("Failed to request GPIO line");
        return 1;
    }

    // Initialize UART
    int uart_fd = uart_init(UART_DEVICE);
    if (uart_fd < 0) {
        perror("Failed to initialize UART");
        return 1;
    }

    while (1) {
        uint32_t magic;
        uint16_t data[64];

        // Read magic word
        if (read(uart_fd, &magic, sizeof(magic)) != sizeof(magic)) {
            perror("Failed to read magic word");
            return 1;
        }

        if (magic != MAGIC_WORD)
            continue;

        // Read data
        if (read(uart_fd, data, sizeof(data)) != sizeof(data)) {
            perror("Failed to read data");
            return 1;
        }

        // Check for intrusion
        for (int i = 0; i < 64; i++) {
            if (data[i] < THRESHOLD) {
                // Intrusion detected
                time_t now = time(NULL);
                struct tm *timeinfo = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

                FILE *file = fopen("intrusion_log.csv", "a");
                if (file) {
                    fprintf(file, "%s,%d\n", timestamp, data[i]);
                    fclose(file);
                }

                // Activate alert LED
                gpiod_line_set_value(line, 1);
                usleep(2000000);
                gpiod_line_set_value(line, 0);

                break;
            }
        }
    }

    return 0;
}

