#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_BUZZER 18
#define GPIO_SENSOR 17
#define DELAY 100000 // 100ms

struct gpiod_chip *chip;
struct gpiod_line *buzzer, *sensor;
FILE *file;

void signal_handler(int signum) {
    gpiod_line_release(buzzer);
    gpiod_line_release(sensor);
    gpiod_chip_close(chip);
    fclose(file);
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Open chip failed");
        return -1;
    }

    buzzer = gpiod_chip_get_line(chip, GPIO_BUZZER);
    sensor = gpiod_chip_get_line(chip, GPIO_SENSOR);
    if (!buzzer || !sensor) {
        perror("Get line failed");
        return -1;
    }

    int ret = gpiod_line_request_output(buzzer, "buzzer", 0);
    if (ret < 0) {
        perror("Request line as output failed");
        return -1;
    }

    ret = gpiod_line_request_input(sensor, "sensor");
    if (ret < 0) {
        perror("Request line as input failed");
        return -1;
    }

    file = fopen("obstacle_log.txt", "w");
    if (!file) {
        perror("Open file failed");
        return -1;
    }

    int prev_state = 1; // Assume no obstacle initially
    while (1) {
        int state = gpiod_line_get_value(sensor);
        if (state < 0) {
            perror("Read line value failed");
            return -1;
        }

        if (state != prev_state) {
            time_t now = time(NULL);
            char *timestamp = ctime(&now);
            timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
            fprintf(file, "%s: %s\n", timestamp, state == 0 ? "Obstacle detected" : "Obstacle removed");
            fflush(file);

            if (state == 0) {
                gpiod_line_set_value(buzzer, 1);
            } else {
                gpiod_line_set_value(buzzer, 0);
            }

            prev_state = state;
        }

        usleep(DELAY);
    }

    return 0;
}

