#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x42 // replace with your sensor's address
#define GPIO_PIN 17
#define FILE_NAME "distance_log.txt"
#define ALERT_DISTANCE 10.0 // in cm

int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void cleanup(int signum) {
    close(i2c_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    // Set GPIO line as output
    if (gpiod_line_request_output(line, "alert", 0) < 0) {
        perror("Failed to set GPIO line as output");
        return 1;
    }

    // Open log file
    FILE *file = fopen(FILE_NAME, "w");
    if (!file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        char buf[2];
        float distance;
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

        // Read distance from sensor
        if (read(i2c_fd, buf, 2) != 2) {
            perror("Failed to read from the i2c bus");
            return 1;
        }

        // Convert to float (in cm)
        distance = (buf[0] << 8 | buf[1]) / 10.0;

        // Log distance and timestamp
        fprintf(file, "%s,%f\n", timestamp, distance);
        fflush(file);

        // Check if distance is below alert threshold
        if (distance < ALERT_DISTANCE) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        sleep(0.1); // 100ms delay
    }

    return 0;
}

