    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    if (vl53l1x_Init(&sensor, I2C_BUS, SENSOR_ADDR) != VL53L1X_ERROR_NONE) {
        printf("Failed to initialize sensor\n");
        return 1;
    }

    logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    // Check if file is empty, if so, write the header
    fseek(logFile, 0, SEEK_END);
    if (ftell(logFile) == 0) {
        fprintf(logFile, "timestamp,distance_mm\n");
    }

    while (1) {
        uint16_t distance = vl53l1x_get_distance(&sensor);
        if (distance == VL53L1X_ERROR_NONE) {
            time_t now = time(NULL);
            fprintf(logFile, "%ld,%d\n", now, distance);
            fflush(logFile);

            if (distance < 300) {
                printf("STOP\n");
            } else if (distance < 600) {
                printf("APPROACH\n");
            } else if (distance < 1200) {
                printf("SLOW\n");
            } else {
                printf("CLEAR\n");
            }
        } else {
            printf("Failed to read distance\n");
