#include <stdint.h>
#include <time.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MLX75030_ADDR 0x33 // MLX75030 I2C address
#define CMD_MEASURE 0x20 // Measure command

int file_i2c;

void signal_handler(int signum) {
    printf("Closing I2C device and exiting...\n");
    close(file_i2c);
    exit(0);
}

int main() {
    // Register signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    if ((file_i2c = open(I2C_DEVICE, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(file_i2c, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access or talk to slave\n");
        return 1;
    }

    // Open file for logging
    FILE *file = fopen("distance_log.csv", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        // Write command to start measurement
        uint8_t cmd = CMD_MEASURE;
        if (write(file_i2c, &cmd, 1) != 1) {
            fprintf(stderr, "Failed to write to I2C device\n");
            return 1;
        }

        // Wait for measurement to complete
        usleep(100000); // 100ms delay

        // Read 2-byte distance value
        uint8_t buf[2];
        if (read(file_i2c, buf, 2) != 2) {
            fprintf(stderr, "Failed to read from I2C device\n");
            return 1;
        }

        // Convert to centimeters and append to log file
        uint16_t distance = (buf[0] << 8) | buf[1];
        time_t timestamp = time(NULL);
        fprintf(file, "%ld,%d\n", timestamp, distance);
        fflush(file);

        // Wait before next measurement
        usleep(1000000); // 100ms delay
    }

    return 0;
}

