    fclose(log_file);
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    int value1, value2, prev_value1 = 0, prev_value2 = 0;
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    line1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    line2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);

    gpiod_line_request_input(line1, "proximity_sensor");
    gpiod_line_request_input(line2, "proximity_sensor");

    log_file = fopen("proximity_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening file!\n");
        return 1;
    }

    while (1) {
        usleep(10000);

        value1 = gpiod_line_get_value(line1);
        value2 = gpiod_line_get_value(line2);

        if ((value1 != prev_value1) || (value2 != prev_value2)) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            if (value1 == 1 && prev_value1 == 0) {
                fprintf(log_file, "%s, Sensor 1, DETECTED\n", buffer);
            } else if (value1 == 0 && prev_value1 == 1) {
                fprintf(log_file, "%s, Sensor 1, CLEARED\n", buffer);
            }

            if (value2 == 1 && prev_value2 == 0) {
                fprintf(log_file, "%s, Sensor 2, DETECTED\n", buffer);
            } else if (value2 == 0 && prev_value2 == 1) {
                fprintf(log_file, "%s, Sensor 2, CLEARED\n", buffer);
            }

            fflush(log_file);

            prev_value1 = value1;
            prev_value2 = value2;
        }
    }

    return 0;
}

