#define I2C_DEVICE "/dev/i2c-1"
#define SLAVE_ADDRESS 0x53 // This is the slave address of the TDK CH-101 sensor
#define MEAS_STATUS_REG 0x00
#define DISTANCE_REG 0x02
#define TIMEOUT_MS 50
#define SLEEP_MS 500
#define LOG_FILE "distance_log.csv"

int i2c_fd;
FILE *log_file;

void cleanup(int signum) {
    fflush(log_file);
    close(i2c_fd);
    fclose(log_file);
    exit(0);
}

int main() {
    int ret;
    char buffer[2];
    struct timespec timeout;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, SLAVE_ADDRESS);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    while (1) {
        buffer[0] = MEAS_STATUS_REG;
        ret = write(i2c_fd, buffer, 1);
        if (ret != 1) {
            fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
            continue;
        }

        timeout.tv_sec = 0;
        timeout.tv_nsec = TIMEOUT_MS * 1000000;
        nanosleep(&timeout, NULL);

        ret = read(i2c_fd, buffer, 2);
        if (ret != 2) {
            fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
            continue;
        }

        fprintf(log_file, "%s,%d\n", time(NULL), buffer[1] << 8 | buffer[0]);
        fflush(log_file);

        timeout.tv_sec = 0;
        timeout.tv_nsec = SLEEP_MS * 1000000;
        nanosleep(&timeout, NULL);
    }

    return 0;
}

