    int ret;

    signal(SIGINT, cleanup);

    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    while (1) {
        for (int i = 0; i < 3; i++) {
            ret = read(fd, buffer, 2);
            if (ret == 2)
                break;
            usleep(10000); // 10ms delay
        }

        if (ret != 2) {
            perror("Failed to read from the i2c bus");
            return 1;
        }

        unsigned int distance = (buffer[0] << 8) | buffer[1];
        printf("%ld: %d\n", (long)time(NULL), distance);
