#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <wiringPi.h>
#include <vl53l1x_api.h>

#define GPIO_PIN_BUZZER 22
#define I2C_BUS 1
#define DISTANCE_THRESHOLD 100
#define DELAY_MS 500

VL53L1X_Dev_t dev;

void handle_sigint(int sig) {
    printf("\nCleaning up resources and exiting...\n");
    VL53L1X_DeInit(&dev);
    digitalWrite(GPIO_PIN_BUZZER, LOW);
    exit(0);
}

int main() {
    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(GPIO_PIN_BUZZER, OUTPUT);
    digitalWrite(GPIO_PIN_BUZZER, LOW);

    signal(SIGINT, handle_sigint);

    if (VL53L1X_Init(&dev, I2C_BUS) != VL53L1X_ERROR_NONE) {
        printf("Failed to initialize VL53L1X sensor\n");
        return 1;
    }

    if (VL53L1X_SetDistanceMode(&dev, VL53L1X_DISTANCEMODE_CONTINUOUS) != VL53L1X_ERROR_NONE) {
        printf("Failed to set distance mode\n");
        return 1;
    }

    while (1) {
        uint32_t distance;
        if (VL53L1X_GetDistance(&dev, &distance) != VL53L1X_ERROR_NONE) {
            printf("Failed to read distance\n");
            continue;
        }

        if (distance < DISTANCE_THRESHOLD) {
            digitalWrite(GPIO_PIN_BUZZER, HIGH);
        } else {
            digitalWrite(GPIO_PIN_BUZZER, LOW);
        }

        delay(DELAY_MS);
    }

    return 0;
}

