#include <pigpio.h>
#include <stdio.h>
#include <time.h>
#include <signal.h>

#define TRIG 23
#define ECHO 24
#define SERVO 17

volatile sig_atomic_t stop;

void sig_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    gpioSetMode(TRIG, PI_OUTPUT);
    gpioSetMode(ECHO, PI_INPUT);
    gpioSetMode(SERVO, PI_OUTPUT);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    FILE *logfile = fopen("sensor_data.log", "a");
    if (logfile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (!stop) {
        gpioWrite(TRIG, 1);
        gpioDelay(10); // 10 us
        gpioWrite(TRIG, 0);

        int start_tick = gpioTick();
        while (gpioRead(ECHO) == 0 && gpioTick() - start_tick < 500000) {} // 50 ms timeout

        if (gpioRead(ECHO) == 0) {
            fprintf(stderr, "Sensor timeout\n");
            continue;
        }

        int echo_tick = gpioTick();
        while (gpioRead(ECHO) == 1 && gpioTick() - echo_tick < 500000) {} // 50 ms timeout

        if (gpioRead(ECHO) == 1) {
            fprintf(stderr, "Sensor timeout\n");
            continue;
        }

        int travel_time = gpioTick() - start_tick;
        int distance = (travel_time / 1000) / 58; // cm

        if (distance < 2 || distance > 400) {
            fprintf(stderr, "Invalid distance: %d cm\n", distance);
            continue;
        }

        int angle = (distance - 2) * 180 / 398 + 90; // map 2 cm to -90°, 400 cm to +90°

        gpioServo(SERVO, angle);

        time_t now = time(NULL);
        fprintf(logfile, "%ld, %d cm, %d°\n", now, distance, angle);
        fflush(logfile);

        gpioDelay(2000000); // 200 ms delay
    }

    gpioServo(SERVO, 0); // stop servo

    fclose(logfile);

    gpioTerminate();

    return 0;
}

