#include <pigpio.h>
#include <vl53l1x.h>
#include <mqueue.h>

#define GPIO_BUZZER 23
#define I2C_BUS 1
#define QUEUE_NAME "/my_queue"
#define QUEUE_SIZE 10
#define MESSAGE_SIZE sizeof(uint16_t)

VL53L1X_Dev_t dev;
mqd_t queue;

void signal_handler(int signum) {
    mq_close(queue);
    mq_unlink(QUEUE_NAME);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (VL53L1X_init(&dev, I2C_BUS) < 0) {
        fprintf(stderr, "Failed to initialize VL53L1X sensor\n");
        return 1;
    }

    if ((queue = mq_open(QUEUE_NAME, O_CREAT | O_RDWR, 0666, NULL)) == -1) {
        perror("Failed to create message queue");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        uint16_t distance;
        if (VL53L1X_read(&dev, &distance) < 0) {
            fprintf(stderr, "Failed to read from VL53L1X sensor\n");
            continue;
        }

        if (mq_send(queue, (char*)&distance, MESSAGE_SIZE, 0) == -1) {
            perror("Failed to send message");
            continue;
        }

        if (distance < 100) {
            gpioWrite(GPIO_BUZZER, 1);
        } else {
            gpioWrite(GPIO_BUZZER, 0);
        }

        gpioDelay(1000000); // Delay for 1 second
    }

    return 0;
}

