#include <pigpio.h>
#include <signal.h>
#include <stdio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

#define SPEED_OF_SOUND 34300 // in cm/s
#define TIMEOUT_US 1000000 // 1 second

volatile unsigned int startTick = 0;
volatile unsigned int endTick = 0;

void echoCallback(int gpio, int level, uint32_t tick) {
    if (level == PI_ON) {
        startTick = tick;
    } else if (level == PI_OFF) {
        endTick = tick;
    }
}

void alarmHandler(int signum) {
    unsigned int distance = (endTick - startTick) * SPEED_OF_SOUND / 2 / 1000000;

    if (distance < 2 || distance > 400) {
        printf("Invalid reading: %d cm\n", distance);
        return;
    }

    printf("Distance: %d cm\n", distance);

    if (distance < 30) {
        gpioWrite(BUZZER_PIN, 1);
    } else {
        gpioWrite(BUZZER_PIN, 0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        return 1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        return 1;
    }

    if (gpioSetISRFunc(ECHO_PIN, EITHER_EDGE, 100, &echoCallback) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        return 1;
    }

    signal(SIGALRM, alarmHandler);
    alarm(100);

    while (1) {
        gpioWrite(TRIGGER_PIN, 1);
        time_sleep(0.00001); // 10us
        gpioWrite(TRIGGER_PIN, 0);

        sleep(1);
    }

    gpioTerminate();
    return 0;
}

