#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SAMPLING_RATE 5000 // in microseconds
#define TIMEOUT 60000 // in microseconds
#define NOISE_FILTER 100 // in microseconds
#define MAX_DISTANCE 30000 // in microseconds

struct gpiod_chip *chip;
struct gpiod_line *trig_line, *echo_line;
FILE *log_file;

void handle_signal(int signum) {
    fclose(log_file);
    gpiod_line_release(echo_line);
    gpiod_line_release(trig_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main(void) {
    struct timespec ts = {0, SAMPLING_RATE * 1000};
    unsigned long rising_tick, falling_tick, duration;
    char buf[50];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);

    if (!trig_line || !echo_line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    if (gpiod_line_request_output(trig_line, "hcsr04", 0) < 0) {
        perror("Failed to request TRIG line as output");
        return 1;
    }

    if (gpiod_line_request_input(echo_line, "hcsr04") < 0) {
        perror("Failed to request ECHO line as input");
        return 1;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        if (gpiod_line_set_value(trig_line, 1) < 0) {
            perror("Failed to set TRIG line value");
            return 1;
        }
        nanosleep(&ts, NULL);

        if (gpiod_line_set_value(trig_line, 0) < 0) {
            perror("Failed to reset TRIG line value");
            return 1;
        }

        if (gpiod_line_event_wait(echo_line, NULL) < 0) {
            perror("Failed to wait for ECHO line event");
            return 1;
        }

        struct gpiod_line_event evt;
        if (gpiod_line_event_read(echo_line, &evt) < 0) {
            perror("Failed to read ECHO line event");
            return 1;
        }

        if (evt.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            rising_tick = evt.timestamp.tv_nsec / 1000;
        } else if (evt.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            falling_tick = evt.timestamp.tv_nsec / 1000;
            duration = falling_tick - rising_tick;

            if (duration < NOISE_FILTER || duration > MAX_DISTANCE) {
                fprintf(stderr, "Warning: Rejected measurement due to noise or timeout\n");
                continue;
            }

            sprintf(buf, "%ld %ld\n", rising_tick, falling_tick);
            fputs(buf, log_file);
            fflush(log_file);

            printf("%ld %ld\n", rising_tick, falling_tick);
        }
    }

    return 0;
}

