#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <vl53l1x.h>

#define SDA_PIN 2
#define SCL_PIN 3
#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24
#define PWM_PIN 18
#define HYSTERESIS 10

int fd;

void sigint_handler(int sig) {
    printf("Exiting...\n");
    digitalWrite(SHUTDOWN_PIN, LOW);
    close(fd);
    exit(0);
}

int main() {
    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(SDA_PIN, OUTPUT);
    pinMode(SCL_PIN, OUTPUT);
    pinMode(SHUTDOWN_PIN, OUTPUT);
    pinMode(INTERRUPT_PIN, INPUT);
    pinMode(PWM_PIN, PWM_OUTPUT);

    digitalWrite(SHUTDOWN_PIN, HIGH);

    fd = wiringPiI2CSetup(VL53L1X_DEFAULT_I2C_ADDR);
    if (fd == -1) {
        printf("Failed to setup I2C\n");
        return 1;
    }

    if (VL53L1X_Init(fd) != 0) {
        printf("Failed to initialize VL53L1X\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        int distance = VL53L1X_GetDistance(fd);
        if (distance == -1) {
            printf("Failed to read distance\n");
            return 1;
        }

        if (distance < 50) {
            pwmWrite(PWM_PIN, 1024);
            printf("Gate opened at %d cm\n", distance);
        } else if (distance > 60 + HYSTERESIS) {
            pwmWrite(PWM_PIN, 0);
            printf("Gate closed at %d cm\n", distance);
        }

        delay(500);
    }

    return 0;
}

