#include <stdio.h>
#include <time.h>
#include <signal.h>

#define TRIG 17
#define ECHO 18
#define SPEED_OF_SOUND 34300 // in cm/s
#define MAX_DISTANCE 40000 // in cm
#define MIN_DISTANCE 200 // in cm

volatile sig_atomic_t stop;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    FILE *file = fopen("distance_log.txt", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    gpioSetMode(TRIG, PI_OUTPUT);
    gpioSetMode(ECHO, PI_INPUT);

    while (!stop) {
        gpioWrite(TRIG, 0);
        gpioDelay(100); // 100 us
        gpioWrite(TRIG, 1);
        gpioDelay(10); // 10 us
        gpioWrite(TRIG, 0);

        unsigned int start_tick = gpioTick();
        while (gpioRead(ECHO) == 0 && gpioTick() - start_tick < 310000) {
            // wait for echo to go high
        }

        unsigned int echo_tick = gpioTick();
        while (gpioRead(ECHO) == 1 && gpioTick() - echo_tick < 310000) {
            // measure echo pulse width
        }

        unsigned int distance_tick = gpioTick() - echo_tick;
        if (distance_tick > 310000) {
            fprintf(stderr, "Timeout\n");
            continue;
        }

        int distance = (distance_tick * SPEED_OF_SOUND) / 2000000; // convert to cm
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Out of range\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        fprintf(file, "%s,%d\n", timestamp, distance);
        fflush(file);

        gpioDelay(1000000); // 1 second
    }

    fclose(file);
    gpioTerminate();
    return 0;
}

