#include <pigpio.h>
#include <stdio.h>
#include <signal.h>
#include <time.h>

#define TRIG 17
#define ECHO 18

FILE *file;

void alertFunc(int gpio, int level, uint32_t tick)
{
    static uint32_t startTick;
    uint32_t endTick;
    uint32_t diff;
    double distance;
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    if (level == 0) // Rising edge
    {
        startTick = tick;
    }
    else // Falling edge
    {
        endTick = tick;
        diff = endTick - startTick;
        distance = (double)diff / 1000000.0 * 34000.0 / 2.0; // Speed of sound is 340m/s, divide by 2 to account for round trip

        if (distance > 1.0 && distance < 400.0) // Check if distance is within a sane range
        {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(buffer, sizeof(buffer), "%d-%m-%Y %H:%M:%S", timeinfo);
            fprintf(file, "%s, %.2f m\n", buffer, distance);
            fflush(file);
        }
    }
}

void sigintHandler(int sig)
{
    gpio_set_alert_func(ECHO, NULL);
    fclose(file);
    gpio_write(TRIG, 0);
    gpio_term_store(0);
    exit(0);
}

int main(int argc, char *argv[])
{
    if (gpio_init_library() < 0)
    {
        printf("Failed to initialize library\n");
        return 1;
    }

    file = fopen("distance_log.txt", "w");
    if (file == NULL)
    {
        printf("Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, sigintHandler);
    signal(SIGTERM, sigintHandler);

    gpio_set_mode(TRIG, PI_OUTPUT);
    gpio_set_mode(ECHO, PI_INPUT);

    gpio_write(TRIG, 0);

    gpio_set_alert_func(ECHO, alertFunc);

    while (1)
    {
        gpio_write(TRIG, 1);
        time_sleep(0.00001); // 10µs
        gpio_write(TRIG, 0);
        time_sleep(1); // Wait for next measurement
    }

    return 0;
}

