#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <signal.h>
#include <systemd/sd-journal.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x29
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 27

int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void cleanup(int signum) {
    sd_journal_printv("Exiting on signal %d", signum);
    close(i2c_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        sd_journal_printv("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        sd_journal_printv("Failed to acquire bus access or talk to slave");
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        sd_journal_printv("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        sd_journal_printv("Failed to get GPIO line");
        return 1;
    }

    gpiod_line_request_output(line, "vl53l1x", 1);

    while (1) {
        gpiod_line_set_value(line, 1);
        usleep(10000);
        gpiod_line_set_value(line, 0);

        int distance;
        if (read(i2c_fd, &distance, sizeof(distance)) < 0) {
            sd_journal_printv("Failed to read from I2C device");
            continue;
        }

        sd_journal_printv("Timestamp: %ld, Distance: %d mm, Status: %s",
                          time(NULL), distance, distance > 0 ? "Success" : "Error");

        usleep(100000);
    }

    return 0;
}

