#define SENSOR_ADDR 0x29 // VL53L1X I2C address
#define GPIO_PIN 24 // GPIO pin number
#define LOG_FILE "gate_log.txt"

int fd;

void sig_handler(int signum) {
    printf("Caught signal %d\n", signum);
    close(fd);
    fclose(fopen(LOG_FILE, "a"));
    exit(0);
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    fd = wiringPiI2CSetup(SENSOR_ADDR);
    if (fd == -1) {
        printf("Failed to setup I2C\n");
        return 1;
    }

    FILE *file = fopen(LOG_FILE, "w");
    if (file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    pinMode(GPIO_PIN, OUTPUT);
    digitalWrite(GPIO_PIN, LOW);

    while (1) {
        int distance = wiringPiI2CReadReg16(fd, 0x00);
        if (distance == -1) {
            printf("Failed to read from sensor\n");
            return 1;
        }

        time_t now = time(NULL);
        fprintf(file, "%s: Sensor reading: %d cm\n", ctime(&now), distance / 10);
        fflush(file);

        if (distance / 10 < 20) {
            digitalWrite(GPIO_PIN, HIGH);
            fprintf(file, "%s: Gate opened\n", ctime(&now));
            fflush(file);
        } else {
            digitalWrite(GPIO_PIN, LOW);
            fprintf(file, "%s: Gate closed\n", ctime(&now));
            fflush(file);
        }

        delay(100);
    }

    return 0;
}

