#include <pigpio.h>
#include <stdio.h>
#include <signal.h>
#include <time.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

volatile sig_atomic_t flag = 0;
volatile unsigned int pulse_width = 0;
volatile unsigned int new_pulse = 0;

void sigint_handler(int signum) {
    flag = 1;
}

void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        gpioSetTimerFunc(ECHO_PIN, 30000, echo_callback);
    } else {
        pulse_width = tick;
        new_pulse = 1;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioSetTimerFunc(ECHO_PIN, 30000, echo_callback);

    FILE *file = fopen("distance_log.csv", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        return 1;
    }

    fprintf(file, "Timestamp,Distance (cm),Servo Angle (deg)\n");
    fflush(file);

    while (!flag) {
        if (new_pulse) {
            new_pulse = 0;

            double distance = (double)pulse_width / 58.82; // Convert to cm

            if (distance < 2 || distance > 400) {
                distance = -1.0;
                gpioServo(SERVO_PIN, 9000); // Set servo to 90 degrees
            }

            time_t now = time(NULL);
            fprintf(file, "%ld,%.2f,%d\n", now, distance, gpioGetServoPulsewidth(SERVO_PIN));
            fflush(file);
        }
    }

    gpioServo(SERVO_PIN, 0); // Stop servo
    fclose(file);

    gpioTerminate();

    return 0;
}

