#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

#define SENSOR_ADDR 0x29
#define BUFFER_SIZE 10
#define WARNING_LED 17
#define RANGE_PERIOD 50

int i2c_fd;
int buffer[BUFFER_SIZE];
int buffer_index = 0;

void handle_sigint(int sig) {
    digitalWrite(WARNING_LED, LOW);
    close(i2c_fd);
    exit(0);
}

