    signal(SIGINT, handle_sigint);

    if (wiringPiSetupGpio() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(WARNING_LED, OUTPUT);

    i2c_fd = wiringPiI2CSetup(SENSOR_ADDR);
