#include <wiringPi.h>
#include <wiringPiI2C.h>

#define GPIO_PIN 27
#define I2C_ADDR 0x53
#define THRESHOLD 1000
#define FILE_NAME "proximity.log"

int fd;
FILE *file;

void interruptHandler(void) {
    // Read the 16-bit proximity value
    int proximity = wiringPiI2CReadReg16(fd, 0x00);
    if (proximity < 0) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return;
    }

    // Determine the status string
    char status[6];
    if (proximity <= THRESHOLD) {
        strcpy(status, "SAFE");
    } else {
        strcpy(status, "ALERT");
    }

    // Get the current timestamp
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    sprintf(timestamp, "%d-%02d-%02d %02d:%02d:%02d", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);

    // Append to the log file
    if (fprintf(file, "%s %d %s\n", timestamp, proximity, status) < 0) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
    }
}

void signalHandler(int signum) {
    // Clean up
    close(fd);
    fclose(file);
    exit(0);
}

int main(int argc, char *argv[]) {
    // Parse command-line options
    int opt;
    while ((opt = getopt(argc, argv, "t:a:")) != -1) {
        switch (opt) {
            case 't':
                THRESHOLD = atoi(optarg);
                break;
            case 'a':
                I2C_ADDR = strtol(optarg, NULL, 0);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-a i2c_address]\n", argv[0]);
                return 1;
        }
    }

    // Initialise GPIO and I2C
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error setting up GPIO: %s\n", strerror(errno));
        return 1;
    }
    fd = wiringPiI2CSetup(I2C_ADDR);
    if (fd == -1) {
        fprintf(stderr, "Error setting up I2C: %s\n", strerror(errno));
        return 1;
    }

    // Configure GPIO interrupt
    if (wiringPiISetupInterrupt(GPIO_PIN, INT_EDGE_RISING) == -1) {
        fprintf(stderr, "Error setting up GPIO interrupt: %s\n", strerror(errno));
        return 1;
    }

    // Open the log file
    file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signalHandler);

    // Main loop
    while (1) {
        // Wait for the interrupt
        int status = wiringPiISafeWaitForInterrupt(GPIO_PIN, 1000);
        if (status == -1) {
            fprintf(stderr, "Error waiting for interrupt: %s\n", strerror(errno));
            return 1;
        }

        // Handle the interrupt
        interruptHandler();
    }

    return 0;
}

