#include <pigpio.h>
#include <signal.h>
#include <stdio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define PWM_FREQ 5000

volatile sig_atomic_t stop;

void sig_handler(int signum) {
    stop = 1;
}

double get_distance() {
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIG_PIN, 0);

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioRead(ECHO_PIN) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            break;
        }
    }

    double diff = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1000000000.0;
    return diff * 34000 / 2; // Speed of sound is 340m/s, divide by 2 to get the distance to the object
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQ);

    while (!stop) {
        double distance = get_distance();

        if (distance < 2 || distance > 200) {
            continue;
        }

        double freq = 200 + (distance - 2) * (2000 - 200) / (200 - 2); // Logarithmic scale mapping
        gpioSetPWMfrequency(PWM_PIN, freq);
        gpioPWM(PWM_PIN, 500000 / (2 * freq)); // 50% duty cycle
    }

    gpioSetPWMfrequency(PWM_PIN, 0);
    gpioTerminate();

    return 0;
}

