#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG 23
#define ECHO 24
#define PWM 18

volatile sig_atomic_t stop;

void handler(int signum) {
    stop = 1;
}

double getDistance() {
    gpioWrite(TRIG, 1);
    gpioDelay(10);
    gpioWrite(TRIG, 0);

    while(gpioRead(ECHO) == 0);

    time_t start = gpioTick();
    while(gpioRead(ECHO) == 1);
    time_t end = gpioTick();

    if (end - start > 10000000) {
        printf("Error: Echo timeout\n");
        return -1;
    }

    double distance = (double)(end - start) / 58.0;
    if (distance < 5 || distance > 50) {
        printf("Error: Out of range\n");
        return -1;
    }

    return distance;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIG, PI_OUTPUT);
    gpioSetMode(ECHO, PI_INPUT);
    gpioSetMode(PWM, PI_OUTPUT);

    gpioSetPWMfrequency(PWM, 2000);

    signal(SIGINT, handler);

    while(!stop) {
        double distance = getDistance();
        if (distance > 0) {
            double frequency = 200 + (distance - 5) / (50 - 5) * (2000 - 200);
            gpioSetPWMfrequency(PWM, frequency);
            printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        }
        gpioDelay(1000000);
    }

    gpioSetPWMfrequency(PWM, 0);
    gpioTerminate();

    return 0;
}

