#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x53
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "proximity_log.csv"
#define SENSOR_CMD 0x00

int fd;
FILE *log;

void cleanup(int signum) {
    fclose(log);
    close(fd);
    exit(0);
}

int main() {
    uint16_t als_visible;
    char timestamp[20];
    time_t t;
    struct tm *tmp;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    if ((log = fopen(LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    fprintf(log, "timestamp,als_visible\n");

    while (1) {
        if (write(fd, &SENSOR_CMD, 1) != 1) {
            perror("Failed to write to the i2c bus");
            return 1;
        }

        sleep(1);

        if (read(fd, &als_visible, 2) != 2) {
            perror("Failed to read from the i2c bus");
            return 1;
        }

        time(&t);
        tmp = localtime(&t);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tmp);

        fprintf(log, "%s,%d\n", timestamp, als_visible);
        fflush(log);

        sleep(5);
    }

    return 0;
}

