#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

#define SENSOR_ADDR 0x52  // I2C address of the Si1120 sensor
#define RESET_REG 0x01  // Register to reset the sensor
#define RESET_VAL 0x01  // Value to reset the sensor
#define PART_ID_REG 0x00  // Register to get the part ID
#define PART_ID_VAL 0x73  // Expected part ID
#define ALS_REG 0x02  // Register for ALS data
#define PROX_REG 0x03  // Register for proximity data
#define DELAY_MS 500  // Delay between samples
#define MAX_RETRIES 3  // Max retries for I2C operations

int main() {
    int fd, retries, i;
    char part_id;
    FILE *file;
    time_t t;
    struct tm *tmp;
    char timestamp[20];

    // Initialize wiringPi and I2C
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to setup wiringPi: %s\n", strerror(errno));
        return 1;
    }

    fd = wiringPiI2CSetup(SENSOR_ADDR);
    if (fd == -1) {
        fprintf(stderr, "Failed to open I2C connection: %s\n", strerror(errno));
        return 1;
    }

    // Reset the sensor
    retries = MAX_RETRIES;
    for (i = 0; i < retries; i++) {
        if (wiringPiI2CWriteReg8(fd, RESET_REG, RESET_VAL) == -1) {
            fprintf(stderr, "Failed to reset sensor: %s\n", strerror(errno));
            delay(10);
        } else {
            break;
        }
    }
    if (i == retries) {
        fprintf(stderr, "Failed to reset sensor after %d retries\n", retries);
        return 1;
    }

    // Verify part ID
    part_id = wiringPiI2CReadReg8(fd, PART_ID_REG);
    if (part_id != PART_ID_VAL) {
        fprintf(stderr, "Unexpected part ID: 0x%02x\n", part_id);
        return 1;
    }

    // Open log file
    file = fopen("si1120_log.txt", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Main loop
    while (1) {
        unsigned int als, prox;

        // Get ALS and proximity data
        als = wiringPiI2CReadReg8(fd, ALS_REG);
        prox = wiringPiI2CReadReg8(fd, PROX_REG);

        // Get timestamp
        t = time(NULL);
        tmp = localtime(&t);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tmp);

        // Write to log file
        fprintf(file, "%s, %04x, %04x\n", timestamp, als, prox);
        fflush(file);

        // Delay
        delay(DELAY_MS);
    }

    // Close log file
    fclose(file);

    // Close I2C connection
    close(fd);

    return 0;
}

