#define MEAS_RATE_REG 0x02  // Measurement rate register
#define LUX_REG 0x03  // Lux register
#define PROX_REG 0x04  // Proximity register

#define MEAS_RATE 0x0F  // Measurement rate value

int fd;  // I2C file descriptor
FILE *log_file;  // Log file

void handle_sigint(int sig) {
    fclose(log_file);
    close(fd);
    exit(0);
}

void handle_sigterm(int sig) {
    fclose(log_file);
    close(fd);
    exit(0);
}

int main() {
    int part_id, lux, proximity;
    char timestamp[20];

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Initialize I2C
    fd = wiringPiI2CSetup(SLAVE_ADDRESS);
    if (fd < 0) {
        printf("Failed to initialize I2C: %d\n", fd);
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    // Verify sensor by reading part ID
    part_id = wiringPiI2CReadReg8(fd, PART_ID_REG);
    if (part_id < 0) {
        printf("Failed to read part ID: %d\n", part_id);
        return 1;
    }
    printf("Part ID: 0x%02X\n", part_id);

    // Configure measurement rate
    if (wiringPiI2CWriteReg8(fd, MEAS_RATE_REG, MEAS_RATE) < 0) {
        printf("Failed to write to measurement rate register\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read lux and proximity
        lux = wiringPiI2CReadReg16(fd, LUX_REG);
        if (lux < 0) {
            printf("Failed to read lux: %d\n", lux);
            return 1;
        }
        proximity = wiringPiI2CReadReg16(fd, PROX_REG);
        if (proximity < 0) {
            printf("Failed to read proximity: %d\n", proximity);
            return 1;
        }

        // Get current timestamp
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

        // Log data
