#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include "alarm_trigger.h"

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

volatile unsigned int startTick, endTick;
volatile unsigned int distance;

void alarmHandler(int gpio, int level, uint32_t tick)
{
    if (level == 0) // Rising edge
    {
        startTick = tick;
    }
    else // Falling edge
    {
        endTick = tick;
        distance = (endTick - startTick) * 17150; // Convert to cm
        printf("Distance: %d cm\n", distance);
        if (distance < 20)
        {
            gpioWrite(BUZZER_PIN, 1);
        }
        else
        {
            gpioWrite(BUZZER_PIN, 0);
        }
    }
}

void sigintHandler(int sig)
{
    printf("Exiting...\n");
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[])
{
    if (signal(SIGINT, sigintHandler) == SIG_ERR)
    {
        fprintf(stderr, "Unable to catch SIGINT\n");
        exit(1);
    }

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0)
    {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        exit(1);
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0)
    {
        fprintf(stderr, "Failed to set echo pin mode\n");
        exit(1);
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0)
    {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        exit(1);
    }

    if (gpioSetAlarmFunc(ECHO_PIN, alarmHandler) < 0)
    {
        fprintf(stderr, "Failed to set alarm function\n");
        exit(1);
    }

    while (1)
    {
        gpioWrite(TRIGGER_PIN, 1);
        time_sleep(0.00001);
        gpioWrite(TRIGGER_PIN, 0);
        time_sleep(1);
    }

    return 0;
}
