#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG 4
#define ECHO 17
#define SERVO 18

#define MIN_DIST 20
#define MAX_DIST 110
#define MIN_PULSE 500
#define MAX_PULSE 2500

volatile sig_atomic_t stop;

void sigint_handler(int signum) {
    stop = 1;
}

double measure_distance() {
    gpioSetMode(TRIG, PI_OUTPUT);
    gpioSetMode(ECHO, PI_INPUT);

    gpioWrite(TRIG, PI_OFF);
    gpioDelay(10000); // 10 microseconds

    gpioWrite(TRIG, PI_ON);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIG, PI_OFF);

    while (gpioRead(ECHO) == PI_OFF) {
        if (stop) {
            return -1.0;
        }
    }

    unsigned int start = gpioTick();
    while (gpioRead(ECHO) == PI_ON) {
        if (stop) {
            return -1.0;
        }
    }
    unsigned int end = gpioTick();

    double distance = (end - start) * 1000000.0 / 5800.0; // cm
    return distance;
}

void adjust_servo(double distance) {
    if (distance < MIN_DIST || distance > MAX_DIST) {
        return;
    }

    double pulse = MIN_PULSE + (distance - MIN_DIST) * (MAX_PULSE - MIN_PULSE) / (MAX_DIST - MIN_DIST);
    gpioServo(SERVO, pulse);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (!stop) {
        double distance = measure_distance();
        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
            adjust_servo(distance);
        } else {
            printf("Measurement error\n");
        }

        gpioDelay(1000000); // 100 milliseconds
    }

    gpioServo(SERVO, 0);
    gpioTerminate();

    return 0;
}

