#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_ADDR 0x29 // VL53L1X default I2C address
#define GPIO_PWM 18 // GPIO pin for PWM
#define TIMEOUT 1000 // I2C timeout in microseconds

FILE *log_file;

void sigint_handler(int sig) {
    gpioWrite(GPIO_PWM, 0);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    log_file = fopen("gate_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    int handle = i2cOpen(1, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    // Verify model ID
    char model_id = i2cReadByteData(handle, 0x00);
    if (model_id != 0xEA) {
        fprintf(stderr, "Invalid model ID: 0x%02X\n", model_id);
        return 1;
    }

    // Set timing budget
    i2cWriteByteData(handle, 0x01, 0x00);

    // Start ranging
    i2cWriteByteData(handle, 0x00, 0x01);

    // Set up GPIO for PWM
    gpioSetMode(GPIO_PWM, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_PWM, 50);

    while (1) {
        // Read distance
        char distance_low = i2cReadByteData(handle, 0x0F);
        char distance_high = i2cReadByteData(handle, 0x10);
        int distance = (distance_high << 8) | distance_low;

        // Calculate pulse width
        int pulse_width;
        if (distance > 250) {
            pulse_width = 1000;
        } else if (distance < 200) {
            pulse_width = 2000;
        } else {
            pulse_width = 1500;
        }

        // Set PWM
        gpioPWM(GPIO_PWM, pulse_width);

        // Log event
        time_t now = time(NULL);
        fprintf(log_file, "%ld: %d\n", now, distance);
        fflush(log_file);

        // Wait before next measurement
        time_sleep(0.005);
    }

    return 0;
}

