#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <crc8.h>

#define SHT40_ADDR 0x44
#define I2C_BUS "/dev/i2c-1"

int fd;

void handle_signal(int signum) {
    printf("Exiting...\n");
    close(fd);
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    while (1) {
        uint8_t cmd[] = {0x24, 0x00};
        if (write(fd, cmd, 2) != 2) {
            perror("Failed to write to the i2c bus");
            close(fd);
            return 1;
        }

        usleep(10000);

        uint8_t data[6];
        if (read(fd, data, 6) != 6) {
            perror("Failed to read from the i2c bus");
            close(fd);
            return 1;
        }

        uint8_t crc_temp = crc8(data, 2, 0x31, 0xFF, false);
        uint8_t crc_hum = crc8(data + 3, 2, 0x31, 0xFF, false);

        if (crc_temp != data[2] || crc_hum != data[5]) {
            fprintf(stderr, "CRC failure\n");
            close(fd);
            return 1;
        }

        float temp = (data[0] * 256 + data[1]) * 175.0 / 65535.0 - 45.0;
        float hum = (data[3] * 256 + data[4]) * 100.0 / 65535.0;

        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temp, hum);

        sleep(5);
    }

    return 0;
}

