#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

#define MLX90614_ADDR 0x5A // Default I2C address of MLX90614
#define MLX90614_TA 0x06 // Temperature register for ambient temperature
#define MLX90614_TOBJ1 0x07 // Temperature register for object temperature

int fd;
FILE *file;

void handle_sigint(int sig) {
    printf("\nClosing I2C and file descriptors...\n");
    close(fd);
    fclose(file);
    exit(0);
}

float read_temp(int reg) {
    int raw = wiringPiI2CReadReg16(fd, reg);
    return (float)(raw * 0.02) - 273.15; // Convert raw value to temperature in Celsius
}

int main() {
    signal(SIGINT, handle_sigint);

    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi: %s\n", strerror(errno));
        return 1;
    }

    fd = wiringPiI2CSetup(MLX90614_ADDR);
    if (fd == -1) {
        printf("Failed to setup I2C: %s\n", strerror(errno));
        return 1;
    }

    file = fopen("temperature_log.csv", "a");
    if (file == NULL) {
        printf("Failed to open file: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        float temp_ambient = read_temp(MLX90614_TA);
        float temp_object = read_temp(MLX90614_TOBJ1);

        if (temp_ambient == -1 || temp_object == -1) {
            printf("Failed to read temperature: %s\n", strerror(errno));
            continue;
        }

        fprintf(file, "%ld,%f,%f\n", now, temp_ambient, temp_object);
        fflush(file);

        sleep(5);
    }

    return 0;
}

