#define SENSOR_ADDR 0x2A // Sensirion SDP31 I2C address
#define LOG_FILE "airflow.log"
#define SAMPLE_INTERVAL 100000 // 100 ms

volatile sig_atomic_t stop;

void intHandler(int signum) {
    stop = 1;
}

int main() {
    int fd;
    FILE *log;
    struct timespec ts;
    int retries, i;
    unsigned char buf[6];
    float pressure, temperature;

    signal(SIGINT, intHandler);
    signal(SIGTERM, intHandler);

    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    while (!stop) {
        retries = 3;
        while (retries--) {
            if (i2c_smbus_write_byte(fd, 0x0800) < 0) {
                usleep(1000); // 1 ms delay
                continue;
            }
            break;
        }
        if (retries < 0) {
            perror("Failed to trigger measurement");
            return 1;
        }

        usleep(SAMPLE_INTERVAL); // Wait for at least 100 ms

