            perror("Failed to read measurement data");
            return 1;
        }

        pressure = (buf[0] << 8 | buf[1]) / 100.0;
        temperature = (buf[3] << 8 | buf[4]) / 100.0;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log, "%ld,%f,%f\n", ts.tv_sec, pressure, temperature);
        fflush(log);
    }

    fclose(log);
    close(fd);

    // Call library's cleanup API here

    return 0;
}

