#define SENSOR_ADDR 0x40  // I2C address of the Si7015 sensor
#define READ_TEMP_CMD 0xE0  // Command to read temperature
#define READ_HUM_CMD 0xE5  // Command to read humidity
#define DELAY_MS 5000  // Delay between measurements in milliseconds

int fd;  // File descriptor for I2C communication
FILE *file;  // File for logging

void sigint_handler(int sig) {
    printf("\nClosing I2C handle, terminating driver library and closing file.\n");
    close(fd);
    wiringPiI2CWriteReg8(fd, 0x01, 0x80);  // Reset the sensor
    digitalWrite(1, LOW);  // Turn off the I2C bus
    fclose(file);
    exit(0);
}

int main() {
    float temp, hum;
    int res;
    char buf[256];
    time_t t = time(NULL);

    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to setup wiringPi: %s\n", strerror(errno));
        return 1;
    }

    fd = wiringPiI2CSetup(SENSOR_ADDR);
    if (fd == -1) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    wiringPiI2CWriteReg8(fd, 0x01, 0x80);  // Reset the sensor
    delay(500);  // Wait for sensor to reset

    file = fopen("sensor_data.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        wiringPiI2CWrite(fd, READ_TEMP_CMD);  // Start temperature measurement
        delay(20);  // Wait for measurement to complete
        temp = wiringPiI2CReadReg16(fd, READ_TEMP_CMD) * 175.72 / 65536.0 - 46.85;  // Read and convert temperature

        wiringPiI2CWrite(fd, READ_HUM_CMD);  // Start humidity measurement
        delay(20);  // Wait for measurement to complete
        hum = wiringPiI2CReadReg16(fd, READ_HUM_CMD) * 125 / 65536.0 - 6;  // Read and convert humidity

        t = time(NULL);
        sprintf(buf, "%s Temp: %.2f°C, Humidity: %.2f%%\n", ctime(&t), temp, hum);
        printf("%s", buf);
        fputs(buf, file);
        fflush(file);

        delay(DELAY_MS);
    }

    return 0;
}

