#define I2C_BUS "/dev/i2c-1"
#define STS30_ADDR 0x4A
#define STS30_CMD 0x2400

int fd;
int running = 1;

void* sample_temp(void* arg) {
    while(running) {
        usleep(15000); // wait for 15ms
        int ret = write(fd, &STS30_CMD, 2);
        if (ret != 2) {
            time_t now = time(NULL);
            FILE *error_log = fopen("error_log.txt", "a");
            fprintf(error_log, "%s: I2C write error\n", ctime(&now));
            fclose(error_log);
            continue;
        }
        usleep(50000); // wait for conversion
        unsigned char buf[3];
        ret = read(fd, buf, 3);
        if (ret != 3) {
            time_t now = time(NULL);
            FILE *error_log = fopen("error_log.txt", "a");
            fprintf(error_log, "%s: I2C read error\n", ctime(&now));
            fclose(error_log);
            continue;
        }
        // CRC check here...
        time_t now = time(NULL);
        FILE *log_file = fopen("enclosure_temp_log.txt", "a");
        fprintf(log_file, "%s: Temp = %d.%d C\n", ctime(&now), buf[0], buf[1]);
        fclose(log_file);
    }
    return NULL;
}

void sigint_handler(int sig) {
    running = 0;
    close(fd);
    exit(0);
}

