#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <crc8.h>
#include <time.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDR 0x28 // Sensor address
#define CMD_CONT_MEASURE 0x00 // Continuous measurement command
#define CRC8_POLYNOMIAL 0x31 // CRC8 polynomial
#define CRC8_INIT 0xFF // CRC8 initial value

int file_i2c;
FILE *file_log;

void cleanup(int signum) {
    fclose(file_log);
    close(file_i2c);
    exit(0);
}

int main() {
    unsigned char buffer[6];
    int res;
    float pressure, temperature;
    time_t rawtime;
    struct tm *timeinfo;
    char timestr[20];

    signal(SIGINT, cleanup);

    file_log = fopen("airflow_data.txt", "a");
    if (file_log == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    if ((file_i2c = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(file_i2c, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    while (1) {
        if (write(file_i2c, &CMD_CONT_MEASURE, 1) != 1) {
            perror("Failed to write to I2C device");
            return 1;
        }

        usleep(1000); // Wait at least 1ms

        if (read(file_i2c, buffer, 6) != 6) {
            perror("Failed to read from I2C device");
            return 1;
        }

        if (crc8(buffer, 5, CRC8_POLYNOMIAL, CRC8_INIT) != buffer[5]) {
            fprintf(stderr, "CRC8 checksum error\n");
            continue;
        }

        pressure = (buffer[0] << 8) | buffer[1];
        temperature = (buffer[3] << 8) | buffer[4];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestr, sizeof(timestr), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(file_log, "%s,%f,%f\n", timestr, pressure, temperature);
        fflush(file_log);

        usleep(1000000); // Wait 1 second between each measurement
    }

    return 0;
}

