#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>

#define SENSOR_ADDR 0x40 // Si7021 I2C address
#define FAN_PIN 18 // GPIO pin for the cooling fan
#define BUFFER_SIZE 60
#define RETRY_LIMIT 3

int i2cHandle;
float temperatureBuffer[BUFFER_SIZE];
time_t timestampBuffer[BUFFER_SIZE];
int bufferIndex = 0;

void handleSIGINT(int sig) {
    digitalWrite(FAN_PIN, LOW);
    close(i2cHandle);
    exit(0);
}

float readTemperature() {
    int retryCount = 0;
    while (retryCount < RETRY_LIMIT) {
        int rawTemp = wiringPiI2CReadReg16(i2cHandle, 0x24);
        if (rawTemp != -1) {
            float temp = ((175.72 * rawTemp) / 65536.0) - 46.85;
            return temp;
        }
        retryCount++;
    }
    return -1.0;
}

void controlFan(float temp) {
    if (temp > 28.0) {
        digitalWrite(FAN_PIN, HIGH);
    } else if (temp < 27.0) {
        digitalWrite(FAN_PIN, LOW);
    }
}

int main() {
    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(FAN_PIN, OUTPUT);
    signal(SIGINT, handleSIGINT);

    i2cHandle = wiringPiI2CSetup(SENSOR_ADDR);
    if (i2cHandle == -1) {
        printf("Failed to setup I2C\n");
        return 1;
    }

    while (1) {
        float temp = readTemperature();
        if (temp != -1.0) {
            time_t currentTime = time(NULL);
            temperatureBuffer[bufferIndex] = temp;
            timestampBuffer[bufferIndex] = currentTime;
            bufferIndex = (bufferIndex + 1) % BUFFER_SIZE;

            printf("Temperature: %.2f°C, Time: %s\n", temp, ctime(&currentTime));
            controlFan(temp);
        } else {
            printf("Failed to read temperature\n");
        }

        delay(2000);
    }

    return 0;
}

