#define I2C_DEVICE "/dev/i2c-1"
#define SHT35_ADDR 0x44
#define CRC_POLYNOMIAL 0x31
#define FILE_NAME "environmental_data.txt"

int fd;
FILE *file;

void sig_handler(int signum) {
    fflush(file);
    fclose(file);
    close(fd);
    exit(0);
}

int crc8(const unsigned char *data, int len) {
    int crc = 0xff;
    int polynomial = CRC_POLYNOMIAL;

    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }

    return crc;
}

void *measure_and_log(void *arg) {
    unsigned char buffer[6];
    int ret;

    for (int i = 0; i < 3; i++) {
        ret = write(fd, "\x2C\x06", 2);
        if (ret != 2) {
            sleep(1);
            continue;
        }

        usleep(15000);

        ret = read(fd, buffer, 6);
        if (ret != 6) {
            sleep(1);
            continue;
        }

        if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
            sleep(1);
            continue;
        }

        float temp = -45.0 + 175.0 * buffer[0] / 65535.0;
