        time_t now = time(NULL);
        struct tm *tm_info = gmtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", tm_info);

        fprintf(file, "%s,%.2f,%.2f\n", timestamp, temp, humidity);
        fflush(file);

        break;
    }

    return NULL;
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SHT35_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    file = fopen(FILE_NAME, "w");
    if (file == NULL) {
        perror("Failed to open file");
        return 1;
    }

    pthread_t thread;
    srand(time(NULL));

    while (1) {
        pthread_create(&thread, NULL, measure_and_log, NULL);
        pthread_join(thread, NULL);
        sleep(5);
    }

    return 0;
}

