void* periodic_measurement(void* arg) {
    while (1) {
        int ret;
        unsigned char buf[3];

        // Reset the sensor
        ret = wiringPiI2CWriteReg8(fd, RESET_CMD, 0);
        if (ret < 0) {
            fprintf(stderr, "I2C reset failed: %d\n", ret);
            continue;
        }

        // Read temperature
        ret = wiringPiI2CWriteReg8(fd, READ_TEMP_CMD, 0);
        if (ret < 0) {
            fprintf(stderr, "I2C read temperature failed: %d\n", ret);
            continue;
        }
        delay(20); // Wait for conversion
        buf[0] = wiringPiI2CReadReg8(fd, 0);
        buf[1] = wiringPiI2CReadReg8(fd, 0);
        buf[2] = wiringPiI2CReadReg8(fd, 0);
        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "CRC error in temperature measurement\n");
            continue;
        }

        // Read humidity
        ret = wiringPiI2CWriteReg8(fd, READ_HUMID_CMD, 0);
        if (ret < 0) {
            fprintf(stderr, "I2C read humidity failed: %d\n", ret);
            continue;
        }
