        buf[0] = wiringPiI2CReadReg8(fd, 0);
        buf[1] = wiringPiI2CReadReg8(fd, 0);
        buf[2] = wiringPiI2CReadReg8(fd, 0);
        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "CRC error in humidity measurement\n");
            continue;
        }

        // Log the measurement
        time_t now = time(NULL);
