        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%FT%T%z", pnow);
        FILE* file = fopen(FILE_NAME, "a");
        if (file != NULL) {
            fprintf(file, "%s,%.1f,%.1f\n", timestamp, buf[0]*175.72/65536.0-46.85, buf[1]*125.0/65536.0-6.0);
            fclose(file);
        }

        delay(POLL_INTERVAL);
    }
    return NULL;
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    wiringPiSetup();
    fd = wiringPiI2CSetup(SENSOR_ADDR);
    if (fd < 0) {
        fprintf(stderr, "I2C open failed: %d\n", fd);
        return 1;
    }

    pthread_t thread;
    pthread_create(&thread, NULL, periodic_measurement, NULL);
    pthread_join(thread, NULL);

