#define BUFFER_SIZE 10 // Circular buffer size

int fd; // I2C file descriptor
float buffer[BUFFER_SIZE]; // Circular buffer
int buffer_index = 0;

void handle_signal(int signum) {
    digitalWrite(GPIO_PIN, LOW);
    close(fd);
    exit(0);
}

float get_temp() {
    int raw_temp = wiringPiI2CReadReg16(fd, TEMP_REG);
    float temp = (float)raw_temp / 256.0;
    return temp;
}

void update_buffer(float temp) {
    buffer[buffer_index++] = temp;
    if (buffer_index == BUFFER_SIZE) buffer_index = 0;
}

float compute_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer[i];
    }
    return sum / BUFFER_SIZE;
}

int main() {
    if (wiringPiSetupGpio() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(GPIO_PIN, OUTPUT);

    fd = wiringPiI2CSetup(STLM75_ADDR);
    if (fd == -1) {
        printf("Failed to open I2C bus\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        float temp = get_temp();
        update_buffer(temp);
        float avg = compute_average();
        if (avg > 28.0) {
            digitalWrite(GPIO_PIN, HIGH);
        } else {
            digitalWrite(GPIO_PIN, LOW);
        }
