Please note that this program assumes that you have the `wiringPi` and `i2c-dev` libraries installed and configured on your Raspberry Pi.

```c
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <stdio.h>
#include <signal.h>
#include <unistd.h>

#define STLM75_ADDR 0x48 // STLM75 I2C address
#define TEMP_REG 0x00 // Temperature register
#define GPIO_PIN 17 // GPIO pin number
#define BUFFER_SIZE 10 // Circular buffer size

int fd; // I2C file descriptor
float buffer[BUFFER_SIZE]; // Circular buffer
int buffer_index = 0;

void handle_signal(int signum) {
    digitalWrite(GPIO_PIN, LOW);
    close(fd);
    exit(0);
}

float get_temp() {
    int raw_temp = wiringPiI2CReadReg16(fd, TEMP_REG);
    float temp = (float)raw_temp / 256.0;
    return temp;
}

void update_buffer(float temp) {
    buffer[buffer_index++] = temp;
    if (buffer_index == BUFFER_SIZE) buffer_index = 0;
}

float compute_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer[i];
    }
    return sum / BUFFER_SIZE;
}

int main() {
    if (wiringPiSetupGpio() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(GPIO_PIN, OUTPUT);

    fd = wiringPiI2CSetup(STLM75_ADDR);
    if (fd == -1) {
        printf("Failed to open I2C bus\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        float temp = get_temp();
        update_buffer(temp);
        float avg = compute_average();
        if (avg > 28.0) {
            digitalWrite(GPIO_PIN, HIGH);
        } else {
            digitalWrite(GPIO_PIN, LOW);
        }
        sleep(1);
    }

    return 0;
}
```

This program reads the temperature from the STLM75 sensor, stores the last 10 readings in a circular buffer, computes the average, and controls the LED based on the average temperature. If the program receives a SIGINT or SIGTERM signal, it turns off the LED, closes the I2C handle, and exits.

Please note that the STLM75 temperature sensor returns a 16-bit value, where the most significant byte is the integer part and the least significant byte is the fractional part. The program converts this value to a floating-point temperature in degrees Celsius by dividing by 256.

Also, the `wiringPi` library uses the BCM pin numbering scheme, so GPIO17 corresponds to pin 11 on the Raspberry Pi's GPIO header.

This program does not handle errors that might occur when reading from the sensor or when writing to the GPIO pin. You might want to add error checking code to handle these cases.

