#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <wiringPiI2C.h>
#include <wiringPi.h>

#define SCD30_I2C_ADDR 0x61
#define SCD30_CMD_CONTINUOUS_MEASUREMENT 0x0010
#define SCD30_CMD_STOP_MEASUREMENT 0x0104

int fd;
FILE *log_file;

void handle_signal(int signum) {
    printf("Exiting...\n");
    fclose(log_file);
    close(fd);
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = handle_signal;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi: %s\n", strerror(errno));
        return 1;
    }

    fd = wiringPiI2CSetup(SCD30_I2C_ADDR);
    if (fd == -1) {
        printf("Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    if (wiringPiI2CWriteReg8(fd, 0x01, 0x03) == -1) {
        printf("Failed to write to I2C device: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen("air_quality.log", "w");
    if (log_file == NULL) {
        printf("Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        int co2, temp, humidity;
        time_t now = time(NULL);
        struct tm *timeinfo = gmtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", timeinfo);

        if (wiringPiI2CWriteReg8(fd, 0x00, 0x36) == -1) {
            printf("Failed to write to I2C device: %s\n", strerror(errno));
            continue;
        }

        if (wiringPiI2CWriteReg8(fd, 0x06, 0x15) == -1) {
            printf("Failed to write to I2C device: %s\n", strerror(errno));
            continue;
        }

        sleep(5);

        co2 = wiringPiI2CReadReg16(fd, 0x02);
        temp = wiringPiI2CReadReg16(fd, 0x03);
        humidity = wiringPiI2CReadReg16(fd, 0x04);

        if (co2 == -1 || temp == -1 || humidity == -1) {
            printf("Failed to read from I2C device: %s\n", strerror(errno));
            continue;
        }

        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, co2, temp, humidity);
        fflush(log_file);

        if (co2 < 800) {
            // OFF state
        } else if (co2 < 1200) {
            // LOW state
        } else {
            // HIGH state
        }
    }

    return 0;
}

