#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <crc.h>

#define SENSIRION_ADDR 0x28 // Sensirion SDP32 I2C address
#define I2C_BUS "/dev/i2c-1" // I2C bus device file

int fd;

void handle_signal(int signum) {
    printf("Exiting...\n");
    close(fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    int interval = 1000;
    if (argc > 1) {
        interval = atoi(argv[1]);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SENSIRION_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    while (1) {
        char buf[9];
        if (read(fd, buf, 9) != 9) {
            perror("Failed to read from the i2c bus");
            return 1;
        }

        uint8_t crc_calc = crc8(buf, 8);
        if (crc_calc != buf[8]) {
            printf("CRC8 mismatch\n");
            return 1;
        }

        uint16_t pressure = (buf[0] << 8) | buf[1];
        uint16_t temperature = (buf[3] << 8) | buf[4];
        uint16_t scale_factor = (buf[6] << 8) | buf[7];

        printf("%ld: Pressure: %d, Temperature: %d, Scale Factor: %d\n", time(NULL), pressure, temperature, scale_factor);

        usleep(interval * 1000);
    }

    return 0;
}

