#define HDC1000_ADDR 0x40
#define HDC1000_TEMP 0x00
#define HDC1000_HUMID 0x01

int file_i2c;

void signal_handler(int signum) {
    close(file_i2c);
    exit(0);
}

int main() {
    unsigned char buffer[2];
    float temp, humid;
    int ret;

    if ((file_i2c = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(file_i2c, I2C_SLAVE, HDC1000_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        exit(1);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        buffer[0] = HDC1000_TEMP;
        buffer[1] = 0x00;
        ret = write(file_i2c, buffer, 1);
        if (ret != 1) {
            perror("Failed to write to the i2c bus");
            continue;
        }
        usleep(20000); // Wait at least 20ms

        buffer[0] = HDC1000_HUMID;
        buffer[1] = 0x00;
        ret = write(file_i2c, buffer, 1);
        if (ret != 1) {
            perror("Failed to write to the i2c bus");
            continue;
        }
        usleep(20000); // Wait at least 20ms

        ret = read(file_i2c, buffer, 2);
        if (ret != 2) {
            perror("Failed to read from the i2c bus");
            continue;
