#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x28
#define FILE_NAME "airflow_log.csv"

int file;

void signal_handler(int signum) {
    printf("Closing file and exiting...\n");
    fclose(file);
    exit(0);
}

int main() {
    int fd;
    unsigned char buffer[3];
    struct timespec ts;
    char time_str[20];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    // Set the slave address
    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    // Open file
    if (access(FILE_NAME, F_OK) != 0) {
        file = fopen(FILE_NAME, "w");
        if (file == NULL) {
            perror("Failed to open file for writing");
            return 1;
        }
        fprintf(file, "Timestamp,Pressure\n");
    } else {
        file = fopen(FILE_NAME, "a");
        if (file == NULL) {
            perror("Failed to open file for appending");
            return 1;
        }
    }

    while (1) {
        // Trigger measurement
        if (write(fd, "", 0) != 0) {
            perror("Failed to trigger measurement");
            return 1;
        }

        // Wait at least 8ms
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_nsec += 8000000;
        if (ts.tv_nsec > 1000000000) {
            ts.tv_sec++;
            ts.tv_nsec -= 1000000000;
        }
        clock_nanosleep(CLOCK_REALTIME, TIMER_ABSTIME, &ts, NULL);

        // Read measurement
        if (read(fd, buffer, 3) != 3) {
            perror("Failed to read measurement");
            return 1;
        }

        // Get current time
        time(&ts.tv_sec);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Log measurement
        fprintf(file, "%s,%d\n", time_str, buffer[0] << 8 | buffer[1]);
        fflush(file);
    }

    return 0;
}

