#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_FILE "/dev/i2c-1"
#define I2C_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_SIZE 1024 * 1024 // 1MB

int fd;

void cleanup(int signum) {
    close(fd);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);

    if ((fd = open(I2C_FILE, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    while (1) {
        char buf[2];
        buf[0] = 0x22; // Trigger measurement command
        if (write(fd, buf, 1) != 1) {
            perror("Failed to write to the i2c bus");
            return 1;
        }

        usleep(40000); // Wait for 40ms

        if (read(fd, buf, 2) != 2) {
            perror("Failed to read from the i2c bus");
            return 1;
        }

        int status = buf[0] & 0x80; // Check status bit
        if (status != 0) {
            printf("Sensor error: %d\n", status);
            continue;
        }

        float humidity = ((buf[0] & 0x1F) * 256 + buf[1]) / 16384.0 * 100;
        float temperature = ((buf[0] & 0x20) * 256 + buf[1]) / 16384.0 * 165 - 40;

        FILE *log = fopen(LOG_FILE, "a");
        if (log == NULL) {
            perror("Failed to open log file");
            return 1;
        }

        fseek(log, 0, SEEK_END);
        if (ftell(log) > LOG_SIZE) {
            fclose(log);
            remove(LOG_FILE);
            log = fopen(LOG_FILE, "a");
        }

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%FT%T%z", tm);

        fprintf(log, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        fclose(log);

        sleep(5);
    }

    return 0;
}

