#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>

#define SHT40_ADDR 0x44
#define SHT40_CMD_READ 0x240B

int fd;
FILE *file;

void sigint_handler(int sig) {
    fclose(file);
    close(fd);
    exit(0);
}

int crc8(const unsigned char *data, int len) {
    int crc = 0xFF;
    int polynomial = 0x31;
    int i, j;

    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }

    return crc;
}

void *read_sensor(void *arg) {
    while (1) {
        int result = wiringPiI2CWrite(fd, SHT40_CMD_READ);
        if (result == -1) {
            perror("Failed to write to the sensor");
            exit(1);
        }

        delay(8.5);

        unsigned char buffer[6];
        result = read(fd, buffer, 6);
        if (result != 6) {
            perror("Failed to read from the sensor");
            exit(1);
        }

        if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        time_t now = time(NULL);
        fprintf(file, "%ld,%d,%d\n", now, buffer[0] * 65536 + buffer[1], buffer[3] * 65536 + buffer[4]);
        fflush(file);

        delay(5000);
    }

    return NULL;
}

int main() {
    if (wiringPiSetup() == -1) {
        perror("Failed to setup wiringPi");
        return 1;
    }

    fd = wiringPiI2CSetup(SHT40_ADDR);
    if (fd == -1) {
        perror("Failed to setup I2C");
        return 1;
    }

    file = fopen("environmental_data.txt", "w");
    if (file == NULL) {
        perror("Failed to open file");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    pthread_t thread;
    pthread_create(&thread, NULL, read_sensor, NULL);
    pthread_join(thread, NULL);

    return 0;
}

