#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define TMP117_ADDR 0x48
#define BUFFER_SIZE 100
#define SLEEP_TIME 5

int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *sda_line, *scl_line;

void cleanup(int signum) {
    // Flush and close the I2C file descriptor
    close(i2c_fd);

    // Release the GPIO lines
    gpiod_line_release(sda_line);
    gpiod_line_release(scl_line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    // Exit the program
    exit(0);
}

int main() {
    // Register the signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open the I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("Failed to set the I2C slave address");
        return 1;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open the GPIO chip");
        return 1;
    }

