#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>

#define SHTC3 0x70
#define CMD_READ_SINGLE_SHOT 0x240B

int fd;

void sigint_handler(int sig) {
    printf("Exiting...\n");
    close(fd);
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to setup wiringPi\n");
        return 1;
    }

    fd = wiringPiI2CSetup(SHTC3);
    if (fd == -1) {
        fprintf(stderr, "Failed to setup I2C\n");
        return 1;
    }

    while (1) {
        wiringPiI2CWriteReg16(fd, 0x20, CMD_READ_SINGLE_SHOT);
        delay(12);  // Wait at least 12.4ms

        int data[6];
        for (int i = 0; i < 6; i++) {
            data[i] = wiringPiI2CReadReg8(fd, 0x00 + i);
        }

        // Validate CRC and check range
        if (data[2] != crc8(data, 2) || data[5] != crc8(data + 3, 2) ||
            data[0] > 125 || data[0] < -40 || data[1] > 100 || data[1] < 0) {
            fprintf(stderr, "CRC failure or out-of-range values\n");
            continue;
        }

        // Log to file
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        FILE *file = fopen("shtc3_environment.log", "a");
        if (file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return 1;
        }
        fprintf(file, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, data[0], data[1]);
        fclose(file);

        // Print to stdout
        printf("%.2f,%.2f\n", data[0], data[1]);

        delay(5000);  // Wait 5 seconds
    }

    return 0;
}

