            sleep(1);
            continue;
        }

        if (ioctl(fd, I2C_SLAVE, TMP117_ADDR) < 0) {
            perror("Failed to acquire bus access or talk to slave");
            close(fd);
            sleep(1);
            continue;
        }

        break;
    }

    if (fd < 0) {
        printf("Failed to initialize I2C handle after 3 attempts\n");
        return 1;
