        char buf[2] = {0};
        if (write(fd, buf, 1) != 1) {
            perror("Failed to write to I2C device");
            fclose(file);
            close(fd);
            return 1;
        }

        if (read(fd, buf, 2) != 2) {
            perror("Failed to read from I2C device");
            fclose(file);
            close(fd);
            return 1;
