#include <signal.h>

#define DHT_PIN 4
#define TIMEOUT 1000

void sig_handler(int signum) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    gpioSetMode(DHT_PIN, PI_OUTPUT);
    gpioWrite(DHT_PIN, 0);
    gpioDelay(1000000); // 1 second delay
    gpioWrite(DHT_PIN, 1);
    gpioDelay(20000); // 20 millisecond delay

    gpioSetMode(DHT_PIN, PI_INPUT);
    gpioDelay(TIMEOUT);

    if (gpioRead(DHT_PIN) == 0) {
        fprintf(stderr, "Timeout on start signal\n");
        gpioTerminate();
        return 1;
    }

    gpioDelay(TIMEOUT);

    if (gpioRead(DHT_PIN) == 1) {
        fprintf(stderr, "Timeout on response\n");
        gpioTerminate();
        return 1;
