#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <stdio.h>

#define SDA_GPIO 2
#define SCL_GPIO 3
#define SHT31_ADDR 0x44
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF

int fd;
FILE *logFile;

void handle_signal(int signum) {
    printf("Closing I2C handle and log file...\n");
    close(fd);
    fclose(logFile);
    exit(0);
}

int crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (unsigned char)((crc << 1) ^ CRC_POLYNOMIAL);
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    fd = wiringPiI2CSetup(SHT31_ADDR);
    if (fd == -1) {
        printf("Failed to open I2C interface\n");
        return 1;
    }

    logFile = fopen("sht31d_data.log", "w");
    if (logFile == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    while (1) {
        wiringPiI2CWrite(fd, 0x2C, 0x06); // Start measurement
        delay(15); // Wait at least 15ms

        int data[6];
        for (int i = 0; i < 6; i++) {
            data[i] = wiringPiI2CReadReg8(fd, 0x00);
        }

        if (crc8((unsigned char*)data, 2) != data[2] || crc8((unsigned char*)&data[3], 2) != data[5]) {
            time_t now = time(NULL);
            fprintf(logFile, "%s,CRC error\n", ctime(&now));
            continue;
        }

        float temperature = (float)((data[0] * 256) + data[1]) * 0.01;
        float humidity = (float)((data[3] * 256) + data[4]) * 0.01;

        time_t now = time(NULL);
        fprintf(logFile, "%s,%f,%f\n", ctime(&now), temperature, humidity);

        delay(5000); // Wait 5 seconds
    }

    return 0;
}

