#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <math.h>

#define I2C_DEV "/dev/i2c-1"
#define LM75B_ADDR 0x48
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define SAMPLE_COUNT 60

volatile sig_atomic_t stop;

void intHandler(int signum) {
    stop = 1;
}

int main() {
    signal(SIGINT, intHandler);
    signal(SIGTERM, intHandler);

    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i2c_fd;
    float temp_samples[SAMPLE_COUNT];
    int current_sample = 0;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LM75B_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    while (!stop) {
        unsigned char buf[2];
        short temp;

        if (read(i2c_fd, buf, 2) != 2) {
            perror("Failed to read from I2C device");
            continue;
        }

        temp = buf[0] << 8 | buf[1];
        temp_samples[current_sample++] = temp / 256.0;
        if (current_sample == SAMPLE_COUNT)
            current_sample = 0;

        float avg = 0;
        for (int i = 0; i < SAMPLE_COUNT; i++)
            avg += temp_samples[i];
        avg /= SAMPLE_COUNT;

        if (avg > 28.0) {
            if (gpiod_line_set_value(line, 1) < 0) {
                perror("Failed to set GPIO line value");
                continue;
            }
        } else if (avg < 26.0) {
            if (gpiod_line_set_value(line, 0) < 0) {
                perror("Failed to set GPIO line value");
                continue;
            }
        }

        sleep(1);
    }

    gpiod_line_release(line);
    close(i2c_fd);
    gpiod_chip_close(chip);

    return 0;
}

