#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDR 0x28 // Sensirion SDP800-500Pa sensor address
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

void handle_signal(int signum) {
    printf("Exiting...\n");
    // Cleanup code here
    exit(0);
}

unsigned char crc8(unsigned char *data, int len) {
    unsigned char crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (unsigned char)((crc << 1) ^ CRC8_POLYNOMIAL);
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, handle_signal);

    int file_i2c = open(I2C_DEVICE, O_RDWR);
    if (file_i2c < 0) {
        printf("Failed to open the i2c bus\n");
        return 1;
    }

    if (ioctl(file_i2c, I2C_SLAVE, SENSOR_ADDR) < 0) {
        printf("Failed to acquire bus access or talk to slave\n");
        return 1;
    }

    FILE *file = fopen("flow_data.txt", "w");
    if (file == NULL) {
        printf("Failed to open file\n");
        return 1;
    }

    while (1) {
        usleep(45000); // Wait at least 45ms

        unsigned char buffer[9];
        if (read(file_i2c, buffer, 9) != 9) {
            printf("Failed to read from the i2c bus\n");
            continue;
        }

        if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5] || crc8(buffer + 5, 3) != buffer[8]) {
            printf("CRC check failed\n");
            continue;
        }

        time_t now = time(NULL);
        fprintf(file, "%s: DP=%d.%d, T=%d.%d, SF=%d.%d.%d\n", ctime(&now), buffer[0], buffer[1], buffer[3], buffer[4], buffer[6], buffer[7], buffer[8]);
        fflush(file);
    }

    fclose(file);
    close(file_i2c);
    return 0;
}

