#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>

#define MLX90614_ADDR 0x5A // MLX90614 I2C address
#define FAN_PIN 18 // GPIO pin for the cooling fan
#define HYSTERESIS 2 // Hysteresis value

int fd; // I2C file descriptor

void handle_signal(int signum) {
    digitalWrite(FAN_PIN, LOW);
    close(fd);
    exit(0);
}

float read_temp(int addr, int reg) {
    int nRetries = 3;
    int i;
    for (i = 0; i < nRetries; i++) {
        int data = wiringPiI2CReadReg16(fd, reg);
        if (data != -1) {
            float temp = (data & 0xFFF);
            temp *= 0.02;
            temp -= 273.15;
            return temp;
        }
        delay(10);
    }
    return -1;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (wiringPiSetupGpio() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(FAN_PIN, OUTPUT);

    fd = wiringPiI2CSetup(MLX90614_ADDR);
    if (fd == -1) {
        printf("Failed to setup I2C\n");
        return 1;
    }

    FILE *file = fopen("temperature_log.txt", "w");
    if (file == NULL) {
        printf("Failed to open file\n");
        return 1;
    }

    while (1) {
        float obj_temp = read_temp(MLX90614_ADDR, 0x2C);
        float amb_temp = read_temp(MLX90614_ADDR, 0x2E);

        if (obj_temp != -1 && amb_temp != -1) {
            time_t now = time(NULL);
            fprintf(file, "%ld, %.2f, %.2f\n", now, obj_temp, amb_temp);
            fflush(file);

            if (obj_temp > 30) {
                digitalWrite(FAN_PIN, HIGH);
            } else if (obj_temp < 28 - HYSTERESIS) {
                digitalWrite(FAN_PIN, LOW);
            }
        }

        delay(2000);
    }

    fclose(file);
    return 0;
}

