#include <fcntl.h>

#define TMP102_ADDR 0x48 // TMP102 I2C address
#define I2C_BUS "/dev/i2c-1"

int fd;

void sigint_handler(int sig) {
    printf("\nClosing I2C handle and exiting...\n");
    close(fd);
    exit(0);
}

float read_temperature() {
    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
        return -1;
    }
    int16_t raw = (buffer[0] << 8) | buffer[1];
    return (float)raw * 0.0625; // TMP102 resolution is 0.0625°C
}

void log_temperature() {
    FILE *file = fopen("temperature_log.csv", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", tm_info);

    float temperature = read_temperature();
    if (temperature != -1) {
        fprintf(file, "%s,%.2f\n", timestamp, temperature);
    }

    fclose(file);
}

int main() {
    signal(SIGINT, sigint_handler);

    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, TMP102_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access or talk to slave: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        log_temperature();
        sleep(5);
    }

    return 0;
}

