    fd = wiringPiSPISetup(SPI_CHANNEL, 500000);
    if (fd == -1) {
        printf("Failed to setup SPI\n");
        return 1;
    }

    struct sigaction action;
    action.sa_handler = handle_term;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    FILE *log_file = fopen("reflow_log.csv", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    while (1) {
        char data[2] = {0};
        if (wiringPiSPIDataRW(SPI_CHANNEL, data, 2) == -1) {
            printf("Failed to read from SPI\n");
            return 1;
        }

        int temp = ((data[0] << 8) | data[1]) >> 3;
        if (temp & 0x4) {
            printf("Sensor not present\n");
            return 1;
