#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>

#define AHT20_I2C_ADDR 0x38
#define AHT20_CMD_TRIGGER 0xAC33
#define AHT20_CMD_SOFTRESET 0xBA00
#define AHT20_GPIO_PIN 17
#define HUMIDITY_THRESHOLD_HIGH 60
#define HUMIDITY_THRESHOLD_LOW 55

int fd;

void cleanup(int signum) {
    digitalWrite(AHT20_GPIO_PIN, LOW);
    close(fd);
    exit(0);
}

int main() {
    int res;
    float humidity;
    int retry_count;

    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to setup wiringPi: %s\n", strerror(errno));
        return 1;
    }

    pinMode(AHT20_GPIO_PIN, OUTPUT);

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    fd = wiringPiI2CSetup(AHT20_I2C_ADDR);
    if (fd == -1) {
        fprintf(stderr, "Failed to setup I2C: %s\n", strerror(errno));
        return 1;
    }

    wiringPiI2CWriteReg16(fd, 0x20, AHT20_CMD_SOFTRESET);
    delay(10);

    for (;;) {
        retry_count = 0;
        while (retry_count < 3) {
            wiringPiI2CWriteReg16(fd, 0x20, AHT20_CMD_TRIGGER);
            delay(80);

            res = wiringPiI2CReadReg16(fd, 0x22);
            if ((res & 0x8000) == 0) {
                break;
            }

            delay(10);
            retry_count++;
        }

        if (retry_count == 3) {
            fprintf(stderr, "Failed to read from AHT20 sensor: %s\n", strerror(errno));
            continue;
        }

        humidity = ((res & 0x0000FF00) >> 8) * 100.0 / 256.0;
        printf("%ld,%.2f%%\n", time(NULL), humidity);

        if (humidity > HUMIDITY_THRESHOLD_HIGH) {
            digitalWrite(AHT20_GPIO_PIN, HIGH);
        } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
            digitalWrite(AHT20_GPIO_PIN, LOW);
        }

        delay(5000);
    }

    return 0;
}

