#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x76 // BMP280 I2C address
#define CHIP_ID 0x58 // BMP280 Chip ID
#define RETRY_COUNT 3

bmp280_t bmp280;

void handle_signal(int signum) {
    bmp280_close(&bmp280);
    exit(0);
}

int main() {
    int fd, ret, retry_count;
    uint8_t chip_id;
    FILE *file;
    struct bmp280_dev dev;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    ioctl(fd, I2C_SLAVE, I2C_ADDR);

    dev.fd = fd;
    dev.read = bmp280_i2c_read;
    dev.write = bmp280_i2c_write;

    bmp280_init(&bmp280, &dev);

    for (retry_count = 0; retry_count < RETRY_COUNT; retry_count++) {
        bmp280_read_chip_id(&chip_id, &bmp280);
        if (chip_id == CHIP_ID) {
            break;
        }
        usleep(100000); // Wait 100ms
    }

    if (chip_id != CHIP_ID) {
        printf("Failed to verify BMP280 chip ID\n");
        return 1;
    }

    file = fopen("pressure_log.txt", "w");
    if (file == NULL) {
        perror("Failed to open file");
        return 1;
    }

    while (1) {
        float pressure;
        time_t now;
        struct tm *timeinfo;
        char buffer[80];

        bmp280_read_pressure(&pressure, &bmp280);

        if (pressure > 1020.0 || pressure < 980.0) {
            time(&now);
            timeinfo = localtime(&now);
            strftime(buffer, sizeof(buffer), "%d-%m-%Y %H:%M:%S", timeinfo);
            fprintf(file, "%s: %f hPa\n", buffer, pressure);
        }

        usleep(2000000); // Wait 2 seconds
    }

    fclose(file);
    bmp280_close(&bmp280);
    close(fd);

    return 0;
}

