#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27

#define CPU_LOAD_FILE "/proc/stat"
#define SAMPLE_INTERVAL 500

void handle_signal(int signum) {
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE* file = fopen(CPU_LOAD_FILE, "r");
    if (file == NULL) {
        fprintf(stderr, "Failed to open CPU load file\n");
        return 1;
    }

    unsigned long prev_total = 0, prev_idle = 0;
    fscanf(file, "cpu %lu %lu %lu %lu %lu %lu %lu %lu", &prev_total, &prev_idle);

    while (1) {
        unsigned long total, idle, diff_total, diff_idle;
        fseek(file, 0, SEEK_SET);
        fscanf(file, "cpu %lu %lu %lu %lu %lu %lu %lu %lu", &total, &idle, &diff_total, &diff_idle);

        double load = (double)(diff_total - diff_idle) / (double)(total - idle);
        int color = (int)(load * 255);

        gpioPWM(RED_PIN, color);
        gpioPWM(GREEN_PIN, 255 - color);
        gpioPWM(BLUE_PIN, 0);

        prev_total = total;
        prev_idle = idle;

        time_sleep(SAMPLE_INTERVAL / 1000.0);
    }

    fclose(file);
    gpioTerminate();

    return 0;
}

