        fseek(file, 0, SEEK_SET);
        fscanf(file, "cpu %lu %lu %lu %lu %lu %lu %lu %lu", &total, &idle, &diff_total, &diff_idle);

        double load = (double)(diff_total - diff_idle) / (double)(total - idle);
        int color = (int)(load * 255);

        gpioPWM(RED_PIN, color);
        gpioPWM(GREEN_PIN, 255 - color);
        gpioPWM(BLUE_PIN, 0);

        prev_total = total;
        prev_idle = idle;

        time_sleep(SAMPLE_INTERVAL / 1000.0);
    }

    fclose(file);
    gpioTerminate();

    return 0;
}
