#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <softPwm.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define GPIO_FAN 18
#define GPIO_TEMP_CS 8
#define BUFFER_SIZE 20

int buffer[BUFFER_SIZE][3];
int buffer_index = 0;

void handle_sigint(int sig) {
    softPwmWrite(GPIO_FAN, 0);
    digitalWrite(GPIO_TEMP_CS, LOW);
    wiringPiSPIDataRW(SPI_CHANNEL, NULL, 0);
    exit(0);
}

int main() {
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to setup wiringPi\n");
        return 1;
    }

    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "Failed to setup SPI\n");
        return 1;
    }

    pinMode(GPIO_FAN, PWM_OUTPUT);
    pinMode(GPIO_TEMP_CS, OUTPUT);

    signal(SIGINT, handle_sigint);

    while (1) {
        digitalWrite(GPIO_TEMP_CS, HIGH);
        delay(1);
        int temp = wiringPiSPIDataRW(SPI_CHANNEL, NULL, 0);
        digitalWrite(GPIO_TEMP_CS, LOW);

        if (temp == -1) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        int duty_cycle;
        if (temp < 25) {
            duty_cycle = 0;
        } else if (temp < 40) {
            duty_cycle = (temp - 25) * 51;
        } else if (temp < 60) {
            duty_cycle = 50 + (temp - 40) * 155;
        } else {
            duty_cycle = 200 + (temp - 60) * 100;
        }

        softPwmWrite(GPIO_FAN, duty_cycle);

        buffer[buffer_index][0] = time(NULL);
        buffer[buffer_index][1] = temp;
        buffer[buffer_index][2] = duty_cycle;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        delay(1000);
    }

    return 0;
}

