#define GPIO_PIN 2
#define I2C_BUS 1
#define BMP180_ADDR 0x77

int fd;
FILE *file;

void handle_interrupt() {
    // Toggle logging
}

void handle_sigint(int sig) {
    // Close I2C handle, close log file, and release GPIO
    close(fd);
    fclose(file);
    digitalWrite(GPIO_PIN, LOW);
    exit(0);
}

int main() {
    struct bmp180_dev dev;
    struct bmp180_uncomp data;
    struct bmp180_settings settings;
    int err;

    // Set up GPIO
    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }
    pinMode(GPIO_PIN, INPUT);
    pullUpDnControl(GPIO_PIN, PUD_UP);
    wiringPiISR(GPIO_PIN, INT_EDGE_FALLING, &handle_interrupt);

    // Set up I2C
    fd = bmp180_i2c_init(I2C_BUS, BMP180_ADDR);
    if (fd < 0) {
        printf("Failed to setup I2C\n");
        return 1;
    }

    // Set up BMP180
    err = bmp180_init(&dev, fd);
    if (err < 0) {
        printf("Failed to initialize BMP180\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Main loop
    while (1) {
        // Read data from BMP180
        err = bmp180_get_uncomp_pressure(&dev, &data);
        if (err < 0) {
            printf("Failed to read BMP180 data\n");
            continue;
        }

        // Convert data to Celsius and Pa
        float temp = bmp180_compensate_temp(dev.cal, data.temp);
        float press = bmp180_compensate_pressure(dev.cal, data.press);

        // Append data to log file
        time_t now = time(NULL);
        fprintf(file, "%ld,%f,%f\n", now, temp, press);
        fflush(file);

        // Sleep for one second
        sleep(1);
    }

    return 0;
}

