#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <bme280.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR BME280_I2C_ADDR_PRIM
#define DEVICE_FILE "/dev/bme280_log.csv"

int fd;

void sig_handler(int signum) {
    close(fd);
    remove(DEVICE_FILE);
    exit(0);
}

int main() {
    struct bme280_dev dev;
    int8_t rslt = BME280_OK;
    uint8_t settings_sel;
    uint32_t delay;

    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        printf("Failed to open i2c bus\n");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        printf("Failed to acquire bus access or talk to slave\n");
        return 1;
    }

    dev.dev_id = I2C_ADDR;
    dev.intf = BME280_I2C_INTF;
    dev.read = bme280_i2c_read;
    dev.write = bme280_i2c_write;
    dev.delay_us = bme280_delay_us;

    rslt = bme280_init(&dev);

    if (rslt != BME280_OK) {
        printf("Failed to initialize the device (code %+d).\n", rslt);
        return 1;
    }

    settings_sel = BME280_OSR_PRESS_SEL | BME280_OSR_TEMP_SEL | BME280_OSR_HUM_SEL | BME280_FILTER_SEL;
    rslt = bme280_set_sensor_settings(settings_sel, &dev);

    if (rslt != BME280_OK) {
        printf("Failed to set sensor settings (code %+d).\n", rslt);
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        struct bme280_data comp_data;
        bme280_get_sensor_data(BME280_ALL, &comp_data, &dev);

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char timestamp[20];
        sprintf(timestamp, "%d-%02d-%02d %02d:%02d:%02d", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);

        FILE *file = fopen(DEVICE_FILE, "a");
        if (file == NULL) {
            printf("Failed to open file\n");
            return 1;
        }

        fprintf(file, "%s,%.2f,%.2f,%.2f\n", timestamp, comp_data.temperature, comp_data.humidity, comp_data.pressure);
        fclose(file);

        delay = bme280_cal_meas_delay(&dev);
        bme280_delay_us(delay, dev.delay_us);
    }

    return 0;
}

