#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <bmp180.h>
#include <pigpio.h>

#define I2C_BUS 1
#define GPIO_ALERT 24
#define SAMPLE_RATE_MS 50
#define BUFFER_SIZE 600
#define ALERT_THRESHOLD 5

struct bmp180_dev dev;
struct bmp180_uncomp_data uncomp_data;
struct bmp180_comp_data comp_data;
float pressure_buffer[BUFFER_SIZE];
int buffer_index = 0;

void sigint_handler(int sig) {
    gpioTerminate();
    bmp180_close(&dev);
    exit(0);
}

float compute_rolling_average() {
    float sum = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += pressure_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

void sample_pressure() {
    if (bmp180_read_uncomp_pressure(&dev, &uncomp_data) < 0) {
        fprintf(stderr, "Failed to read uncompensated pressure\n");
        return;
    }

    if (bmp180_uncomp_to_comp(&dev, &uncomp_data, &comp_data) < 0) {
        fprintf(stderr, "Failed to convert uncompensated pressure to compensated\n");
        return;
    }

    pressure_buffer[buffer_index++ % BUFFER_SIZE] = comp_data.pressure;
    float rolling_average = compute_rolling_average();

    if (fabs(comp_data.pressure - rolling_average) > ALERT_THRESHOLD) {
        gpioWrite(GPIO_ALERT, 1);
        fprintf(stderr, "Alert: Pressure deviates by more than %.2f hPa from rolling average\n", ALERT_THRESHOLD);
    } else {
        gpioWrite(GPIO_ALERT, 0);
    }
}

int main() {
    signal(SIGINT, sigint_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (bmp180_init(&dev, I2C_BUS) < 0) {
        fprintf(stderr, "Failed to initialize BMP180\n");
        return 1;
    }

    gpioSetMode(GPIO_ALERT, PI_OUTPUT);

    while (1) {
        sample_pressure();
        gpioDelay(SAMPLE_RATE_MS * 1000);
    }

    return 0;
}

