#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <bmp180.h>

#define BMP180_DEVICE "/dev/i2c-1"
#define LOG_FILE "bmp180_log.txt"

bmp180Dev* bmp180;
FILE* logFile;

void handle_signal(int signum) {
    printf("Exiting...\n");
    fclose(logFile);
    bmp180_close(bmp180);
    exit(0);
}

void write_to_log(float temperature, int pressure) {
    time_t now = time(NULL);
    struct tm* timestamp = localtime(&now);
    fprintf(logFile, "%d-%02d-%02d %02d:%02d:%02d, %.2f, %d\n",
            timestamp->tm_year + 1900, timestamp->tm_mon + 1, timestamp->tm_mday,
            timestamp->tm_hour, timestamp->tm_min, timestamp->tm_sec,
            temperature, pressure);
    fflush(logFile);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    logFile = fopen(LOG_FILE, "w");
    if (logFile == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    bmp180 = bmp180_open(BMP180_DEVICE);
    if (bmp180 == NULL) {
        perror("Failed to open BMP180 device");
        return 1;
    }

    if (bmp180_init(bmp180) < 0) {
        perror("Failed to initialize BMP180");
        return 1;
    }

    // Validate calibration data
    if (bmp180_validate_coefficients(bmp180) < 0) {
        perror("Failed to validate BMP180 coefficients");
        return 1;
    }

    // Set up timer
    struct sigevent sev;
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGALRM;
    timer_t timerid;
    if (timer_create(CLOCK_REALTIME, &sev, &timerid) == -1) {
        perror("Failed to create timer");
        return 1;
    }

    struct itimerspec its;
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 500000000;  // 500 ms
    its.it_interval = its.it_value;
    if (timer_settime(timerid, 0, &its, NULL) == -1) {
        perror("Failed to set timer");
        return 1;
    }

    // Main loop
    while (1) {
        pause();  // Wait for signal

        float temperature;
        int pressure;
        if (bmp180_read_temperature(bmp180, &temperature) < 0) {
            perror("Failed to read temperature");
            continue;
        }

        if (bmp180_read_pressure(bmp180, BMP180_OVERSAMPLING_ULTRA_LOW_POWER, &pressure) < 0) {
            perror("Failed to read pressure");
            continue;
        }

        write_to_log(temperature, pressure);
    }

    return 0;
}

