#include <stdio.h>
#include <stdlib.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>

#define THERMAL_ZONE "/sys/class/thermal/thermal_zone0/temp"
#define GPIO_PWM_PIN 18
#define PWM_FREQ 25000
#define LOG_FILE "fan_log.txt"

int pwm;
FILE *log;

void handle_signal(int signum) {
    fprintf(stderr, "Received signal %d, stopping fan and exiting...\n", signum);
    digitalWrite(GPIO_PWM_PIN, LOW);
    fclose(log);
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Failed to setup wiringPi\n");
        return 1;
    }

    if ((log = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    pinMode(GPIO_PWM_PIN, PWM_OUTPUT);
    pwm = PWM_FREQ;
    pwmSetMode(PWM_MODE_MS);
    pwmSetClock(4);
    pwmSetRange(255);

    while (1) {
        FILE *temp_file = fopen(THERMAL_ZONE, "r");
        if (temp_file == NULL) {
            fprintf(stderr, "Failed to open thermal zone file\n");
            return 1;
        }

        int temp;
        if (fscanf(temp_file, "%d", &temp) != 1) {
            fprintf(stderr, "Failed to read temperature\n");
            fclose(temp_file);
            return 1;
        }
        fclose(temp_file);

        temp = temp / 1000; // Convert to Celsius
        if (temp < 40) temp = 40;
        if (temp > 70) temp = 70;

        int duty_cycle = (temp - 40) * 100 / 30; // Map to 0-255

        pwmWrite(GPIO_PWM_PIN, duty_cycle);

        time_t now = time(NULL);
        fprintf(log, "%s, Temp: %d°C, Duty cycle: %d%%\n", ctime(&now), temp, duty_cycle);
        fflush(log);

        delay(5000);
    }

    return 0;
}

