    gpioPWM(PWM_PIN, PWM_FREQ, (int)(duty * PWM_RANGE));
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpioSetMode(PWM_PIN, PI_OUTPUT);

    double integral = 0.0;
    double last_error = 0.0;
    double pwm_duty = 0.0;

    while (!stop) {
