        integral += error;
        double derivative = error - last_error;
        last_error = error;

        pwm_duty = KP * error + KI * integral + KD * derivative;

        if (pwm_duty < 0.0) pwm_duty = 0.0;
        if (pwm_duty > PWM_RANGE) pwm_duty = PWM_RANGE;

        set_pwm_duty(pwm_duty);

        usleep(100000);  // Wait for 100ms
    }

    gpioTerminate();
    return 0;
