            if (file != NULL) {
                fprintf(file, "%s - Temp: %d.%d°C, Pressure: %ldPa\n", timestamp, temp / 100, temp % 100, pressure);
                fclose(file);
            }
        }

        delay(1000);
    }

    return 0;
}

