#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <bmp180.h>

#define I2C_BUS 1
#define GPIO_FAN 18
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL 500 // in ms

bmp180_t bmp180;
struct bmp180_calib_data cal;
struct circular_buffer {
    struct reading {
        int temp;
        int press;
    } data[BUFFER_SIZE];
    int head;
    int tail;
} buffer;

void alarm_handler(int signum) {
    int temp, press;
    if (bmp180_read_temp(&bmp180, &temp) < 0) return;
    if (bmp180_read_press(&bmp180, &press) < 0) return;

    buffer.data[buffer.head].temp = temp;
    buffer.data[buffer.head].press = press;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    if (buffer.head == buffer.tail) buffer.tail = (buffer.tail + 1) % BUFFER_SIZE;

    printf("Temperature: %d, Pressure: %d\n", temp, press);

    if (temp > 3000) {
        gpioWrite(GPIO_FAN, 1);
    } else {
        gpioWrite(GPIO_FAN, 0);
    }
}

void cleanup(int signum) {
    gpioWrite(GPIO_FAN, 0);
    bmp180_close(&bmp180);
    pigpio_stop();
    exit(0);
}

int main() {
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        return 1;
    }

    if (bmp180_open(&bmp180, I2C_BUS, BMP180_ADDR) < 0) {
        fprintf(stderr, "Failed to open BMP180\n");
        return 1;
    }

    if (bmp180_read_cal(&bmp180, &cal) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        return 1;
    }

    buffer.head = 0;
    buffer.tail = 0;

    if (gpioSetMode(GPIO_FAN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);
    signal(SIGALRM, alarm_handler);
    alarm(SAMPLE_INTERVAL);

    while (1) {
        pause();
    }

    return 0;
}

