#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define MAX31855_READ_CMD 0x01
#define GPIO_HEATER 17
#define GPIO_CS 8
#define TARGET_TEMP 25.0
#define MAX_DUTY_CYCLE 80.0

FILE *log_file;

void handle_signal(int signum) {
    // Turn off the heater
    pwmWrite(GPIO_HEATER, 0);

    // Close the SPI interface
    wiringPiSPIDataRW(SPI_CHANNEL, NULL, 0);

    // Close the log file
    fclose(log_file);

    // Terminate the program
    exit(0);
}

int main() {
    // Set up GPIO
    if (wiringPiSetupGpio() == -1) {
        printf("Failed to setup GPIO\n");
        return 1;
    }

    // Set up SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        printf("Failed to setup SPI\n");
        return 1;
    }

    // Set up GPIO for heater
    pinMode(GPIO_HEATER, PWM_OUTPUT);

    // Set up GPIO for chip select
    pinMode(GPIO_CS, OUTPUT);
    digitalWrite(GPIO_CS, HIGH);

    // Open log file
    log_file = fopen("heater_log.csv", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        // Read temperature from MAX31855
        unsigned char spi_data[2] = {MAX31855_READ_CMD, 0};
        digitalWrite(GPIO_CS, LOW);
        wiringPiSPIDataRW(SPI_CHANNEL, spi_data, 2);
        digitalWrite(GPIO_CS, HIGH);

        // Parse temperature from SPI data
        int16_t temp = (spi_data[0] << 8) | spi_data[1];
        temp = temp >> 4;
        float celsius = temp * 0.25;

        // Calculate duty cycle
        float duty_cycle = (celsius - TARGET_TEMP) / (MAX_DUTY_CYCLE / 100.0);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 100) duty_cycle = 100;

        // Set PWM duty cycle
        pwmWrite(GPIO_HEATER, duty_cycle);

        // Log measurement
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
        fprintf(log_file, "%s,%f,%f\n", timestamp, celsius, duty_cycle);
        fflush(log_file);

        // Sleep for a while
        delay(1000);
    }

    return 0;
}

