#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
    gpioWrite(RED_PIN, 255);
    gpioWrite(GREEN_PIN, 255);
    gpioWrite(BLUE_PIN, 255);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    FILE* tempFile = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (tempFile == NULL) {
        fprintf(stderr, "Failed to open temperature file\n");
        return 1;
    }

    while (!stop) {
        unsigned int temp;
        if (fscanf(tempFile, "%u", &temp) != 1 || ferror(tempFile)) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        temp /= 1000; // Convert to millidegrees Celsius

        unsigned int red = 0, green = 0, blue = 0;
        if (temp < 40000) {
            blue = 255;
        } else if (temp < 60000) {
            green = 255;
        } else {
            red = 255;
        }

        gpioWrite(RED_PIN, 255 - red);
        gpioWrite(GREEN_PIN, 255 - green);
        gpioWrite(BLUE_PIN, 255 - blue);

        printf("Temperature: %u.%03u°C, Red: %u, Green: %u, Blue: %u\n",
               temp / 1000, temp % 1000, red, green, blue);

        time_sleep(0.5);
    }

    fclose(tempFile);
    gpioTerminate();

    return 0;
}

