#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <wiringPi.h>
#include <bmp180.h>

#define GPIO_PIN 4
#define OSS 3
#define DEBOUNCE_TIME 200000

int fd;
unsigned long lastDebounceTime = 0;
int loggingEnabled = 0;
FILE *file;

void handleInterrupt() {
    unsigned long debounceDelay = micros() - lastDebounceTime;
    if (debounceDelay >= DEBOUNCE_TIME) {
        loggingEnabled = !loggingEnabled;
        lastDebounceTime = micros();
        if (loggingEnabled) {
            file = fopen("pressure_log.txt", "a");
            if (file == NULL) {
                perror("Error opening file");
                exit(1);
            }
        } else {
            printf("Logging disabled\n");
            fclose(file);
        }
    }
}

int main() {
    struct bmp180_dev dev;
    int8_t rslt;
    int32_t pressure;

    if (signal(SIGINT, SIG_IGN) == SIG_ERR) {
        perror("Error setting up signal handler");
        return 1;
    }

    rslt = wiringPiSetup();
    if (rslt != 0) {
        fprintf(stderr, "Error setting up wiringPi: %d\n", rslt);
        return 1;
    }

    pinMode(GPIO_PIN, INPUT);
    pullUpDnControl(GPIO_PIN, PUD_UP);
    wiringPiISR(GPIO_PIN, INT_EDGE_FALLING, &handleInterrupt);

    fd = bmp180_init(BMP180_I2C_ADDR_LOW, BMP180_I2C_BUS);
    if (fd < 0) {
        fprintf(stderr, "Error initializing BMP180: %d\n", fd);
        return 1;
    }

    rslt = bmp180_set_oss(fd, OSS);
    if (rslt != 0) {
        fprintf(stderr, "Error setting oversampling setting: %d\n", rslt);
        return 1;
    }

    while (1) {
        if (loggingEnabled) {
            rslt = bmp180_get_pressure(&dev, &pressure);
            if (rslt != 0) {
                fprintf(stderr, "Error reading pressure: %d\n", rslt);
                return 1;
            }
            fprintf(file, "%lu,%d\n", millis(), pressure / 100);
            delay(2000);
        }
    }

    bmp180_close(fd);
    return 0;
}

