#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define MAX31855_CLK 11
#define MAX31855_CS 8
#define MAX31855_DO 9
#define HEATER_PWM 18

#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

#define TARGET_TEMP 50.0

#define SPI_SPEED 500000

struct gpiod_chip *chip;
struct gpiod_line *pwm_line;

void cleanup(int signum) {
    gpiod_line_set_value(pwm_line, 0);
    gpiod_line_release(pwm_line);
    gpiod_chip_close(chip);
    exit(0);
}

double read_temp() {
    int fd;
    uint8_t tx[4] = {0};
    uint8_t rx[4] = {0};

    if ((fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        perror("Could not open SPI device");
        exit(1);
    }

    if (ioctl(fd, SPI_MODE, SPI_SPEED) < 0) {
        perror("Could not set SPI speed");
        exit(1);
    }

    if (write(fd, tx, 4) != 4) {
        perror("Could not write to SPI device");
        exit(1);
    }

    if (read(fd, rx, 4) != 4) {
        perror("Could not read from SPI device");
        exit(1);
    }

    close(fd);

    return ((rx[0] << 8) | rx[1]) / 32.0;
}

void set_pwm(double duty) {
    gpiod_line_set_value(pwm_line, duty);
}

int main() {
    double temp, error, integral = 0.0, derivative = 0.0, pwm_duty = 0.0;
    FILE *log_file;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Could not open GPIO chip");
        exit(1);
    }

    pwm_line = gpiod_chip_get_line(chip, HEATER_PWM);
    if (!pwm_line) {
        perror("Could not get GPIO line");
        exit(1);
    }

    if (gpiod_line_request_output(pwm_line, "heater", 0) < 0) {
        perror("Could not request GPIO line as output");
        exit(1);
    }

    log_file = fopen("heater_log.txt", "w");
    if (!log_file) {
        perror("Could not open log file");
        exit(1);
    }

    while (1) {
        temp = read_temp();
        error = TARGET_TEMP - temp;
        integral += error;
        derivative = error - (TARGET_TEMP - temp);

        if (temp > 100.0 || temp < 0.0) {
            fprintf(log_file, "Temperature out of range: %.2f\n", temp);
            set_pwm(0);
            continue;
        }

        pwm_duty = Kp * error + Ki * integral + Kd * derivative;
        if (pwm_duty > 100.0) pwm_duty = 100.0;
        if (pwm_duty < 0.0) pwm_duty = 0.0;

        set_pwm(pwm_duty);

        fprintf(log_file, "Temperature: %.2f, PWM Duty: %.2f, PID Output: %.2f\n", temp, pwm_duty, error);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    gpiod_line_release(pwm_line);
    gpiod_chip_close(chip);

    return 0;
}

