#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PWM 18
#define CPU_TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define PWM_FREQ 25000
#define MIN_TEMP 40
#define MAX_TEMP 70

void handle_signal(int signum) {
    gpioWrite(GPIO_PWM, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE* cpu_temp_file = fopen(CPU_TEMP_FILE, "r");
    if (cpu_temp_file == NULL) {
        fprintf(stderr, "Failed to open CPU temperature file\n");
        return 1;
    }

    FILE* log_file = fopen("cooling_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    fprintf(log_file, "Timestamp,Temperature (°C),PWM Duty Cycle (%)\n");

    gpioSetMode(GPIO_PWM, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_PWM, PWM_FREQ);

    while (1) {
        unsigned int cpu_temp;
        fscanf(cpu_temp_file, "%u", &cpu_temp);
        cpu_temp /= 1000; // Convert from millidegrees to degrees

        unsigned int pwm_duty_cycle = (cpu_temp - MIN_TEMP) * 100 / (MAX_TEMP - MIN_TEMP);
        if (pwm_duty_cycle > 100) {
            pwm_duty_cycle = 100;
        }

        gpioPWM(GPIO_PWM, pwm_duty_cycle * PWM_FREQ / 100);

        time_t now = time(NULL);
        fprintf(log_file, "%lu,%u,%u\n", now, cpu_temp, pwm_duty_cycle);
        fflush(log_file);

        sleep(5);
    }

    return 0;
}

