#define GPIO_PIN 18

volatile unsigned int pulseCount = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *logFile;

void handleSignal(int signum) {
    pthread_mutex_lock(&mutex);
    fclose(logFile);
    pthread_mutex_unlock(&mutex);
    exit(0);
}

void handleInterrupt() {
    pthread_mutex_lock(&mutex);
    pulseCount++;
    pthread_mutex_unlock(&mutex);
}

void *readSensor(void *arg) {
    while (1) {
        sleep(1);
        pthread_mutex_lock(&mutex);
        double rpm = pulseCount * 60.0;
        time_t now = time(NULL);
        fprintf(logFile, "%ld, %.2f\n", now, rpm);
        fflush(logFile);
        pulseCount = 0;
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

int main() {
    if (wiringPiSetup() == -1) {
        printf("Failed to initialize wiringPi library\n");
        return 1;
    }

    if (wiringPiISSetupInterrupt(GPIO_PIN) == -1) {
        printf("Failed to setup ISR\n");
        return 1;
    }

    logFile = fopen("rpm_log.txt", "a");
    if (logFile == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, handleSignal);
    signal(SIGTERM, handleSignal);

    pthread_t thread;
    pthread_create(&thread, NULL, readSensor, NULL);

    wiringPiISR(GPIO_PIN, INT_EDGE_RISING, &handleInterrupt);

    while (1) {
        delay(1000);
    }

    return 0;
}

