#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_INPUT "17"
#define GPIO_OUTPUT "18"
#define GPIO_CHIP "gpiochip0"
#define SAMPLE_RATE 10000 // in microseconds

struct gpiod_chip *chip;
struct gpiod_line *input_line, *output_line;

void signal_handler(int signum) {
    printf("Exiting...\n");
    gpiod_line_release(input_line);
    gpiod_line_release(output_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    input_line = gpiod_chip_get_line(chip, atoi(GPIO_INPUT));
    if (!input_line) {
        perror("Failed to get GPIO input line");
        return 1;
    }

    output_line = gpiod_chip_get_line(chip, atoi(GPIO_OUTPUT));
    if (!output_line) {
        perror("Failed to get GPIO output line");
        return 1;
    }

    if (gpiod_line_request_input(input_line, "audio_monitor") < 0) {
        perror("Failed to request GPIO input");
        return 1;
    }

    if (gpiod_line_request_output(output_line, "gain_control", 0) < 0) {
        perror("Failed to request GPIO output");
        return 1;
    }

    printf("Starting audio monitoring...\n");

    FILE *log_file = fopen("audio_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    int last_state = 0;
    while (1) {
        int current_state = gpiod_line_get_value(input_line);
        if (current_state != last_state && current_state == 1) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(log_file, "%s 1\n", timestamp);
            printf("%s 1\n", timestamp);
        }
        last_state = current_state;
        usleep(SAMPLE_RATE);
    }

    fclose(log_file);
    gpiod_line_release(input_line);
    gpiod_line_release(output_line);
    gpiod_chip_close(chip);
    return 0;
}

