#include <gpiod.h>

#define GPIO_LINE 17
#define TAMPER_TIMEOUT 5000000000 // 5 seconds in nanoseconds
#define POLL_INTERVAL 100000000 // 100 ms in nanoseconds

struct gpiod_line *line;
struct gpiod_chip *chip;

void cleanup(int signum) {
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int main(void) {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(line, "ttp223_tamper");
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct timespec last_touch = {0, 0};
    struct timespec now;
    int tamper_detected = 0;

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (gpiod_line_get_value(line) == 1) {
            if (tamper_detected == 0 && (now.tv_sec - last_touch.tv_sec > 5 || (now.tv_sec - last_touch.tv_sec == 5 && now.tv_nsec - last_touch.tv_nsec >= TAMPER_TIMEOUT))) {
                printf("Tamper detected\n");
                tamper_detected = 1;
                last_touch = now;
            }
        } else {
            tamper_detected = 0;
            last_touch = now;
        }
        usleep(POLL_INTERVAL / 1000); // Sleep for 100 ms
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

