#include <alsa/asoundlib.h>
#include <wiringPi.h>
#include <signal.h>
#include <stdio.h>

#define GPIO_PIN 17
#define I2S_DEVICE "hw:C0,0"
#define FILE_NAME "audio_capture.pcm"

snd_pcm_t *handle;
FILE *file;

void sigint_handler(int sig) {
    snd_pcm_close(handle);
    fclose(file);
    digitalWrite(GPIO_PIN, LOW);
    exit(0);
}

int main() {
    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(GPIO_PIN, OUTPUT);
    digitalWrite(GPIO_PIN, LOW);

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        printf("Failed to register signal handler\n");
        return 1;
    }

    if (snd_pcm_open(&handle, I2S_DEVICE, SND_PCM_STREAM_CAPTURE, 0) < 0) {
        printf("Failed to open I2S device\n");
        return 1;
    }

    if (snd_pcm_set_params(handle, SND_PCM_FORMAT_S16_LE, SND_PCM_ACCESS_RW_INTERLEAVED, 1, 44100, 1, 500000) < 0) {
        printf("Failed to set I2S parameters\n");
        return 1;
    }

    file = fopen(FILE_NAME, "wb");
    if (file == NULL) {
        printf("Failed to open file\n");
        return 1;
    }

    char buffer[4096];
    while (1) {
        int r = snd_pcm_readi(handle, buffer, 4096 / sizeof(short));
        if (r < 0) {
            printf("Failed to read from I2S device: %s\n", snd_strerror(r));
            return 1;
        }

        fwrite(buffer, sizeof(short), r, file);
        if (ferror(file)) {
            printf("Failed to write to file\n");
            return 1;
        }

        digitalWrite(GPIO_PIN, !digitalRead(GPIO_PIN)); // Toggle GPIO pin
    }

    return 0;
}

