#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <stdio.h>

#define SENSOR_GPIO 4
#define FAN_GPIO 18
#define DEBOUNCE_MS 50

FILE *logFile;

void signalHandler(int signum) {
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
    fclose(logFile);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    logFile = fopen("flame_log.txt", "w");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    time_t startTime = time(NULL);
    fprintf(logFile, "Program started at %s", ctime(&startTime));

    gpioSetMode(SENSOR_GPIO, PI_INPUT);
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    int lastSensorState = 0;
    int sensorState;
    time_t lastDebounceTime = time(NULL);

    while (1) {
        sensorState = gpioRead(SENSOR_GPIO);
        if (sensorState != lastSensorState) {
            lastDebounceTime = time(NULL);
        }

        if (time(NULL) - lastDebounceTime >= DEBOUNCE_MS / 1000) {
            if (sensorState == 0) {
                time_t flameEndTime = time(NULL);
                fprintf(logFile, "Flame end at %s", ctime(&flameEndTime));
                gpioWrite(FAN_GPIO, 0);
            } else {
                time_t flameStartTime = time(NULL);
                fprintf(logFile, "Flame start at %s", ctime(&flameStartTime));
                gpioWrite(FAN_GPIO, 1);
            }

            lastSensorState = sensorState;
        }
    }

    return 0;
}

