#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 20
#define FILE_NAME "flame_log.txt"
#define POLL_INTERVAL 100000 // 100ms

struct gpiod_chip *chip;
struct gpiod_line *line;
int previous_state = -1;
FILE *file;

void signal_handler(int signum) {
    fclose(file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    if (gpiod_line_request_input(line, "flame_sensor") < 0) {
        perror("Failed to request GPIO line as input");
        return 1;
    }

    file = fopen(FILE_NAME, "a");
    if (!file) {
        perror("Failed to open file");
        return 1;
    }

    while (1) {
        int current_state = gpiod_line_get_value(line);
        if (current_state != previous_state) {
            previous_state = current_state;

            time_t now = time(NULL);
            struct tm *ptm = gmtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%FT%TZ", ptm);

            fprintf(file, "%s,%s\n", timestamp, current_state ? "flame detected" : "flame cleared");
            fflush(file);
        }

        usleep(POLL_INTERVAL);
    }

    return 0;
}

