#include <signal.h>
#include <time.h>
#include <gpiod.h>

volatile sig_atomic_t stop;

void interrupt_handler(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    char *chipname = "gpiochip0";
    int lineno = 17;
    int value;
    time_t t;
    struct tm *tm;
    char buffer[50];

    signal(SIGINT, interrupt_handler);

    chip = gpiod_chip_open_by_name(chipname);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open chip %s\n", chipname);
        return 1;
    }

    line = gpiod_chip_get_line(chip, lineno);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d\n", lineno);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line, "flame_detect") != 0) {
        fprintf(stderr, "Failed to request line as input\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (!stop) {
        value = gpiod_line_get_value(line);
        if (value == -1) {
            fprintf(stderr, "Failed to read line value\n");
            break;
        }

        time(&t);
        tm = localtime(&t);
        strftime(buffer, sizeof(buffer), "%F %T", tm);

        if (value == 0) {
            printf("%s Flame Detected: YES\n", buffer);
        } else {
            printf("%s Flame Detected: NO\n", buffer);
        }

        sleep(1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

