#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define GPIO_DEVICE "/dev/gpiochip0"
#define GPIO_LINES {2, 3, 4, 5, 6, 7, 8, 9}
#define POLL_INTERVAL 100000 // 100ms

struct gpiod_chip *chip;
struct gpiod_line *lines[8];

void cleanup(void) {
    for (int i = 0; i < 8; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
}

void signal_handler(int signum) {
    printf("Exiting...\n");
    cleanup();
    exit(0);
}

int main(void) {
    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_DEVICE);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    for (int i = 0; i < 8; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_LINES[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get line %d\n", GPIO_LINES[i]);
            cleanup();
            return 1;
        }

        if (gpiod_line_request_input(lines[i], "ttp226-reader") < 0) {
            fprintf(stderr, "Failed to request input on line %d\n", GPIO_LINES[i]);
            cleanup();
            return 1;
        }
    }

    while (1) {
        time_t now = time(NULL);
        for (int i = 0; i < 8; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to read value from line %d\n", GPIO_LINES[i]);
                cleanup();
                return 1;
            }
            printf("%ld: Line %d: %d\n", now, GPIO_LINES[i], value);
        }
        usleep(POLL_INTERVAL);
    }

    return 0;
}

