#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_DEV "/dev/i2c-1"
#define SI1145_ADDR 0x60

int fd;
FILE *log_file;

void cleanup(int signum) {
    fclose(log_file);
    close(fd);
    exit(0);
}

int main() {
    unsigned char uv_index, als_visible;
    struct timespec ts;
    char timestamp[20];

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    log_file = fopen("uv_als_log.csv", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get timestamp");
            return 1;
        }

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        if (write(fd, &uv_index, 1) != 1) {
            perror("Failed to write to the i2c bus");
            return 1;
        }

        if (read(fd, &uv_index, 1) != 1) {
            perror("Failed to read from the i2c bus");
            return 1;
        }

        if (write(fd, &als_visible, 1) != 1) {
            perror("Failed to write to the i2c bus");
            return 1;
        }

        if (read(fd, &als_visible, 1) != 1) {
            perror("Failed to read from the i2c bus");
            return 1;
        }

        printf("%s,%d,%d\n", timestamp, uv_index, als_visible);
        fprintf(log_file, "%s,%d,%d\n", timestamp, uv_index, als_visible);
        fflush(log_file);

        sleep(1);
    }

    return 0;
}

