#define SCL_GPIO 3
#define SENSOR_ADDR 0x55 // Assuming sensor address is 0x55
#define SENSOR_MODE 0x01 // Assuming sensor mode is 0x01
#define SENSOR_REG_X 0x02 // Assuming X register is 0x02
#define SENSOR_REG_Y 0x03 // Assuming Y register is 0x03
#define SENSOR_REG_Z 0x04 // Assuming Z register is 0x04
#define SAMPLE_RATE 20 // Sample rate in Hz
#define CSV_FILE "fan_health.csv"

int i2c_fd;
FILE *csv_file;

void cleanup(int signum) {
    fclose(csv_file);
    close(i2c_fd);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set GPIOs
    // ...

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    // Switch to sensor mode
    if (write(i2c_fd, &SENSOR_MODE, 1) != 1) {
        perror("Failed to switch to sensor mode");
        return 1;
    }

    // Wait for sensor to become active
    sleep(1);

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        return 1;
    }

    // Write header row
    fprintf(csv_file, "Timestamp,X,Y,Z\n");

    // Main loop
    for (;;) {
        unsigned char buf[6];
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%FT%T%z", tm_info);

        // Read acceleration values
        if (write(i2c_fd, &SENSOR_REG_X, 1) != 1) {
            perror("Failed to read X register");
            continue;
        }
        if (read(i2c_fd, buf, 6) != 6) {
            perror("Failed to read acceleration values");
            continue;
        }

        // Append sample to CSV file
        fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, buf[0] << 8 | buf[1], buf[2] << 8 | buf[3], buf[4] << 8 | buf[5]);
        fflush(csv_file);

        // Sleep for 500ms
        usleep(500 * 1000);
    }

    return 0;
}

