#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <stdio.h>

#define SENSOR1 17
#define SENSOR2 18
#define STALL_TIME 2 // in seconds

volatile sig_atomic_t stop;

void alarmHandler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    FILE *file = fopen("stall_log.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(SENSOR1, PI_INPUT);
    gpioSetMode(SENSOR2, PI_INPUT);

    signal(SIGINT, alarmHandler);
    signal(SIGTERM, alarmHandler);

    time_t startTime, currentTime;
    int sensor1State, sensor2State;

    while (!stop) {
        sensor1State = gpioRead(SENSOR1);
        sensor2State = gpioRead(SENSOR2);

        if (sensor1State == PI_LOW && sensor2State == PI_LOW) {
            time(&startTime);
            while (sensor1State == PI_LOW && sensor2State == PI_LOW && !stop) {
                sensor1State = gpioRead(SENSOR1);
                sensor2State = gpioRead(SENSOR2);
                time(&currentTime);
                if (difftime(currentTime, startTime) >= STALL_TIME) {
                    fprintf(file, "Stall detected at %s", ctime(&startTime));
                    fflush(file);
                    break;
                }
            }
        }
    }

    fclose(file);
    gpioTerminate();
    return 0;
}

