            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%FT%T%z", gmtime(&now));

        ret = fprintf(log, "%s,%f,%f,%f\n", timestamp, x, y, z);
        if (ret < 0) {
            perror("Failed to write to log file");
            continue;
        }

        fflush(log);
        nanosleep(&ts, NULL);
