#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_LINE 4
#define PULSES_PER_REVOLUTION 4
#define SAMPLE_RATE 1
#define RPM_LOG_FILE "rpm_log.txt"

struct gpiod_line *line;
struct gpiod_chip *chip;
FILE *log_file;
volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
}

int main(void) {
    unsigned long long int pulse_count = 0;
    unsigned long long int last_pulse_count = 0;
    time_t now;
    struct tm *timeinfo;
    char buffer[80];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line, "hall-effect-sensor") < 0) {
        perror("Failed to request GPIO line as input");
        exit(EXIT_FAILURE);
    }

    log_file = fopen(RPM_LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    while (!stop) {
        if (gpiod_line_event_wait(line, NULL) < 0) {
            perror("Failed to wait for GPIO event");
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_event_read(line) == GPIOD_LINE_EVENT_RISING_EDGE) {
            __sync_add_and_fetch(&pulse_count, 1);
        }

        time(&now);
        timeinfo = localtime(&now);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (pulse_count != last_pulse_count) {
            unsigned long long int rpm = (pulse_count - last_pulse_count) * 60 / SAMPLE_RATE;
            fprintf(log_file, "%s %llu\n", buffer, rpm);
            fflush(log_file);
            printf("%s %llu\n", buffer, rpm);
            last_pulse_count = pulse_count;
        }
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

