#include <gpiod.h>

#define GPIO_A 17
#define GPIO_B 27

struct gpiod_chip *chip;
struct gpiod_line *line_a, *line_b;
FILE *file;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void signal_handler(int signum) {
    pthread_mutex_lock(&mutex);
    fflush(file);
    fclose(file);
    gpiod_chip_close(chip);
    exit(0);
}

void *interrupt_thread(void *arg) {
    struct gpiod_line_event evt;
    while (1) {
        if (gpiod_line_event_read(line_a, &evt) == 0) {
            pthread_mutex_lock(&mutex);
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            fprintf(file, "%d-%02d-%02d %02d:%02d:%02d.%03ld ",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                    tm.tm_hour, tm.tm_min, tm.tm_sec, t % 1000);
            if (evt.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                fprintf(file, "Clockwise\n");
            } else {
                fprintf(file, "Counterclockwise\n");
            }
            fflush(file);
            pthread_mutex_unlock(&mutex);
        }
    }
    return NULL;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line_a = gpiod_chip_get_line(chip, GPIO_A);
    line_b = gpiod_chip_get_line(chip, GPIO_B);
    if (line_a == NULL || line_b == NULL) {
        perror("Failed to get GPIO lines");
        return 1;
    }

    if (gpiod_line_request_both_edges_events(line_a, "rotation_logger") < 0 ||
        gpiod_line_request_both_edges_events(line_b, "rotation_logger") < 0) {
        perror("Failed to request GPIO lines");
        return 1;
    }

    file = fopen("rotation_log.txt", "w");
    if (file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    pthread_t thread;
    pthread_create(&thread, NULL, interrupt_thread, NULL);

    while (1) {
        sleep(1);
    }

    return 0;
