#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define SENSOR_GPIO 23
#define LED_GPIO 18
#define POLL_INTERVAL_MS 50

struct gpiod_chip *chip;
struct gpiod_line *sensor_line, *led_line;

void cleanup(void) {
    gpiod_line_release(sensor_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    closelog();
}

void signal_handler(int signum) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signum);
    cleanup();
    exit(0);
}

int main(void) {
    int ret;

    openlog("ttp223_led_control", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Starting TTP223B LED control program");

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return 1;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    led_line = gpiod_chip_get_line(chip, LED_GPIO);

    if (!sensor_line || !led_line) {
        syslog(LOG_ERR, "Failed to request GPIO lines");
        goto err;
    }

    ret = gpiod_line_request_input(sensor_line, "ttp223_led_control");
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request input on sensor GPIO");
        goto err;
    }

    ret = gpiod_line_request_output(led_line, "ttp223_led_control", 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request output on LED GPIO");
        goto err;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        int value = gpiod_line_get_value(sensor_line);
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read sensor GPIO");
            goto err;
        }

        if (value == 1) {
            syslog(LOG_INFO, "Sensor touched");
            gpiod_line_set_value(led_line, 1);
        } else {
            syslog(LOG_INFO, "Sensor not touched");
            gpiod_line_set_value(led_line, 0);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

err:
    cleanup();
    return 0;
}

