            gpiod_line_set_value(led_line, 1);
        } else {
            syslog(LOG_INFO, "Sensor not touched");
            gpiod_line_set_value(led_line, 0);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

err:
