    if (!line) {
        perror("Get line failed");
        return 1;
    }

    int ret = gpiod_line_request_input(line, "rain_sensor");
    if (ret < 0) {
        perror("Request input failed");
        return 1;
    }

    log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Open log file failed");
        return 1;
    }

    int prev_value = -1;
    while (1) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Get value failed");
            return 1;
        }

        if (value != prev_value) {
