#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <math.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <bcm2835.h>

#define SDA_BCM 2
#define SCL_BCM 3
#define LED_BCM 17
#define SENSOR_ADDR 0x55 // Assuming sensor address is 0x55
#define THRESHOLD 500
#define RETRIES 3

FILE *log_file;

void signal_handler(int signum) {
    bcm2835_i2c_end();
    bcm2835_close();
    fclose(log_file);
    exit(0);
}

int main() {
    if (!bcm2835_init()) {
        printf("bcm2835_init failed. Are you running as root?\n");
        return 1;
    }

    bcm2835_i2c_begin();
    bcm2835_i2c_setSlaveAddress(SENSOR_ADDR);
    bcm2835_i2c_set_baudrate(100000);

    bcm2835_gpio_fsel(SDA_BCM, BCM2835_GPIO_FSEL_I2C);
    bcm2835_gpio_fsel(SCL_BCM, BCM2835_GPIO_FSEL_I2C);

    bcm2835_gpio_fsel(LED_BCM, BCM2835_GPIO_FSEL_OUTP);

    log_file = fopen("seismic_events.log", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    // Clear power-down bit in CTRL1
    uint8_t ctrl1 = 0x00;
    bcm2835_i2c_write_register_rs(&ctrl1, 0x01);

    while (1) {
        uint8_t data[2];
        for (int i = 0; i < RETRIES; i++) {
            if (bcm2835_i2c_read_register_rs(data, 0x02, 2) == BCM2835_I2C_REASON_EXPECT_ACK) {
                uint16_t peak_vibration = (data[0] << 8) | data[1];
                if (peak_vibration > THRESHOLD) {
                    time_t now = time(NULL);
                    char timestamp[20];
                    strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
                    fprintf(log_file, "%s,%d\n", timestamp, peak_vibration);
                    bcm2835_gpio_write(LED_BCM, HIGH);
                    bcm2835_delay(1000);
                    bcm2835_gpio_write(LED_BCM, LOW);
                }
                break;
            }
        }
        bcm2835_delay(100);
    }

    return 0;
}

