#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LED 18
#define GPIO_SENSORS {4, 17, 27, 22}
#define POLL_INTERVAL_MS 50

struct gpiod_chip *chip;
struct gpiod_line *lines[4];
struct gpiod_line *led;

void cleanup(int signum) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_SENSORS[i]);
        if (!lines[i]) {
            perror("Failed to get line");
            return 1;
        }
        if (gpiod_line_request_input(lines[i], "obstacle-detection") < 0) {
            perror("Failed to request line as input");
            return 1;
        }
    }

    led = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led) {
        perror("Failed to get LED line");
        return 1;
    }
    if (gpiod_line_request_output(led, "led", 0) < 0) {
        perror("Failed to request LED as output");
        return 1;
    }

    while (1) {
        for (int i = 0; i < 4; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                perror("Failed to get line value");
                return 1;
            }
            if (value == 0) {
                gpiod_line_set_value(led, 1);
                break;
            }
        }
        usleep(POLL_INTERVAL_MS * 1000);
        gpiod_line_set_value(led, 0);
    }

    return 0;
}

