#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define DEBOUNCE_TIME 50 // in ms

volatile sig_atomic_t stop;

struct sensor_data {
    int gpio_pin;
    struct gpiod_line* line;
};

struct sensor_data sensors[NUM_SENSORS];

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    openlog("flame_monitor", LOG_USER, LOG_USER);
    syslog(LOG_INFO, "Starting flame monitor");

    struct gpiod_chip* chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        closelog();
        return 1;
    }

    sensors[0] = (struct sensor_data){2, gpiod_chip_get_line(chip, 2)};
    sensors[1] = (struct sensor_data){3, gpiod_chip_get_line(chip, 3)};
    sensors[2] = (struct sensor_data){4, gpiod_chip_get_line(chip, 4)};
    sensors[3] = (struct sensor_data){17, gpiod_chip_get_line(chip, 17)};
    sensors[4] = (struct sensor_data){27, gpiod_chip_get_line(chip, 27)};

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (!sensors[i].line) {
            syslog(LOG_ERR, "Failed to get line %d", sensors[i].gpio_pin);
            gpiod_chip_close(chip);
            closelog();
            return 1;
        }

        if (gpiod_line_request_input(sensors[i].line, "flame_monitor") < 0) {
            syslog(LOG_ERR, "Failed to request line %d", sensors[i].gpio_pin);
            gpiod_chip_close(chip);
            closelog();
            return 1;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int value = gpiod_line_get_value(sensors[i].line);
            if (value == 0) {
                struct timespec debounce_start, debounce_end;
                clock_gettime(CLOCK_MONOTONIC, &debounce_start);
                while (1) {
                    clock_gettime(CLOCK_MONOTONIC, &debounce_end);
                    if ((debounce_end.tv_sec - debounce_start.tv_sec) * 1000 + (debounce_end.tv_nsec - debounce_start.tv_nsec) / 1000000 >= DEBOUNCE_TIME)
                        break;
                    value = gpiod_line_get_value(sensors[i].line);
                    if (value == 1)
                        break;
                }
                if (value == 0) {
                    time_t now = time(NULL);
                    struct tm* tm_info = gmtime(&now);
                    char timestamp[20];
                    strftime(timestamp, sizeof(timestamp), "%FT%TZ", tm_info);
                    FILE* log_file = fopen("/var/log/flame_events.log", "a");
                    if (log_file) {
                        fprintf(log_file, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, i, sensors[i].gpio_pin);
                        fflush(log_file);
                        fclose(log_file);
                    } else {
                        syslog(LOG_ERR, "Failed to open log file");
                    }
                }
            }
        }
        usleep(1000000); // 1 second
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_release(sensors[i].line);
    }

    gpiod_chip_close(chip);

    syslog(LOG_INFO, "Flame monitor stopped");
    closelog();

    return 0;
}

