void handle_signal(int signum) {
    // Turn off the LED and clean up
    digitalWrite(GPIO_PWM_PIN, LOW);
    close(fd);
    fclose(log_file);
    exit(0);
}

int main() {
    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize wiringPi library
    if (wiringPiSetup() == -1) {
        printf("Failed to initialize wiringPi library\n");
        return 1;
    }

    // Initialize I2C bus
    fd = wiringPiI2CSetup(VEML7700_ADDR);
    if (fd == -1) {
        printf("Failed to initialize I2C bus\n");
        return 1;
    }

    // Configure the sensor
    // This will depend on the specific sensor you are using
    // For the VEML7700, you might need to write to registers

    // Open log file
    log_file = fopen("grow_log.txt", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    // Set up PWM
    pinMode(GPIO_PWM_PIN, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS); // Set to mark:space mode
    pwmSetClock(400); // Set clock to 400Hz
    pwmSetRange(100); // Set range to 100

    while (1) {
        // Read ambient light sensor
        int lux = wiringPiI2CReadReg8(fd, 0x00); // This will depend on the specific sensor
