            printf("Failed to read from sensor\n");
            return 1;
        }

        // Map lux to brightness level
        int brightness;
        if (lux < 100) {
            brightness = 100;
        } else if (lux < 500) {
            brightness = 75;
        } else if (lux < 1000) {
            brightness = 50;
        } else {
            brightness = 25;
        }

        // Write to log file
        time_t now = time(NULL);
        struct tm *ptm = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", ptm);
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, lux, brightness, pwmGetLastError());
        fflush(log_file);

        // Set PWM duty cycle
        pwmWrite(GPIO_PWM_PIN, brightness);

        // Sleep for 1 second
        delay(1000);
    }

    return 0;
}

