#define DEBOUNCE_TIME 50000 // 50ms

struct gpiod_chip *chip;
struct gpiod_line *lines[CHANNELS];
struct gpiod_line *led;
int last_state[CHANNELS] = {0};
int current_state[CHANNELS] = {0};

void signal_handler(int signum) {
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    FILE *file;
    char buffer[50];
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char filename[50] = "touch_log.txt";

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    for (int i = 0; i < CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PULL_DOWN + i);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", GPIO_PULL_DOWN + i);
            return 1;
        }
        if (gpiod_line_request_input(lines[i], "touch_sensor") < 0) {
            fprintf(stderr, "Failed to request input on line %d\n", GPIO_PULL_DOWN + i);
            return 1;
        }
    }

    led = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led) {
        fprintf(stderr, "Failed to get LED line\n");
        return 1;
    }
    if (gpiod_line_request_output(led, "led", 0) < 0) {
        fprintf(stderr, "Failed to request output on LED line\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        for (int i = 0; i < CHANNELS; i++) {
            current_state[i] = gpiod_line_get_value(lines[i]);
            if (current_state[i] && !last_state[i]) {
                gpiod_line_set_value(led, 1);
                sprintf(buffer, "%04d-%02d-%02d %02d:%02d:%02d - Channel %d Touched\n",
                        tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                        tm.tm_hour, tm.tm_min, tm.tm_sec, i + 1);
                file = fopen(filename, "a");
                if (file) {
                    fputs(buffer, file);
                    fclose(file);
                } else {
                    fprintf(stderr, "Failed to open file for writing\n");
                }
                usleep(DEBOUNCE_TIME);
            }
            last_state[i] = current_state[i];
        }
        usleep(50000); // 50ms
    }

    return 0;
}

