#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libopt3001.h>

#define I2C_DEVICE "/dev/i2c-1"
#define OPT3001_ADDRESS 0x44

int fd;
opt3001_t *sensor;

void handle_sigint(int signum) {
    printf("Exiting...\n");
    opt3001_close(sensor);
    close(fd);
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open the i2c bus\n");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, OPT3001_ADDRESS) < 0) {
        fprintf(stderr, "Failed to acquire bus access or talk to slave\n");
        return 1;
    }

    sensor = opt3001_init(fd);
    if (sensor == NULL) {
        fprintf(stderr, "Failed to initialize OPT3001 sensor\n");
        return 1;
    }

    FILE *file = fopen("light_data.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open the log file\n");
        return 1;
    }

    while (1) {
        usleep(100000);  // Wait for 100ms

        uint16_t raw_data;
        if (opt3001_read_raw(&raw_data, sensor) < 0) {
            fprintf(stderr, "Failed to read from OPT3001 sensor\n");
            continue;
        }

        uint16_t data = __bswap_16(raw_data);  // Byte swap

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%F %T", tm);

        float lux = opt3001_convert_to_lux(data, sensor);

        printf("%s, %.2f\n", timestamp, lux);
        fprintf(file, "%s, %.2f\n", timestamp, lux);
        fflush(file);
    }

    fclose(file);
    opt3001_close(sensor);
    close(fd);

    return 0;
}

