    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    alert_line = gpiod_chip_get_line(chip, ALERT_GPIO);
    if (!sensor_line || !alert_line) {
        perror("Failed to get GPIO lines");
