        perror("Failed to request sensor GPIO");
        return 1;
    }

    if (gpiod_line_request_output(alert_line, "fire_alert", 0) < 0) {
        perror("Failed to request alert GPIO");
        return 1;
    }

    while (1) {
        value = gpiod_line_get_value(sensor_line);
        if (value < 0) {
            perror("Failed to read sensor GPIO");
            return 1;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        fprintf(log_file, "%s: Sensor value = %d\n", buffer, value);
        fflush(log_file);

        if (value == 0) {
            gpiod_line_set_value(alert_line, 1);
            nanosleep(&ts, NULL);
            gpiod_line_set_value(alert_line, 0);
        }

        nanosleep(&ts, NULL);
    }

    return 0;
}

