#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>

#define SDA_PIN 2
#define SCL_PIN 3
#define SENSOR_ADDR 0x28 // Sensirion SLF3S-1300F I2C address
#define FILE_NAME "cooling_log.csv"

int fd;

void sigint_handler(int sig) {
    printf("Exiting...\n");
    close(fd);
    exit(0);
}

void log_data(char* timestamp, float flow_rate, char* status) {
    FILE *file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }
    fprintf(file, "%s,%f,%s\n", timestamp, flow_rate, status);
    fclose(file);
}

int main() {
    signal(SIGINT, sigint_handler);

    if (wiringPiSetup() == -1) {
        printf("Error setting up wiringPi\n");
        return 1;
    }

    fd = wiringPiI2CSetup(SENSOR_ADDR);
    if (fd == -1) {
        printf("Error setting up I2C\n");
        return 1;
    }

    while (1) {
        delay(1000); // Wait for 1 second

        int raw_data = wiringPiI2CReadReg16(fd, 0x00); // Read raw data
        if (raw_data == -1) {
            printf("Error reading from I2C\n");
            continue;
        }

        float flow_rate = raw_data / 100.0; // Convert to ml/min
        char status[10];

        if (flow_rate < 0 || flow_rate > 100) {
            sprintf(status, "INVALID");
        } else {
            sprintf(status, "VALID");
        }

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        log_data(timestamp, flow_rate, status);
    }

    return 0;
}

