#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x53
#define PART_ID_EXPECTED 0x82
#define HW_REV_EXPECTED 0x1D

int fd;

void handle_sigint(int sig) {
    printf("Exiting...\n");
    close(fd);
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    char part_id, hw_rev;
    if (read(fd, &part_id, 1) != 1 || read(fd, &hw_rev, 1) != 1) {
        perror("Failed to read from the i2c bus");
        return 1;
    }

    if (part_id != PART_ID_EXPECTED || hw_rev != HW_REV_EXPECTED) {
        fprintf(stderr, "Invalid PART_ID or HW_REV\n");
