#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_DEVICE "/dev/gpiochip0"
#define GPIO_OUT_START 17
#define GPIO_OUT_END 24
#define GPIO_IN_START 5
#define GPIO_IN_END 12
#define DELAY_MS 10

struct gpiod_chip *chip;
struct gpiod_line **lines_in;
struct gpiod_line **lines_out;
int num_in;
int num_out;

void cleanup(int signum) {
    for (int i = 0; i < num_out; i++) {
        gpiod_line_set_value(lines_out[i], 0);
        gpiod_line_release(lines_out[i]);
    }
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open(GPIO_DEVICE);
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    num_in = GPIO_IN_END - GPIO_IN_START + 1;
    num_out = GPIO_OUT_END - GPIO_OUT_START + 1;

    lines_in = malloc(num_in * sizeof(struct gpiod_line *));
    lines_out = malloc(num_out * sizeof(struct gpiod_line *));

    for (int i = 0; i < num_in; i++) {
        lines_in[i] = gpiod_chip_get_line(chip, GPIO_IN_START + i);
        if (lines_in[i] == NULL) {
            perror("Failed to get GPIO line");
            return 1;
        }
        if (gpiod_line_request_input(lines_in[i], "touch_counter") < 0) {
            perror("Failed to request GPIO line input");
            return 1;
        }
    }

    for (int i = 0; i < num_out; i++) {
        lines_out[i] = gpiod_chip_get_line(chip, GPIO_OUT_START + i);
        if (lines_out[i] == NULL) {
            perror("Failed to get GPIO line");
            return 1;
        }
        if (gpiod_line_request_output(lines_out[i], "touch_counter", 0) < 0) {
            perror("Failed to request GPIO line output");
            return 1;
        }
    }

    FILE *log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    int counter = 0;
    while (1) {
        for (int i = 0; i < num_in; i++) {
            int value = gpiod_line_get_value(lines_in[i]);
            if (value < 0) {
                perror("Failed to read GPIO line");
                return 1;
            }
            if (value == 1) {
                counter = (counter + 1) % 256;
                for (int j = 0; j < num_out; j++) {
                    int bit = (counter >> j) & 1;
                    if (gpiod_line_set_value(lines_out[j], bit) < 0) {
                        perror("Failed to write GPIO line");
                        return 1;
                    }
                }
                time_t now = time(NULL);
                struct tm *tm_info = gmtime(&now);
                char timestamp[20];
                strftime(timestamp, 20, "%Y-%m-%dT%H:%M:%SZ", tm_info);
                fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, i + 1, counter);
                fflush(log_file);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
        }
        usleep(DELAY_MS * 1000);
    }

    return 0;
}

