#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define GPIO_PIN_1 17
#define GPIO_PIN_2 18
#define DEBOUNCE_TIME 50 // in ms

FILE *logFile;

void sigintHandler(int sig) {
    fclose(logFile);
    gpioTerminate();
    exit(0);
}

void monitorPin(int pin) {
    int lastState = gpioRead(pin);
    unsigned int lastDebounceTime = gpioTick() - DEBOUNCE_TIME;

    while(1) {
        unsigned int currentTick = gpioTick();
        int currentState = gpioRead(pin);

        if (currentState != lastState && (currentTick - lastDebounceTime) > DEBOUNCE_TIME) {
            lastDebounceTime = currentTick;
            lastState = currentState;

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char time_str[20];
            strftime(time_str, 20, "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(logFile, "%s, Sensor %d tilted\n", time_str, pin == GPIO_PIN_1 ? 1 : 2);
            fflush(logFile);
        }

        gpioDelay(100000); // 100ms delay
    }
}

int main() {
    if (signal(SIGINT, sigintHandler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        return 1;
    }

    if (signal(SIGTERM, sigintHandler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGTERM handler\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    logFile = fopen("/var/log/tilt_events.log", "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN_1, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin mode\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN_2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin mode\n");
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN_1, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO pin pull up/down\n");
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN_2, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO pin pull up/down\n");
        return 1;
    }

    monitorPin(GPIO_PIN_1);
    monitorPin(GPIO_PIN_2);

    return 0;
}

