volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line_input, *line_output;
    int value_input, value_output;
    struct timespec ts;
    char *endp;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip\n");
        return 1;
    }

    line_input = gpiod_chip_get_line(chip, GPIO_PIN_INPUT);
    line_output = gpiod_chip_get_line(chip, GPIO_PIN_OUTPUT);

    if (!line_input || !line_output) {
        fprintf(stderr, "Failed to get line\n");
        return 1;
    }

    if (gpiod_line_request_input(line_input, "mic-monitor") < 0) {
        fprintf(stderr, "Failed to request input\n");
        return 1;
    }

    if (gpiod_line_request_output(line_output, "mic-monitor", 0) < 0) {
        fprintf(stderr, "Failed to request output\n");
        return 1;
    }

    value_output = 0;
    gpiod_line_set_value(line_output, value_output);

    while (!stop) {
        value_input = gpiod_line_get_value(line_input);
        if (value_input < 0) {
            fprintf(stderr, "Failed to get value\n");
            return 1;
        }

        if (value_input) {
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("%ld%ld\n", ts.tv_sec, ts.tv_nsec / 1000000);

            value_output = 1;
            gpiod_line_set_value(line_output, value_output);
            nanosleep((const struct timespec[]){{0, 100 * 1000000}}, NULL);
            value_output = 0;
            gpiod_line_set_value(line_output, value_output);
        }

        usleep(SAMPLING_RATE_US);
    }

    gpiod_line_release(line_input);
    gpiod_line_release(line_output);
    gpiod_chip_close(chip);

    return 0;
}

