#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDR 0x53

int fd;

void cleanup(int signum) {
    printf("Closing I2C device...\n");
    close(fd);
    exit(0);
}

int main() {
    unsigned char buffer[2];
    int result;

    signal(SIGINT, cleanup);

    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        exit(1);
    }

    while (1) {
        buffer[0] = 0x00;
        result = write(fd, buffer, 1);
        if (result != 1) {
            perror("Failed to write to the i2c bus");
            exit(1);
        }

        sleep(0.1);

        buffer[0] = 0x03;
        result = write(fd, buffer, 1);
        if (result != 1) {
            perror("Failed to write to the i2c bus");
            exit(1);
        }

        result = read(fd, buffer, 2);
        if (result != 2) {
            perror("Failed to read from the i2c bus");
            exit(1);
        }

        int raw_value = (buffer[0] << 8) | buffer[1];
        printf("Raw sensor reading: 0x%04X\n", raw_value);

        sleep(0.1);
    }

    return 0;
}

