#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <bcm2835.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x29 // TCS34725 I2C address
#define PON_REG 0x80
#define AEN_REG 0x80
#define ATIME_REG 0x81
#define RED_REG 0x14
#define GREEN_REG 0x16
#define BLUE_REG 0x18
#define CLEAR_REG 0x1C
#define GPIO_PIN RPI_GPIO_P1_11
#define THRESHOLD 200

int fd;

void cleanup(int signum) {
    bcm2835_gpio_write(GPIO_PIN, LOW);
    bcm2835_i2c_close(fd);
    bcm2835_close();
    exit(0);
}

int main() {
    if (!bcm2835_init()) {
        printf("bcm2835_init failed\n");
        return 1;
    }

    if (!bcm2835_i2c_begin()) {
        printf("bcm2835_i2c_begin failed\n");
        return 1;
    }

    bcm2835_i2c_setSlaveAddress(I2C_ADDR);
    bcm2835_i2c_set_baudrate(100000);

    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        printf("Failed to open I2C device\n");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        printf("Failed to acquire bus access or talk to slave\n");
        return 1;
    }

    bcm2835_gpio_fsel(GPIO_PIN, BCM2835_GPIO_FSEL_OUTP);

    uint8_t buf[2];
    buf[0] = PON_REG;
    buf[1] = 0x12; // Power on, RGBC enable
    if (write(fd, buf, 2) != 2) {
        printf("Failed to write to I2C device\n");
        return 1;
    }

    buf[0] = ATIME_REG;
    buf[1] = 0xFF; // Set integration time to 154ms
    if (write(fd, buf, 2) != 2) {
        printf("Failed to write to I2C device\n");
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        buf[0] = RED_REG;
        if (write(fd, buf, 1) != 1) {
            printf("Failed to write to I2C device\n");
            return 1;
        }

        if (read(fd, buf, 2) != 2) {
            printf("Failed to read from I2C device\n");
            return 1;
        }

        uint16_t red = buf[0] | (buf[1] << 8);

        if (red > THRESHOLD) {
            bcm2835_gpio_write(GPIO_PIN, HIGH);
        } else {
            bcm2835_gpio_write(GPIO_PIN, LOW);
        }

        sleep(0.2);
    }

    return 0;
}

