#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define FLAME_SENSOR 4
#define BUZZER 17
#define LED 18

#define TEST_READS 5
#define TEST_INTERVAL 100000 // microseconds
#define TEST_BLINK_INTERVAL 500000 // microseconds

#define ERROR_BLINK_INTERVAL 100000 // microseconds
#define ERROR_BLINK_CYCLES 5

#define BUZZER_PATTERN {200000, 200000, 600000, 200000}
#define BUZZER_PATTERN_LEN 4

#define POLL_INTERVAL 50000 // microseconds

struct gpiod_chip *chip;
struct gpiod_line *flame_sensor, *buzzer, *led;

void signal_handler(int signum) {
    gpiod_line_release(flame_sensor);
    gpiod_line_release(buzzer);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    exit(0);
}

void blink(struct gpiod_line *line, int on_time, int off_time, int cycles) {
    for (int i = 0; i < cycles; i++) {
        gpiod_line_set_value(line, 1);
        usleep(on_time);
        gpiod_line_set_value(line, 0);
        usleep(off_time);
    }
}

void buzz(struct gpiod_line *line, int *pattern, int len) {
    for (int i = 0; i < len; i++) {
        gpiod_line_set_value(line, 1);
        usleep(pattern[i]);
        gpiod_line_set_value(line, 0);
        usleep(pattern[i]);
    }
}

int main() {
    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    flame_sensor = gpiod_chip_get_line(chip, FLAME_SENSOR);
    buzzer = gpiod_chip_get_line(chip, BUZZER);
    led = gpiod_chip_get_line(chip, LED);

    if (!flame_sensor || !buzzer || !led) {
        perror("Failed to get GPIO line");
        return 1;
    }

    // Startup self-test
    printf("Starting self-test...\n");
    for (int i = 0; i < TEST_READS; i++) {
        int value = gpiod_line_get_value(flame_sensor);
        if (value == 0) {
            printf("Flame detected on all samples\n");
            blink(led, ERROR_BLINK_INTERVAL, ERROR_BLINK_INTERVAL, ERROR_BLINK_CYCLES);
            buzz(buzzer, BUZZER_PATTERN, BUZZER_PATTERN_LEN);
            return 1;
        }
        usleep(TEST_INTERVAL);
    }

    printf("Self-test passed\n");
    blink(led, TEST_BLINK_INTERVAL, TEST_BLINK_INTERVAL, 2);

    // Main loop
    while (1) {
        int value = gpiod_line_get_value(flame_sensor);
        if (value == 0) {
            printf("Flame detected at %ld\n", time(NULL));
            gpiod_line_set_value(buzzer, 1);
            gpiod_line_set_value(led, 1);
        } else {
            printf("Flame cleared at %ld\n", time(NULL));
            gpiod_line_set_value(buzzer, 0);
            gpiod_line_set_value(led, 0);
        }
        usleep(POLL_INTERVAL);
    }

    return 0;
}

