#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

#define I2C_ADDR 0x23 // BH1750 I2C address
#define BUFFER_SIZE 60
#define GPIO_PIN 17 // GPIO pin number
#define MAX_LUX 1000 // Maximum lux value
#define MIN_FREQ 0.5 // Minimum frequency in Hz
#define MAX_FREQ 5.0 // Maximum frequency in Hz

int i2c_fd;
int buffer[BUFFER_SIZE];
int buffer_index = 0;

void handle_signal(int signum) {
    printf("\nCleaning up...\n");
    digitalWrite(GPIO_PIN, LOW);
    close(i2c_fd);
    exit(0);
}

float map(float x, float in_min, float in_max, float out_min, float out_max) {
    return (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
}

int main() {
    signal(SIGINT, handle_signal);

    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(GPIO_PIN, OUTPUT);

    i2c_fd = wiringPiI2CSetup(I2C_ADDR);
    if (i2c_fd == -1) {
        printf("Failed to setup I2C\n");
        return 1;
    }

    wiringPiI2CWrite(i2c_fd, 0x23); // Power on and set to continuous mode

    while (1) {
        int lux = wiringPiI2CRead(i2c_fd);
        if (lux == -1) {
            printf("Failed to read from I2C\n");
            continue;
        }

        buffer[buffer_index++ % BUFFER_SIZE] = lux;

        float avg = 0.0;
        for (int i = 0; i < BUFFER_SIZE && i < buffer_index; i++) {
            avg += buffer[i];
        }
        avg /= (buffer_index < BUFFER_SIZE ? buffer_index : BUFFER_SIZE);

        float freq = map(avg, 0, MAX_LUX, MIN_FREQ, MAX_FREQ);
        int period = (int)(1.0 / freq * 1000);

        digitalWrite(GPIO_PIN, HIGH);
        delay(period / 2);
        digitalWrite(GPIO_PIN, LOW);
        delay(period / 2);

        delay(1000); // Wait for 1 second
    }

    return 0;
}

