#include <unistd.h>
#include <gpiod.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define DELAY_ON 500000
#define DELAY_OFF 500000

#define SEGMENT_PATTERN 0b01010100 // Pattern for digit '5'

void shift_out(struct gpiod_chip *chip, struct gpiod_line *data_line, struct gpiod_line *clock_line, unsigned char val)
{
    for (int i = 0; i < 8; i++)
    {
        if ((val & (1 << (7 - i))) != 0)
        {
            gpiod_line_set_value(data_line, 1);
        }
        else
        {
            gpiod_line_set_value(data_line, 0);
        }

        gpiod_line_set_value(clock_line, 1);
        gpiod_line_set_value(clock_line, 0);
    }
}

int main(void)
{
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL)
    {
        perror("Open chip failed");
        return EXIT_FAILURE;
    }

    struct gpiod_line *data_line = gpiod_chip_get_line(chip, DATA_PIN);
    struct gpiod_line *clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    struct gpiod_line *latch_line = gpiod_chip_get_line(chip, LATCH_PIN);

    if (data_line == NULL || clock_line == NULL || latch_line == NULL)
    {
        perror("Get line failed");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(data_line, "data", 0) < 0 ||
        gpiod_line_request_output(clock_line, "clock", 0) < 0 ||
        gpiod_line_request_output(latch_line, "latch", 0) < 0)
    {
        perror("Request line as output failed");
        return EXIT_FAILURE;
    }

    while (1)
    {
        shift_out(chip, data_line, clock_line, SEGMENT_PATTERN);
        gpiod_line_set_value(latch_line, 1);
        gpiod_line_set_value(latch_line, 0);

        usleep(DELAY_ON);

        gpiod_line_set_value(data_line, 0);
        gpiod_line_set_value(clock_line, 0);
        gpiod_line_set_value(latch_line, 0);

        usleep(DELAY_OFF);
    }

    gpiod_line_release(data_line);
    gpiod_line_release(clock_line);
    gpiod_line_release(latch_line);

    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

