#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LED 17
#define GPIO_BUTTON 18

struct gpiod_chip *chip;
struct gpiod_line *led, *button;

void cleanup(int signum) {
    gpiod_line_release(led);
    gpiod_line_release(button);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("Failed to open chip");
        return 1;
    }

    led = gpiod_chip_get_line(chip, GPIO_LED);
    if (led == NULL) {
        perror("Failed to get LED line");
        return 1;
    }

    button = gpiod_chip_get_line(chip, GPIO_BUTTON);
    if (button == NULL) {
        perror("Failed to get button line");
        return 1;
    }

    int ret = gpiod_line_request_output(led, "LED", 0);
    if (ret < 0) {
        perror("Failed to request LED line as output");
        return 1;
    }

    ret = gpiod_line_request_input_flags(button, "Button", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP | GPIOD_LINE_REQUEST_FLAG_EDGE_FALLING);
    if (ret < 0) {
        perror("Failed to request button line as input");
        return 1;
    }

    while (1) {
        gpiod_line_set_value(led, 1);
        usleep(1000000);
        gpiod_line_set_value(led, 0);
        usleep(1000000);

        struct gpiod_line_event evt;
        ret = gpiod_line_event_wait(button, 1000000000);
        if (ret < 0) {
            perror("Failed to wait for button event");
            return 1;
        }

        ret = gpiod_line_event_read(button, &evt);
        if (ret < 0) {
            perror("Failed to read button event");
            return 1;
        }

        if (evt.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            printf("Button pressed\n");
            break;
        }
    }

    cleanup(0);
    return 0;
}

