#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18
#define PWM_FREQ 100 // 100 Hz
#define PWM_PERIOD 10000000 // 10 ms in nanoseconds

struct gpiod_chip *chip;
struct gpiod_line *red_line, *green_line, *blue_line;

void cleanup(int sig) {
    gpiod_line_release(red_line);
    gpiod_line_release(green_line);
    gpiod_line_release(blue_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    int request_flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    if (gpiod_line_request_config(red_line, "RGB LED", request_flags) ||
        gpiod_line_request_config(green_line, "RGB LED", request_flags) ||
        gpiod_line_request_config(blue_line, "RGB LED", request_flags)) {
        perror("Failed to configure GPIO line");
        return 1;
    }

    struct timespec ts = {0, PWM_PERIOD / PWM_FREQ};
    while (1) {
        int red_intensity = rand() % 101;
        int green_intensity = rand() % 101;
        int blue_intensity = rand() % 101;

        for (int i = 0; i < PWM_FREQ; i++) {
            gpiod_line_set_value(red_line, red_intensity > i);
            gpiod_line_set_value(green_line, green_intensity > i);
            gpiod_line_set_value(blue_line, blue_intensity > i);

            clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);
        }

        ts.tv_nsec += 10000000; // Add 10 ms to the period
        if (ts.tv_nsec >= 1000000000) { // If the period is more than 1 second, reset it
            ts.tv_nsec -= 1000000000;
            ts.tv_sec++;
        }
    }

    return 0;
}

