#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <math.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <Adafruit_LSM303DLHC.h>

#define I2C_ADDR 0x1D // I2C address of the accelerometer
#define GPIO_PIN 17 // GPIO pin number
#define SAMPLE_RATE 100 // Sample rate in Hz
#define DEFAULT_THRESHOLD 2.0 // Default threshold in G

int fd, gpio_pin, sample_rate, threshold;
FILE *log_file;

void cleanup(int signum) {
    fclose(log_file);
    digitalWrite(gpio_pin, LOW);
    close(fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc > 1) {
        threshold = atof(argv[1]);
    } else {
        threshold = DEFAULT_THRESHOLD;
    }

    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    fd = wiringPiI2CSetup(I2C_ADDR);
    if (fd == -1) {
        printf("Failed to setup I2C\n");
        return 1;
    }

    pinMode(GPIO_PIN, OUTPUT);
    digitalWrite(GPIO_PIN, LOW);

    log_file = fopen("impact_log.txt", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    Adafruit_LSM303DLHC accel = Adafruit_LSM303DLHC(fd);
    if (!accel.begin()) {
        printf("Failed to initialize accelerometer\n");
        return 1;
    }

    while (1) {
        float x = accel.readFloatAccelX();
        float y = accel.readFloatAccelY();
        float z = accel.readFloatAccelZ();

        float magnitude = sqrt(x*x + y*y + z*z);

        if (magnitude > threshold) {
            digitalWrite(GPIO_PIN, HIGH);
            delay(50);
            digitalWrite(GPIO_PIN, LOW);

            time_t now = time(NULL);
            fprintf(log_file, "%ld, %f, %f, %f, %f\n", now, x, y, z, magnitude);
            fflush(log_file);
        }

        delay(1000 / SAMPLE_RATE);
    }

    return 0;
}

