Adafruit_FXOS8700CQ fxos = Adafruit_FXOS8700CQ(12345);
int fd;

void handle_sigint(int sig) {
    close(fd);
    fxos.standby();
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, FXOS_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    if (!fxos.begin(FXOS_ADDR, &wire)) {
        fprintf(stderr, "Failed to initialize FXOS8700CQ\n");
        return 1;
    }

    if (fxos.getWhoAmI() != 0xC7) {
        fprintf(stderr, "WHO_AM_I identifier does not match\n");
        return 1;
    }

    fxos.setRange(FXOS8700CQ_RANGE_2G);
    fxos.setDataRate(FXOS8700CQ_DATARATE_200HZ);
    fxos.setAxisRemap(1, 0, 2); // Remap X to Y, Y to X, Z to Z
    fxos.setStandby();

    while (1) {
        fxos.setActive();
        usleep(50000); // Wait for 50ms

        int16_t x, y, z;
        fxos.getAcceleration(&x, &y, &z);

        float magnitude = sqrt(x*x + y*y + z*z);

        if (magnitude > IMPACT_THRESHOLD) {
            time_t now = time(NULL);
            struct tm *ptm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", ptm);

            FILE *file = fopen("impact_log.txt", "a");
            if (file != NULL) {
                fprintf(file, "%s,%d,%d,%d,%.3f\n", timestamp, x, y, z, magnitude);
                fclose(file);
            }
        }

        fxos.setStandby();
    }

    return 0;
}

