#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <wiringPi.h>
#include <smbus2.h>
#include <time.h>

#define ADXL345_DEVICE_ADDRESS 0x53
#define ADXL345_DEVICE_ID 0xE5
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAZ0 0x36
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_FULL_RES 0x08
#define ADXL345_2G_RANGE 0x00
#define GPIO_PIN 17

int file_i2c;
FILE *file_log;

void signal_handler(int signum) {
    printf("Exiting...\n");
    fclose(file_log);
    close(file_i2c);
    digitalWrite(GPIO_PIN, LOW);
    exit(0);
}

int main() {
    if (wiringPiSetupGpio() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(GPIO_PIN, OUTPUT);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    file_i2c = open("/dev/i2c-1", O_RDWR);
    if (file_i2c < 0) {
        printf("Failed to open I2C bus\n");
        return 1;
    }

    if (ioctl(file_i2c, I2C_SLAVE, ADXL345_DEVICE_ADDRESS) < 0) {
        printf("Failed to acquire bus access or talk to slave\n");
        return 1;
    }

    char buf[1];
    buf[0] = ADXL345_DEVICE_ID;
    write(file_i2c, buf, 1);
    read(file_i2c, buf, 1);
    if (buf[0] != 0xE5) {
        printf("Device ID mismatch\n");
        return 1;
    }

    buf[0] = ADXL345_POWER_CTL;
    buf[1] = ADXL345_FULL_RES | ADXL345_2G_RANGE;
    write(file_i2c, buf, 2);

    file_log = fopen("accel_log.txt", "w");
    if (file_log == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    while (1) {
        buf[0] = ADXL345_DATAX0;
        write(file_i2c, buf, 1);
        read(file_i2c, buf, 2);
        int x = (buf[0] << 8) | buf[1];

        buf[0] = ADXL345_DATAY0;
        write(file_i2c, buf, 1);
        read(file_i2c, buf, 2);
        int y = (buf[0] << 8) | buf[1];

        buf[0] = ADXL345_DATAZ0;
        write(file_i2c, buf, 1);
        read(file_i2c, buf, 2);
        int z = (buf[0] << 8) | buf[1];

        time_t now = time(NULL);
        fprintf(file_log, "%ld,%.3f,%.3f,%.3f\n", now, x / 256.0, y / 256.0, z / 256.0);
        fflush(file_log);

        if (fabs(x / 256.0) > 2.0 || fabs(y / 256.0) > 2.0 || fabs(z / 256.0) > 2.0) {
            digitalWrite(GPIO_PIN, HIGH);
        } else {
            digitalWrite(GPIO_PIN, LOW);
        }

        delay(100);
    }

    return 0;
}

