#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define VL6180X_ADDR 0x29
#define VL6180X_REG_SYSRANGE 0x0010
#define VL6180X_REG_SYSALS 0x0011

int fd;

void sigint_handler(int sig) {
    printf("Exiting...\n");
    close(fd);
    exit(0);
}

int main() {
    int res;
    unsigned char buf[2];
    FILE *file;
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 100000000;  // 100ms

    signal(SIGINT, sigint_handler);

    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, VL6180X_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    buf[0] = VL6180X_REG_SYSRANGE;
    buf[1] = 0x01;  // Start range measurement
    res = write(fd, buf, 2);
    if (res != 2) {
        perror("Failed to write to the i2c bus");
        return 1;
    }

    file = fopen("distance_log.txt", "w");
    if (file == NULL) {
        perror("Failed to open file");
        return 1;
    }

    while (1) {
        buf[0] = VL6180X_REG_SYSRANGE;
        res = write(fd, buf, 1);
        if (res != 1) {
            perror("Failed to write to the i2c bus");
            return 1;
        }

        res = read(fd, buf, 2);
        if (res != 2) {
            perror("Failed to read from the i2c bus");
            return 1;
        }

        int distance = buf[0] + (buf[1] << 8);
        time_t t = time(NULL);
        fprintf(file, "%ld: %d mm\n", t, distance);
        fflush(file);

        if (distance < 100) {
            fprintf(file, "DOOR_OPEN\n");
        } else {
            fprintf(file, "DOOR_CLOSED\n");
        }
        fflush(file);

        nanosleep(&ts, NULL);
    }

    return 0;
}

