#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR1_ADDR 0x1E
#define SENSOR2_ADDR 0x1F
#define SAMPLING_INTERVAL 10000 // in microseconds

FILE *log_file;
int i2c_fd;

void handle_sigint(int sig) {
    fclose(log_file);
    close(i2c_fd);
    exit(0);
}

int main() {
    struct timespec ts1, ts2;
    int sensor1, sensor2, tdoa;

    signal(SIGINT, handle_sigint);

    if ((log_file = fopen("audio_log.dat", "w")) == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts1);

        if (read(i2c_fd, &sensor1, sizeof(sensor1)) != sizeof(sensor1)) {
            perror("Failed to read from sensor 1");
            continue;
        }

        if (read(i2c_fd, &sensor2, sizeof(sensor2)) != sizeof(sensor2)) {
            perror("Failed to read from sensor 2");
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts2);

        tdoa = (ts2.tv_sec - ts1.tv_sec) * 1000000 + (ts2.tv_nsec - ts1.tv_nsec) / 1000;

        fprintf(log_file, "%ld,%ld,%d,%d,%d\n", ts1.tv_sec, ts1.tv_nsec, sensor1, sensor2, tdoa);

        usleep(SAMPLING_INTERVAL);
    }

    return 0;
}

