#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <pthread.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU_ADDR 0x68 // MPU-6886 I2C address
#define MAX_RETRIES 3

int i2c_fd;
volatile sig_atomic_t stop;

void* read_loop(void* arg) {
    while (!stop) {
        short accel[3], gyro[3];
        for (int i = 0; i < MAX_RETRIES && !stop; i++) {
            if (read(i2c_fd, accel, sizeof(accel)) != sizeof(accel)) {
                perror("Failed to read accelerometer values");
                continue;
            }
            if (read(i2c_fd, gyro, sizeof(gyro)) != sizeof(gyro)) {
                perror("Failed to read gyroscope values");
                continue;
            }
            printf("Accelerometer: %d %d %d\n", accel[0], accel[1], accel[2]);
            printf("Gyroscope: %d %d %d\n", gyro[0], gyro[1], gyro[2]);
            usleep(50000); // 50ms
            break;
        }
    }
    return NULL;
}

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    signal(SIGINT, sigint_handler);

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, &read_loop, NULL) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    pthread_join(thread_id, NULL);

    close(i2c_fd);
    return 0;
}

