#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <wiringPi.h>
#include <Adafruit_ADXL345_U.h>

#define ADXL345_ADDR 0x53
#define LED_PIN 17
#define SAMPLE_RATE 100 // in ms

Adafruit_ADXL345 adxl = Adafruit_ADXL345();
FILE *logFile;

void cleanup(int signum) {
    fclose(logFile);
    digitalWrite(LED_PIN, LOW);
    adxl.powerOff();
    exit(0);
}

int main() {
    int16_t x, y, z;
    float magnitude;
    time_t rawtime;
    struct tm * timeinfo;
    char buffer[80];

    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(LED_PIN, OUTPUT);
    digitalWrite(LED_PIN, LOW);

    if (!adxl.begin(ADXL345_ADDR)) {
        printf("Failed to initialize ADXL345\n");
        return 1;
    }

    adxl.setRange(ADXL345_RANGE_16G);

    if (signal(SIGINT, cleanup) == SIG_ERR || signal(SIGTERM, cleanup) == SIG_ERR) {
        printf("Failed to set up signal handlers\n");
        return 1;
    }

    logFile = fopen("impact_log.txt", "w");
    if (logFile == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    while (1) {
        if (adxl.readXYZ(&x, &y, &z)) {
            magnitude = sqrt(x*x + y*y + z*z) / 256.0; // scale factor is 256 LSB/g
            if (magnitude > 2.5) {
                digitalWrite(LED_PIN, HIGH);
                delay(500);
                digitalWrite(LED_PIN, LOW);

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(buffer, sizeof(buffer), "%d-%m-%Y %H:%M:%S", timeinfo);
                fprintf(logFile, "%s, %.2f, %d, %d, %d\n", buffer, magnitude, x, y, z);
                fflush(logFile);
            }
        } else {
            printf("Failed to read from ADXL345\n");
            break;
        }

        delay(SAMPLE_RATE);
    }

    return 0;
}

