#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define ICM_20602_ADDR 0x68
#define ACC_X_ADDR 0x3B
#define GYR_X_ADDR 0x43

int fd;
FILE *file;

void handle_sigint(int sig) {
    fclose(file);
    close(fd);
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ICM_20602_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    if ((file = fopen("imu_log.csv", "w")) == NULL) {
        perror("Failed to open the CSV file");
        return 1;
    }

    while (1) {
        char buf[14];
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        buf[0] = ACC_X_ADDR;
        if (write(fd, buf, 1) != 1) {
            perror("Failed to write to the i2c bus");
            return 1;
        }

        if (read(fd, buf, 6) != 6) {
            perror("Failed to read from the i2c bus");
            return 1;
        }

        buf[0] = GYR_X_ADDR;
        if (write(fd, buf, 1) != 1) {
            perror("Failed to write to the i2c bus");
            return 1;
        }

        if (read(fd, buf + 1, 6) != 6) {
            perror("Failed to read from the i2c bus");
            return 1;
        }

        fprintf(file, "%ld,%d,%d,%d,%d,%d,%d,%d,%d,%d,%d,%d\n",
                ts.tv_sec, buf[0], buf[1], buf[2], buf[3], buf[4], buf[5],
                buf[7], buf[8], buf[9], buf[10], buf[11]);

        usleep(100000);
    }

    return 0;
}

