#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <gpiod.h>

#define I2C_DEV "/dev/i2c-1"
#define MMA8451Q_ADDR 0x1D // 7-bit address
#define MMA8451Q_ID 0x2A
#define LED_GPIO 17
#define DELAY 100 // 100ms

int fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void cleanup(int signum) {
    gpiod_line_release(line);
    close(fd);
    exit(0);
}

int main() {
    // Open I2C device
    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    // Verify sensor identity
    char id;
    if (read(fd, &id, 1) != 1 || id != MMA8451Q_ID) {
        perror("Failed to verify sensor identity");
        return 1;
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, LED_GPIO);
    if (gpiod_line_request_output(line, "my-app", 0) < 0) {
        perror("Failed to request GPIO line");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Main loop
    while (1) {
        // Read acceleration data
        short x, y, z;
        if (read(fd, &x, 2) != 2 || read(fd, &y, 2) != 2 || read(fd, &z, 2) != 2) {
            perror("Failed to read acceleration data");
            return 1;
        }

        // Check if any axis exceeds threshold
        if (abs(x) > 2048 || abs(y) > 2048 || abs(z) > 2048) {
            // Turn on LED
            gpiod_line_set_value(line, 1);
            usleep(500000); // 500ms
            gpiod_line_set_value(line, 0);

            // Log reading
            FILE *log = fopen("impact_log.txt", "a");
            if (log) {
                time_t t = time(NULL);
                fprintf(log, "%ld: %d %d %d\n", t, x, y, z);
                fclose(log);
            }
        }

        usleep(DELAY * 1000); // 100ms
    }

    return 0;
}

