#include <signal.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>

#define ADXL345_DEVICE_ID 0x53
#define ADXL345_INT1_PIN 17
#define ADXL345_ADDRESS 0x1D
#define ADXL345_DEVICE_NAME "/dev/i2c-1"

#define POWER_CTL 0x2D
#define FREE_FALL_THRESHOLD 0x28
#define FREE_FALL 0x2E

int fd;
FILE *logFile;

void handle_signal(int signum) {
    digitalWrite(ADXL345_INT1_PIN, LOW);
    close(fd);
    fclose(logFile);
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(ADXL345_INT1_PIN, INPUT);

    fd = wiringPiI2CSetupInterface(ADXL345_DEVICE_NAME, ADXL345_ADDRESS);
    if (fd == -1) {
        printf("Failed to setup I2C\n");
        return 1;
    }

    int deviceId = wiringPiI2CReadReg8(fd, 0x00);
    if (deviceId != ADXL345_DEVICE_ID) {
        printf("Invalid device ID: 0x%X\n", deviceId);
        return 1;
    }

    wiringPiI2CWriteReg8(fd, POWER_CTL, 0x00); // Put the device in standby mode

    wiringPiI2CWriteReg8(fd, FREE_FALL_THRESHOLD, 0x00); // Set free fall threshold to 0
    wiringPiI2CWriteReg8(fd, FREE_FALL, 0x00); // Enable free fall detection

    logFile = fopen("freefall_log.csv", "w");
    if (logFile == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    fprintf(logFile, "Timestamp,X,Y,Z\n");
    fflush(logFile);

    pinMode(ADXL345_INT1_PIN, RISING);

    while (1) {
        if (digitalRead(ADXL345_INT1_PIN) == HIGH) {
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%F %T", localtime(&now));

            int x = wiringPiI2CReadReg8(fd, 0x32);
            int y = wiringPiI2CReadReg8(fd, 0x34);
            int z = wiringPiI2CReadReg8(fd, 0x36);

            fprintf(logFile, "%s,%d,%d,%d\n", timestamp, x, y, z);
            fflush(logFile);
        }
    }

    return 0;
}

