#include <stdio.h>
#include <stdint.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <signal.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define CS_PIN 8

#define WHO_AM_I_REG 0x00
#define GYRO_X_REG 0x1D

#define WHO_AM_I_VAL 0x16

#define SAMPLE_RATE_MS 10

FILE *log_file;

void sigint_handler(int sig) {
    fclose(log_file);
    digitalWrite(CS_PIN, LOW);
    wiringPiSPIDestroy(SPI_CHANNEL);
    exit(0);
}

int main() {
    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        printf("Failed to setup SPI\n");
        return 1;
    }

    pinMode(CS_PIN, OUTPUT);
    digitalWrite(CS_PIN, LOW);

    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    fprintf(log_file, "Timestamp,Gyro X\n");

    signal(SIGINT, sigint_handler);

    while (1) {
        uint8_t buffer[2];

        digitalWrite(CS_PIN, HIGH);
        buffer[0] = WHO_AM_I_REG | 0x80;
        wiringPiSPIDataRW(SPI_CHANNEL, buffer, 2);
        digitalWrite(CS_PIN, LOW);

        if (buffer[1] != WHO_AM_I_VAL) {
            printf("WHO_AM_I register mismatch\n");
            return 1;
        }

        digitalWrite(CS_PIN, HIGH);
        buffer[0] = GYRO_X_REG | 0x80;
        wiringPiSPIDataRW(SPI_CHANNEL, buffer, 2);
        digitalWrite(CS_PIN, LOW);

        int16_t gyro_x = (buffer[1] << 8) | buffer[0];
        float gyro_x_deg_sec = gyro_x * 0.0305;

        time_t now = time(NULL);
        fprintf(log_file, "%ld,%f\n", now, gyro_x_deg_sec);

        delay(SAMPLE_RATE_MS);
    }

    return 0;
}

