    struct timespec ts;
    char buf[256];
    int ret;

    signal(SIGINT, signal_handler);

    if ((file_i2c = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(file_i2c, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    if ((file_log = fopen(LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    fprintf(file_log, "Timestamp,X,Y,Z\n");

