        ts.tv_nsec = SAMPLE_RATE * 1000000;
        nanosleep(&ts, NULL);

        // Replace the following with the actual code to read from the sensor
        if ((ret = read(file_i2c, buf, 6)) != 6) {
            if (ret < 0) {
                perror("Failed to read from the i2c bus");
