                fprintf(stderr, "Sensor error: read %d bytes\n", ret);
            }
            continue;
        }

        // Replace the following with the actual code to parse the sensor data
        int x = buf[0] << 8 | buf[1];
        int y = buf[2] << 8 | buf[3];
        int z = buf[4] << 8 | buf[5];

        time_t now = time(NULL);
        struct tm *tm_info = gmtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", tm_info);

        fprintf(file_log, "%s,%d,%d,%d\n", timestamp, x, y, z);
    }

    return 0;
}

