#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_DEVICE "/dev/gpiochip0"
#define GPIO_LINE_1 17
#define GPIO_LINE_2 27
#define LOG_INTERVAL 50000 // 50ms

struct gpiod_chip *chip;
struct gpiod_line *line1, *line2;
FILE *log_file;

void cleanup(int signum) {
    printf("Exiting...\n");
    fclose(log_file);
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open(GPIO_DEVICE);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_LINE_1);
    line2 = gpiod_chip_get_line(chip, GPIO_LINE_2);
    if (!line1 || !line2) {
        perror("Failed to request GPIO lines");
        return 1;
    }

    if (gpiod_line_request_input(line1, "hall_sensor_1") < 0 ||
        gpiod_line_request_input(line2, "hall_sensor_2") < 0) {
        perror("Failed to configure GPIO lines as input");
        return 1;
    }

    log_file = fopen("conveyor_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        int value1 = gpiod_line_get_value(line1);
        int value2 = gpiod_line_get_value(line2);
        time_t now = time(NULL);

        fprintf(log_file, "%ld: %d %d\n", now, value1, value2);
        fflush(log_file);

        if (value1 && value2) {
            printf("Halt message: Conveyor stopped\n");
        }

        usleep(LOG_INTERVAL);
    }

    return 0;
}

