#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MMA8452Q_ADDRESS 0x1D // 7-bit address
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define OUT_Y_MSB 0x03
#define OUT_Z_MSB 0x05
#define EXPECTED_WHO_AM_I 0x2A
#define SENSITIVITY 0.0005987548828125 // 2^-12
#define TILT_THRESHOLD 45 // degrees

int fd;
FILE *log_file;

void handle_signal(int signum) {
    fclose(log_file);
    close(fd);
    exit(0);
}

int main() {
    int result;
    char buffer[6];
    struct timespec ts;

    // Open I2C device
    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    result = ioctl(fd, I2C_SLAVE, MMA8452Q_ADDRESS);
    if (result < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    // Verify sensor identity
    result = read(fd, buffer, 1);
    if (result != 1) {
        perror("Failed to read WHO_AM_I register");
        return 1;
    }
    if (buffer[0] != EXPECTED_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I register mismatch\n");
        return 1;
    }

    // Initialize device
    buffer[0] = CTRL_REG1;
    buffer[1] = 0x01; // Standby mode
    result = write(fd, buffer, 2);
    if (result != 2) {
        perror("Failed to write to control register");
        return 1;
    }

    // Set data rate to 100 Hz
    buffer[0] = CTRL_REG1;
    buffer[1] = 0x15; // Active mode, 100 Hz
    result = write(fd, buffer, 2);
    if (result != 2) {
        perror("Failed to write to control register");
        return 1;
    }

    // Open log file
    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        // Read six data registers
        result = read(fd, buffer, 6);
        if (result != 6) {
            perror("Failed to read data registers");
            return 1;
        }

        // Combine MSB and LSB of each axis
        int16_t x = (buffer[1] << 8) | buffer[0];
        int16_t y = (buffer[3] << 8) | buffer[2];
        int16_t z = (buffer[5] << 8) | buffer[4];

        // Compute absolute tilt
        double tilt = atan2(sqrt(x*x + y*y), z) * 180 / M_PI;

        // Check for tilt exceeding threshold
        if (tilt > TILT_THRESHOLD) {
            // Get timestamp
            clock_gettime(CLOCK_REALTIME, &ts);

            // Write to log file
            fprintf(log_file, "%ld.%ld %d %d %d\n", ts.tv_sec, ts.tv_nsec, x, y, z);
            fflush(log_file);
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    return 0;
}

