#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <signal.h>
#include <math.h>
#include <gpiod.h>

#define I2C_ADDR 0x1E // I2C address of the LIS3MDL
#define I2C_BUS "/dev/i2c-1" // I2C bus
#define SCALE_FACTOR 0.146 // Scale factor
#define OFFSET_X 0 // X offset
#define OFFSET_Y 0 // Y offset
#define OFFSET_Z 0 // Z offset
#define THRESHOLD 800 // Alert threshold in mG

int fd;
FILE *log_file;

void cleanup(int signum) {
    fclose(log_file);
    close(fd);
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, 17); // Assuming GPIO 17 for interrupt
    if (!line) {
        perror("Get GPIO line");
        return 1;
    }

    if (gpiod_line_request_input(line, "my-app") < 0) {
        perror("Request GPIO line");
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Select I2C address");
        return 1;
    }

    log_file = fopen("magnetic_log.txt", "w");
    if (!log_file) {
        perror("Open log file");
        return 1;
    }

    while (1) {
        char buf[6];
        float x, y, z, magnitude;
        int retry = 3;

        while (retry--) {
            if (write(fd, "\x2A\x00", 2) != 2) {
                perror("Write to I2C");
                continue;
            }

            usleep(10000); // Wait for conversion

            if (read(fd, buf, 6) != 6) {
                perror("Read from I2C");
                continue;
            }

            x = (buf[1] << 8 | buf[0]) * SCALE_FACTOR + OFFSET_X;
            y = (buf[3] << 8 | buf[2]) * SCALE_FACTOR + OFFSET_Y;
            z = (buf[5] << 8 | buf[4]) * SCALE_FACTOR + OFFSET_Z;

            magnitude = sqrt(x * x + y * y + z * z);

            if (magnitude > THRESHOLD) {
                fprintf(stderr, "Metal detector alert: %.2f mG\n", magnitude);
            }

            fprintf(log_file, "%.2f,%.2f,%.2f\n", x, y, z);
            fflush(log_file);

            break;
        }

        if (retry < 0) {
            fprintf(stderr, "Failed to initialize sensor\n");
            return 1;
        }

        value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Read GPIO line");
            return 1;
        }

        if (value) {
            usleep(100000); // Wait for interrupt to be cleared
        }
    }

    return 0;
}

