#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define GPIO_LINE 8
#define GPIO_CHIP "gpiochip0"
#define SCALE_FACTOR 0.02

int spi_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void cleanup(int signum) {
    close(spi_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    struct spi_ioc_transfer spi_xfer[2];
    unsigned char tx_data[2] = {0x80, 0x00};
    unsigned char rx_data[2] = {0, 0};
    int ret;

    signal(SIGINT, cleanup);

    // Open SPI device
    if ((spi_fd = open(SPI_DEV, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        return 1;
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        return 1;
    }

    // Open GPIO chip
    if ((chip = gpiod_chip_open_by_name(GPIO_CHIP)) == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get GPIO line
    if ((line = gpiod_chip_get_line(chip, GPIO_LINE)) == NULL) {
        perror("Failed to get GPIO line");
        return 1;
    }

    // Set GPIO line as output
    if (gpiod_line_request_output(line, "my_app", 0) < 0) {
        perror("Failed to set GPIO line as output");
        return 1;
    }

    // Main loop
    while (1) {
        // Set up SPI transfers
        spi_xfer[0].tx_buf = (unsigned long)tx_data;
        spi_xfer[0].rx_buf = (unsigned long)NULL;
        spi_xfer[0].len = 2;
        spi_xfer[0].delay_usecs = 0;
        spi_xfer[0].speed_hz = SPI_SPEED;
        spi_xfer[0].bits_per_word = 8;

        spi_xfer[1].tx_buf = (unsigned long)NULL;
        spi_xfer[1].rx_buf = (unsigned long)rx_data;
        spi_xfer[1].len = 2;
        spi_xfer[1].delay_usecs = 0;
        spi_xfer[1].speed_hz = SPI_SPEED;
        spi_xfer[1].bits_per_word = 8;

        // Transfer data
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(2), spi_xfer) < 0) {
            perror("Failed to transfer SPI data");
            return 1;
        }

        // Print data
        printf("X: %f, Y: %f, Z: %f\n",
               (float)rx_data[0] * SCALE_FACTOR,
               (float)rx_data[1] * SCALE_FACTOR,
               (float)rx_data[2] * SCALE_FACTOR);

        // Wait for 100ms
        usleep(100000);
    }

    return 0;
}

