    unsigned char buf[6];
    int res;

    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, LSM6DSR_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    if (read(fd, buf, 1) != 1 || buf[0] != WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I register mismatch\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        if ((res = write(fd, buf, 1)) != 1) {
            perror("Failed to write to the i2c bus");
            return 1;
        }

        if ((res = read(fd, buf, 6)) != 6) {
            perror("Failed to read from the i2c bus");
            return 1;
        }

        printf("%d %d %d %d %d %d\n", buf[0], buf[1], buf[2], buf[3], buf[4], buf[5]);
        usleep(100000);
    }

    return 0;
}

