#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>

#define ADXL345_DEVICE 0x53 // ADXL345 I2C address
#define PI 3.14159265358979323846
#define THRESHOLD 30.0

int fd;

void handle_interrupt(int signum) {
    printf("Interrupt signal received, cleaning up...\n");
    close(fd);
    exit(0);
}

float get_tilt_angle() {
    int x = wiringPiI2CReadReg8(fd, 0x32);
    int y = wiringPiI2CReadReg8(fd, 0x34);
    int z = wiringPiI2CReadReg8(fd, 0x36);

    float angle = atan2(sqrt(y*y + z*z), x) * 180.0 / PI;

    return angle;
}

void write_to_log(float angle) {
    FILE *file = fopen("/var/log/tilt_events.log", "a");
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s: Tilt angle = %.2f degrees\n", time_str, angle);
    fclose(file);
}

int main() {
    signal(SIGINT, handle_interrupt);

    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    fd = wiringPiI2CSetup(ADXL345_DEVICE);
    if (fd == -1) {
        printf("Failed to setup I2C communication\n");
        return 1;
    }

    wiringPiI2CWriteReg8(fd, 0x2D, 0x10); // Enable measurement mode

    while (1) {
        float angle = get_tilt_angle();
        if (fabs(angle) > THRESHOLD) {
            write_to_log(angle);
        }
        delay(100);
    }

    return 0;
}

