#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>

#define DEVICE_ADDR 0x23 // BH1750FVI device address
#define POWER_DOWN 0x00 // No active state
#define POWER_ON 0x01 // Power on
#define RESET 0x07 // Reset data register value
#define ONE_TIME_HIGH_RES_MODE 0x20 // Start measurement at 1 lux resolution. Time typically 120ms

int file_i2c;
int length;
char buffer[2];

void signal_handler(int signum) {
    printf("Closing I2C bus and exiting...\n");
    close(file_i2c);
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);

    if ((file_i2c = open("/dev/i2c-1", O_RDWR)) < 0) {
        printf("Failed to open the i2c bus\n");
        return 1;
    }

    if (ioctl(file_i2c, I2C_SLAVE, DEVICE_ADDR) < 0) {
        printf("Failed to acquire bus access or talk to slave\n");
        return 1;
    }

    buffer[0] = ONE_TIME_HIGH_RES_MODE;
    length = 1;
    if (write(file_i2c, buffer, length) != length) {
        printf("Failed to write to the i2c bus\n");
        return 1;
    }

    FILE *file = fopen("light_log.txt", "w");
    if (file == NULL) {
        printf("Failed to open the log file\n");
        return 1;
    }

    while (1) {
        sleep(5);

        buffer[0] = POWER_DOWN;
        length = 1;
        if (write(file_i2c, buffer, length) != length) {
            printf("Failed to write to the i2c bus\n");
            return 1;
        }

        usleep(180000); // Wait for 180ms

        if (read(file_i2c, buffer, 2) != 2) {
            printf("Failed to read from the i2c bus\n");
            return 1;
        }

        int lux = (buffer[0] << 8) | buffer[1];

        time_t now = time(NULL);
        fprintf(file, "Timestamp: %ld, Lux: %d\n", now, lux);
        fflush(file);
    }

    return 0;
}

