    signal(SIGTERM, stop);

    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi: ");
        return 1;
    }

    fd = wiringPiI2CSetup(I2C_BUS);
    if (fd == -1) {
        printf("Failed to open I2C bus: ");
        return 1;
    }

    if (wiringPiSPISetup(PWM_PIN, SAMPLE_RATE) == -1) {
        printf("Failed to setup PWM: ");
        return 1;
    }

    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd == -1) {
        printf("Failed to create socket: ");
        return 1;
    }

    // Bind, listen, accept code here

    while (1) {
        char buffer[1024];
        int bytesRead = recv(sockfd, buffer, 1024, 0);
        if (bytesRead > 0) {
            if (strncmp(buffer, "MOTION_DETECTED:", 15) == 0 && strcmp(buffer + 15, SECRET_KEY) == 0) {
                // Motion detected, start playing
                for (int i = 0; i < 50; i++) {
                    // Read touch values and play PWM tone
                    int touchValue = wiringPiI2CReadReg8(fd, 0x2B);
                    digitalWrite(PWM_PIN, HIGH);
                    delay(touchValue);
                    digitalWrite(PWM_PIN, LOW);
                    delay(100 - touchValue);

                    // Log frequency to file
                    FILE *file = fopen("frequency_log.txt", "a");
                    if (file != NULL) {
                        fprintf(file, "%d\n", touchValue);
                        fclose(file);
                    }

                    delay(20);
                }
            }
        }
    }

    return 0;
}

