#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <stdio.h>
#include <signal.h>

#define LSM303DLHC_ADDR 0x1E // I2C address of the LSM303DLHC magnetometer
#define LED_PIN 17 // GPIO pin connected to the LED
#define SAMPLE_RATE 100 // Sample rate in milliseconds

int fd; // I2C file descriptor

void cleanup(int signum) {
    // Cleanup code here
    printf("Cleaning up...\n");
    digitalWrite(LED_PIN, LOW); // Turn off the LED
    close(fd); // Close the I2C file descriptor
    printf("Exiting...\n");
    exit(0);
}

int main() {
    int res;
    int data[6];
    float z_magnitude;

    // Set up signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    // Initialize I2C
    fd = wiringPiI2CSetup(LSM303DLHC_ADDR);
    if (fd == -1) {
        printf("Failed to setup I2C\n");
        return 1;
    }

    // Initialize GPIO
    pinMode(LED_PIN, PWM_OUTPUT);

    // Main loop
    while (1) {
        // Read six bytes from the magnetometer
        for (int i = 0; i < 6; i++) {
            data[i] = wiringPiI2CReadReg8(fd, 0xA0 + i);
            if (data[i] == -1) {
                printf("Failed to read from I2C\n");
                continue;
            }
        }

        // Extract the Z-axis field magnitude
        z_magnitude = (data[2] << 8) | data[3];

        // Set the LED brightness
        pwmWrite(LED_PIN, (int)(z_magnitude / 65536.0 * 1024.0));

        // Sleep for the sample rate
        delay(SAMPLE_RATE);
    }

    return 0;
}

