#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <gpiod.h>
#include <signal.h>

#define GPIO17 17
#define GPIO27 27
#define UART0 "/dev/serial0"
#define UART1 "/dev/serial1"
#define BAUD_RATE B9600
#define TIMEOUT 5
#define CODE_LEN 7  // Include null terminator
#define EXPECTED_CODE "123456"

int uart0_fd, uart1_fd;
struct gpiod_chip *chip;
struct gpiod_line *line17, *line27;

void cleanup(int signum) {
    gpiod_line_set_value(line17, 0);
    gpiod_line_set_value(line27, 0);
    close(uart0_fd);
    close(uart1_fd);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    char code1[CODE_LEN], code2[CODE_LEN];
    struct termios options;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO17);
    line27 = gpiod_chip_get_line(chip, GPIO27);
    if (!line17 || !line27) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        return 1;
    }

    uart0_fd = open(UART0, O_RDONLY | O_NOCTTY | O_NONBLOCK);
    uart1_fd = open(UART1, O_RDONLY | O_NOCTTY | O_NONBLOCK);
    if (uart0_fd < 0 || uart1_fd < 0) {
        fprintf(stderr, "Failed to open UART ports\n");
        return 1;
    }

    tcgetattr(uart0_fd, &options);
    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);
    cfmakeraw(&options);
    tcsetattr(uart0_fd, TCSANOW, &options);

    tcgetattr(uart1_fd, &options);
    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);
    cfmakeraw(&options);
    tcsetattr(uart1_fd, TCSANOW, &options);

    while (1) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(uart0_fd, &readfds);
        FD_SET(uart1_fd, &readfds);

        if (select(uart1_fd + 1, &readfds, NULL, NULL, NULL) < 0) {
            fprintf(stderr, "Read timeout\n");
            continue;
        }

        if (FD_ISSET(uart0_fd, &readfds)) {
            read(uart0_fd, code1, CODE_LEN);
        }

        if (FD_ISSET(uart1_fd, &readfds)) {
            read(uart1_fd, code2, CODE_LEN);
        }

        if (strncmp(code1, EXPECTED_CODE, CODE_LEN) == 0 && strncmp(code2, EXPECTED_CODE, CODE_LEN) == 0) {
            gpiod_line_set_value(line17, 1);
            gpiod_line_set_value(line27, 1);
            sleep(2);
            gpiod_line_set_value(line17, 0);
            gpiod_line_set_value(line27, 0);
        }
    }

    return 0;
}

