#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <wiringPiI2C.h>
#include <wiringPi.h>
#include <time.h>

#define MPU6050_ADDR 0x68 // MPU6050 device address
#define BUFFER_SIZE 1000

int fd;
float buffer[BUFFER_SIZE][3];
int buffer_index = 0;

void timer_handler(union sigval sv) {
    int16_t raw_data[3];
    float accel[3];

    raw_data[0] = wiringPiI2CReadReg16(fd, 0x3B);
    raw_data[1] = wiringPiI2CReadReg16(fd, 0x3D);
    raw_data[2] = wiringPiI2CReadReg16(fd, 0x3F);

    accel[0] = (float)raw_data[0] / 16384.0;
    accel[1] = (float)raw_data[1] / 16384.0;
    accel[2] = (float)raw_data[2] / 16384.0;

    buffer[buffer_index][0] = accel[0];
    buffer[buffer_index][1] = accel[1];
    buffer[buffer_index][2] = accel[2];

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

void signal_handler(int signum) {
    printf("Cleaning up...\n");
    free(buffer);
    close(fd);
    exit(0);
}

int main() {
    struct sigevent sev;
    timer_t timer_id;
    struct itimerspec its;

    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    fd = wiringPiI2CSetup(MPU6050_ADDR);
    if (fd == -1) {
        printf("Failed to setup I2C\n");
        return 1;
    }

    sev.sigev_notify = SIGEV_THREAD;
    sev.sigev_value.sival_ptr = &timer_id;
    sev.sigev_notify_function = timer_handler;
    sev.sigev_notify_attributes = NULL;

    if (timer_create(CLOCK_REALTIME, &sev, &timer_id) == -1) {
        printf("Failed to create timer\n");
        return 1;
    }

    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 100000000; // 100 Hz
    its.it_interval = its.it_value;

    if (timer_settime(timer_id, 0, &its, NULL) == -1) {
        printf("Failed to set timer\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        sleep(1);
    }

    return 0;
}

