    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen("co2_log.json", "w");
    error_file = fopen("co2_error.log", "w");

    if (sp_get_port_by_name(UART_DEVICE, &port) != SP_OK) {
        fprintf(error_file, "%ld: Failed to open UART device\n", time(NULL));
        fclose(log_file);
        fclose(error_file);
        return 1;
    }

    if (sp_open(port, SP_MODE_READ_WRITE) != SP_OK) {
        fprintf(error_file, "%ld: Failed to open UART port\n", time(NULL));
        sp_free(port);
        fclose(log_file);
        fclose(error_file);
        return 1;
    }

    if (sp_set_baudrate(port, BAUD_RATE) != SP_OK) {
        fprintf(error_file, "%ld: Failed to set UART baud rate\n", time(NULL));
        sp_close(port);
        sp_free(port);
        fclose(log_file);
        fclose(error_file);
        return 1;
    }

    while (1) {
        uint8_t buffer[9];
        int i, checksum = 0;
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        if (sp_flush(port, SP_BUF_BOTH) != SP_OK) {
            fprintf(error_file, "%ld: Failed to flush UART buffer\n", time(NULL));
            continue;
        }

        if (sp_write(port, "\xFF\x01\x86\x00\x00\x00\x00\x00\x79", 9) != SP_OK) {
            fprintf(error_file, "%ld: Failed to write to UART\n", time(NULL));
            continue;
        }

        usleep(READ_TIMEOUT);

        for (i = 0; i < 9; i++) {
            int ret = sp_blocking_read(port, buffer + i, 1, READ_TIMEOUT);
            if (ret != 1) {
                fprintf(error_file, "%ld: Failed to read from UART\n", time(NULL));
                continue;
            }
            checksum += buffer[i];
        }

        if (checksum != (buffer[0] << 8) + buffer[1]) {
            fprintf(error_file, "%ld: Checksum mismatch\n", time(NULL));
            continue;
        }

        json_object *obj = json_object_new_object();
        json_object_object_add(obj, "timestamp", json_object_new_int64(ts.tv_nsec));
        json_object_object_add(obj, "ppm", json_object_new_int(buffer[2] << 8 | buffer[3]));
        json_object_object_add(obj, "error", json_object_new_boolean(buffer[4] != 0));

        char *json_str = json_object_to_json_string(obj);
        fprintf(stdout, "%s\n", json_str);
        fprintf(log_file, "%s\n", json_str);
        fflush(log_file);

        json_object_put(obj);
        free(json_str);

        usleep(SAMPLE_INTERVAL);
    }

    return 0;
}

