#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <wiringPi.h>
#include <smbus2.h>
#include <unistd.h>

#define I2C_ADDR 0x1E // HMC5883L I2C address
#define GPIO_PIN 17 // GPIO pin number
#define BUFFER_SIZE 100 // Circular buffer size
#define SAMPLE_INTERVAL 100000 // Sample interval in microseconds
#define TARGET_HEADING 90.0 // Target heading in degrees
#define DEVIATION_THRESHOLD 10.0 // Deviation threshold in degrees

int i2c_fd; // I2C file descriptor
double buffer[BUFFER_SIZE]; // Circular buffer
int buffer_index = 0; // Current index in the buffer

void handle_signal(int signum) {
    // Cleanup and exit
    close(i2c_fd);
    exit(0);
}

double read_heading() {
    // Read raw data from the HMC5883L
    int16_t raw_x, raw_y;
    if (i2cReadReg16(i2c_fd, 0x03, &raw_x) < 0) {
        perror("i2cReadReg16");
        return 0.0;
    }
    if (i2cReadReg16(i2c_fd, 0x05, &raw_y) < 0) {
        perror("i2cReadReg16");
        return 0.0;
    }

    // Apply hard-iron compensation
    double x = raw_x - 100.0;
    double y = raw_y + 50.0;

    // Calculate heading
    double heading = atan2(y, x) * 180.0 / M_PI;
    if (heading < 0) heading += 360.0;

    return heading;
}

void store_heading(double heading) {
    // Store the heading in the circular buffer
    buffer[buffer_index++] = heading;
    if (buffer_index >= BUFFER_SIZE) buffer_index = 0;
}

double calculate_average_heading() {
    // Calculate the average heading from the buffer
    double sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer[i];
    }
    return sum / BUFFER_SIZE;
}

int main() {
    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize wiringPi and I2C
    if (wiringPiSetupGpio() == -1) {
        perror("wiringPiSetupGpio");
        return 1;
    }
    if ((i2c_fd = openI2CBus(1, I2C_ADDR)) < 0) {
        perror("openI2CBus");
        return 1;
    }

    // Set up GPIO pin
    pinMode(GPIO_PIN, OUTPUT);

    // Main loop
    while (1) {
        double heading = read_heading();
        store_heading(heading);

        double average_heading = calculate_average_heading();
        double deviation = fabs(average_heading - TARGET_HEADING);

        // Drive GPIO pin high if deviation is greater than threshold
        if (deviation > DEVIATION_THRESHOLD) {
            digitalWrite(GPIO_PIN, HIGH);
        } else {
            digitalWrite(GPIO_PIN, LOW);
        }

        // Sleep for the sample interval
        usleep(SAMPLE_INTERVAL);
    }

    return 0;
}

