#include <bcm2835.h>
#include <stdio.h>
#include <time.h>
#include <unistd.h>
#include <stdlib.h>
#include <i2c-dev.h>

#define BH1750_ADDR 0x23
#define DELAY 120
#define RED_GPIO 17
#define GREEN_GPIO 27
#define BLUE_GPIO 22

FILE *log_file;

void setup() {
    if (!bcm2835_init()) {
        printf("bcm2835_init failed. Are you running as root?\n");
        exit(1);
    }

    bcm2835_gpio_fsel(RED_GPIO, BCM2835_GPIO_FSEL_OUTP);
    bcm2835_gpio_fsel(GREEN_GPIO, BCM2835_GPIO_FSEL_OUTP);
    bcm2835_gpio_fsel(BLUE_GPIO, BCM2835_GPIO_FSEL_OUTP);

    log_file = fopen("lighting_log.txt", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        exit(1);
    }
}

void cleanup() {
    fclose(log_file);
    bcm2835_close();
}

void handle_light(float lux) {
    if (lux < 50) {
        bcm2835_gpio_write(RED_GPIO, HIGH);
    } else if (lux < 150) {
        bcm2835_gpio_write(RED_GPIO, LOW);
        bcm2835_gpio_write(GREEN_GPIO, HIGH);
    } else if (lux < 300) {
        bcm2835_gpio_write(GREEN_GPIO, LOW);
        bcm2835_gpio_write(BLUE_GPIO, HIGH);
    } else {
        bcm2835_gpio_write(BLUE_GPIO, LOW);
        bcm2835_gpio_write(RED_GPIO, HIGH);
        bcm2835_gpio_write(GREEN_GPIO, HIGH);
        bcm2835_gpio_write(BLUE_GPIO, HIGH);
    }
}

int main() {
    setup();

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        printf("Failed to open I2C bus\n");
        cleanup();
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        printf("Failed to acquire bus access or talk to slave\n");
        cleanup();
        exit(1);
    }

    while (1) {
        char buffer[2] = {0};
        if (write(fd, buffer, 1) != 1) {
            printf("Failed to write to the i2c bus\n");
            cleanup();
            exit(1);
        }

        usleep(DELAY * 1000);

        if (read(fd, buffer, 2) != 2) {
            printf("Failed to read from the i2c bus\n");
            cleanup();
            exit(1);
        }

        float lux = (buffer[0] << 8) | buffer[1];
        time_t now = time(NULL);
        fprintf(log_file, "%ld, %f\n", now, lux);
        fflush(log_file);

        handle_light(lux);

        sleep(1);
    }

    cleanup();
    return 0;
}

