#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define PWM_FREQ 100
#define PWM_RANGE 100
#define FADE_TIME 1800

int relays[NUM_RELAYS] = {4, 17, 27, 22};
int current_state[NUM_RELAYS];
int target_state[NUM_RELAYS];
time_t target_time[NUM_RELAYS];

void handle_signal(int signum) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relays[i], 0);
        gpioSetPWMfrequency(relays[i], 0);
    }
    gpioTerminate();
    exit(0);
}

void check_schedule(void) {
    FILE *file = fopen("lighting_schedule.txt", "r");
    if (file == NULL) {
        perror("Failed to open schedule file");
        return;
    }

    char line[100];
    while (fgets(line, sizeof(line), file)) {
        int hour, minute, second, relay;
        char state[10];
        if (sscanf(line, "%d:%d:%d,%d,%s", &hour, &minute, &second, &relay, state) != 5) {
            fprintf(stderr, "Invalid schedule entry: %s", line);
            continue;
        }

        if (relay < 0 || relay >= NUM_RELAYS) {
            fprintf(stderr, "Invalid relay number: %d\n", relay);
            continue;
        }

        time_t target = hour * 3600 + minute * 60 + second;
        if (target_time[relay] != target) {
            target_time[relay] = target;
            target_state[relay] = strcmp(state, "on") == 0 ? 1 : 0;
        }
    }

    fclose(file);
}

void update_relays(void) {
    time_t now = time(NULL);
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (target_time[i] > now) {
            int dutycycle = (now % target_time[i]) * 100 / target_time[i];
            gpioPWM(relays[i], PWM_FREQ, dutycycle);
            gpioWrite(relays[i], current_state[i] != target_state[i]);
        } else {
            gpioWrite(relays[i], target_state[i]);
            gpioSetPWMfrequency(relays[i], 0);
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioSetMode(relays[i], PI_OUTPUT);
        current_state[i] = 0;
        target_state[i] = 0;
        target_time[i] = 0;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        check_schedule();
        update_relays();
        time_t now = time(NULL);
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (target_time[i] > now) {
                sleep(1);
                break;
            }
        }
    }

    return 0;
}

