#include <wiringPiI2C.h>
#include <wiringPi.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>

#define MPU6050_ADDR 0x68 // MPU-6050 device address
#define SMPLRT_DIV 0x19
#define CONFIG 0x1A
#define GYRO_XOUT_H 0x43
#define PWR_MGMT_1 0x6B

int fd;
FILE *file;

void signal_handler(int signum) {
    fclose(file);
    close(fd);
    exit(0);
}

int main() {
    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    fd = wiringPiI2CSetup(MPU6050_ADDR);
    if (fd == -1) {
        printf("Failed to setup I2C\n");
        return 1;
    }

    if (wiringPiI2CWriteReg8(fd, SMPLRT_DIV, 0x07) == -1) {
        printf("Failed to write to I2C\n");
        return 1;
    }

    if (wiringPiI2CWriteReg8(fd, PWR_MGMT_1, 0x01) == -1) {
        printf("Failed to write to I2C\n");
        return 1;
    }

    if (wiringPiI2CWriteReg8(fd, CONFIG, 0) == -1) {
        printf("Failed to write to I2C\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((file = fopen("gyro_log.txt", "w")) == NULL) {
        printf("Failed to open file\n");
        return 1;
    }

    while (1) {
        int16_t gyro_x, gyro_y, gyro_z;
        time_t now = time(NULL);

        gyro_x = wiringPiI2CReadReg16(fd, GYRO_XOUT_H);
        gyro_y = wiringPiI2CReadReg16(fd, GYRO_XOUT_H + 2);
        gyro_z = wiringPiI2CReadReg16(fd, GYRO_XOUT_H + 4);

        fprintf(file, "%ld %d %d %d\n", now, gyro_x, gyro_y, gyro_z);
        fflush(file);

        delay(100);
    }

    return 0;
}

