#include <pigpio.h>
#include <signal.h>
#include <stdbool.h>

#define BUTTON_GPIO 17
#define BUZZER_GPIO 18
#define MELODY_LENGTH 10
#define DEBOUNCE_TIME 50 // in ms

const int melody[MELODY_LENGTH] = {262, 294, 330, 349, 392, 440, 494, 523, 587, 659}; // C5, D5, E5, F5, G5, A5, B5, C6, D6, E6

volatile bool button_pressed = false;
volatile bool stop_melody = false;

void button_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_ON) {
        button_pressed = true;
    }
}

void play_melody(int gpio, int level, uint32_t tick) {
    for (int i = 0; i < MELODY_LENGTH; i++) {
        if (stop_melody) {
            gpioHardwarePWM(BUZZER_GPIO, 0, 0);
            stop_melody = false;
            break;
        }
        gpioHardwarePWM(BUZZER_GPIO, melody[i], 500000); // 50% duty cycle
        time_sleep(0.1); // duration of each note
        gpioHardwarePWM(BUZZER_GPIO, 0, 0); // stop PWM
        time_sleep(0.1); // pause between notes
    }
    button_pressed = false;
}

void signal_handler(int signum) {
    gpioHardwarePWM(BUZZER_GPIO, 0, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    gpioSetISRFunc(BUTTON_GPIO, EITHER_EDGE, DEBOUNCE_TIME, &button_callback);

    while (true) {
        if (button_pressed) {
            gpioSetISRFunc(BUTTON_GPIO, EITHER_EDGE, DEBOUNCE_TIME, &play_melody);
        }
        time_sleep(0.1);
    }

    return 0;
}

