#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_LINE 17
#define WINDOW_SIZE 5
#define DEFAULT_TIMEOUT 1000

volatile sig_atomic_t stop;
struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *log_file;

void signal_handler(int signum) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    int timeout = DEFAULT_TIMEOUT;
    if (argc > 1) {
        timeout = atoi(argv[1]);
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    if (gpiod_line_request_both_edges_events(line, "vibration_sensor") < 0) {
        perror("Failed to request GPIO line");
        return 1;
    }

    log_file = fopen("vibration_events.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int window[WINDOW_SIZE] = {0};
    int window_index = 0;
    int count = 0;

    while (!stop) {
        struct gpiod_line_event evt;
        int ret = gpiod_line_event_wait_timeout(line, timeout);
        if (ret < 0) {
            perror("Failed to wait for GPIO event");
            return 1;
        } else if (ret > 0) {
            if (gpiod_line_event_read(line, &evt) < 0) {
                perror("Failed to read GPIO event");
                return 1;
            }

            window[window_index++] = evt.event_type == GPIOD_LINE_EVENT_RISING_EDGE;
            window_index %= WINDOW_SIZE;

            if (evt.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                count = 0;
            } else {
                count++;
            }

            if (count >= 3) {
                time_t now = time(NULL);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%FT%T%z", localtime(&now));
                fprintf(log_file, "%s,%d\n", timestamp, evt.event_type == GPIOD_LINE_EVENT_RISING_EDGE);
                fflush(log_file);
                fsync(fileno(log_file));

                printf("EARTHQUAKE ALERT at %s\n", timestamp);
            }
        }
    }

    gpiod_line_release(line);
    fclose(log_file);

    return 0;
}

