#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x1E // LSM303DLHC magnetometer address
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

int i2c_fd;
FILE *csv_file;
pthread_t thread;

void cleanup(int signum) {
    close(i2c_fd);
    fclose(csv_file);
    exit(0);
}

void* sample_magnetometer(void* arg) {
    while (1) {
        char buf[6];
        if (read(i2c_fd, buf, 6) != 6) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        int x = (buf[0] << 8) | buf[1];
        int y = (buf[2] << 8) | buf[3];
        int z = (buf[4] << 8) | buf[5];

        x -= X_OFFSET;
        y -= Y_OFFSET;
        z -= Z_OFFSET;

        double heading = atan2(y, x) * 180 / M_PI;
        if (heading < 0) heading += 360;

        char direction[2];
        if (heading < 22.5 || heading >= 337.5) direction[0] = 'N';
        else if (heading < 67.5) direction[0] = 'NE';
        else if (heading < 112.5) direction[0] = 'E';
        else if (heading < 157.5) direction[0] = 'SE';
        else if (heading < 202.5) direction[0] = 'S';
        else if (heading < 247.5) direction[0] = 'SW';
        else if (heading < 292.5) direction[0] = 'W';
        else direction[0] = 'NW';
        direction[1] = '\0';

        time_t now = time(NULL);
        fprintf(csv_file, "%ld,%d,%d,%d,%f,%s\n", now, x, y, z, heading, direction);
        fflush(csv_file);

        printf("Timestamp: %ld, X: %d, Y: %d, Z: %d, Heading: %f, Direction: %s\n", now, x, y, z, heading, direction);

        sleep(1);
    }

    return NULL;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("I2C slave setup failed");
        return 1;
    }

    csv_file = fopen("mag_log.csv", "a+");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(csv_file, 0, SEEK_END);
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading, Direction\n");
        fflush(csv_file);
    }

    pthread_create(&thread, NULL, sample_magnetometer, NULL);
    pthread_join(thread, NULL);

    return 0;
}

