#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <json-c/json.h>

#define GPIO_TOUCH 4
#define GPIO_RELAY 17
#define DEBOUNCE_TIME 200 // in ms

struct timespec last_touch;
struct gpiod_chip *chip;
struct gpiod_line *touch_line, *relay_line;

void handle_sigint(int sig) {
    gpiod_line_set_value(relay_line, 0);
    gpiod_line_release(relay_line);
    gpiod_line_release(touch_line);
    gpiod_chip_close(chip);
    exit(0);
}

void log_state(int state) {
    struct json_object *json_obj = json_object_new_object();
    char timestamp[20];
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    strftime(timestamp, sizeof(timestamp), "%FT%TZ", tm);
    json_object_object_add(json_obj, "timestamp", json_object_new_string(timestamp));
    json_object_object_add(json_obj, "relay_state", json_object_new_string(state ? "ON" : "OFF"));
    FILE *file = fopen("relay_log.json", "a");
    if (file) {
        fprintf(file, "%s\n", json_object_to_json_string(json_obj));
        fclose(file);
    }
    json_object_put(json_obj);
}

int main() {
    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    touch_line = gpiod_chip_get_line(chip, GPIO_TOUCH);
    if (!touch_line) {
        perror("Failed to get touch line");
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!relay_line) {
        perror("Failed to get relay line");
        return 1;
    }

    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        perror("Failed to request touch line as input");
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        perror("Failed to request relay line as output");
        return 1;
    }

    clock_gettime(CLOCK_MONOTONIC, &last_touch);

    while (1) {
        int value = gpiod_line_get_value(touch_line);
        if (value) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            if ((now.tv_sec - last_touch.tv_sec) * 1000 + (now.tv_nsec - last_touch.tv_nsec) / 1000000 >= DEBOUNCE_TIME) {
                int relay_state = !gpiod_line_get_value(relay_line);
                gpiod_line_set_value(relay_line, relay_state);
                log_state(relay_state);
                last_touch = now;
            }
        }
    }

    return 0;
}

