#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>

#define RELAY1 17
#define RELAY2 23
#define RELAY3 24
#define RELAY4 25

FILE *log_file;

void signal_handler(int signum) {
    gpioWrite(RELAY1, 1);
    gpioWrite(RELAY2, 1);
    gpioWrite(RELAY3, 1);
    gpioWrite(RELAY4, 1);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGTERM handler\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    srand(time(NULL));
    int relays[] = {RELAY1, RELAY2, RELAY3, RELAY4};
    int num_relays = sizeof(relays) / sizeof(int);

    for (int i = 0; i < num_relays; i++) {
        if (gpioSetMode(relays[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO mode\n");
            return 1;
        }
    }

    while (1) {
        for (int i = 0; i < num_relays; i++) {
            gpioWrite(relays[i], 0);
            time_t now = time(NULL);
            struct tm *ptm = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", ptm);
            int moisture = rand() % 101;
            fprintf(log_file, "%s, Relay %d, Moisture level: %d\n", timestamp, relays[i], moisture);
            fflush(log_file);
            sleep(5);

            gpioWrite(relays[i], 1);
            sleep(1);
        }
        sleep(10);
    }

    return 0;
}

