#include <unistd.h>

#define VALVE_SERVO 17
#define NOZZLE_SERVO 18

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
    gpioServo(VALVE_SERVO, 0);
    gpioServo(NOZZLE_SERVO, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioSetMode(VALVE_SERVO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set valve servo mode\n");
        return 1;
    }

    if (gpioSetMode(NOZZLE_SERVO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set nozzle servo mode\n");
        return 1;
    }

    int soil_moisture_values[] = {20, 40, 60, 80, 100};
    int nozzle_angles[] = {0, 45, 90, 135, 180};
    int i, j;

    while (!stop) {
        for (i = 0; i < 5 && !stop; i++) {
            if (soil_moisture_values[i] < 50) {
                if (gpioServo(VALVE_SERVO, 900) < 0) {
                    fprintf(stderr, "Failed to open valve\n");
                    return 1;
                }

                for (j = 0; j < 5 && !stop; j++) {
                    if (gpioServo(NOZZLE_SERVO, nozzle_angles[j]) < 0) {
                        fprintf(stderr, "Failed to position nozzle\n");
                        continue;
                    }

                    usleep(2000000); // 2 seconds
                }

                usleep(5000000); // 5 seconds

                if (gpioServo(VALVE_SERVO, 500) < 0) {
                    fprintf(stderr, "Failed to close valve\n");
                    return 1;
                }

                usleep(5000000); // 5 seconds
            }

            usleep(1000000); // 1 second
        }
    }

    gpioTerminate();
    return 0;
}

