#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>

#define MPU6050_ADDR 0x68 // MPU-6050 I2C address
#define SDA_PIN 2 // SDA pin
#define SCL_PIN 3 // SCL pin
#define SAMPLE_RATE 10 // sample rate in Hz

int fd; // I2C file descriptor

void sigint_handler(int sig) {
    printf("Exiting...\n");
    close(fd);
    exit(0);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    // Set up I2C
    fd = wiringPiI2CSetup(MPU6050_ADDR);
    if (fd == -1) {
        printf("Failed to setup I2C\n");
        return 1;
    }

    // Set up GPIO
    pinMode(SDA_PIN, OUTPUT);
    pinMode(SCL_PIN, OUTPUT);

    // Main loop
    while (1) {
        int gyro_x = wiringPiI2CReadReg8(fd, 0x3B);
        int gyro_y = wiringPiI2CReadReg8(fd, 0x3D);
        int gyro_z = wiringPiI2CReadReg8(fd, 0x3F);

        if (gyro_x == -1 || gyro_y == -1 || gyro_z == -1) {
            printf("Failed to read gyroscope data\n");
            return 1;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        FILE *file = fopen("gyro_log.txt", "a");
        if (file == NULL) {
            printf("Failed to open file\n");
            return 1;
        }

        fprintf(file, "%s,%d,%d,%d\n", timestamp, gyro_x, gyro_y, gyro_z);
        fclose(file);

        delay(1000 / SAMPLE_RATE);
    }

    return 0;
}

