#include <pigpio.h>
#include <stdio.h>
#include <signal.h>
#include <unistd.h>

#define TRIG 17
#define ECHO 18
#define MEASURE_INTERVAL 1000000 // 1 second
#define TRIGGER_INTERVAL 600000 // 60 milliseconds

FILE *file;

void sig_handler(int signum) {
    fclose(file);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if ((file = fopen("distance_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open file\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    gpioSetMode(TRIG, PI_OUTPUT);
    gpioSetMode(ECHO, PI_INPUT);

    while (1) {
        gpioWrite(TRIG, 1);
        gpioDelay(10); // 10 us
        gpioWrite(TRIG, 0);

        unsigned int startTime = 0, endTime = 0;
        int timeout = 50000; // 50 ms

        while (gpioRead(ECHO) == 0 && timeout > 0) {
            startTime = gpioTick();
            timeout--;
            gpioDelay(1);
        }

        timeout = 50000;
        while (gpioRead(ECHO) == 1 && timeout > 0) {
            endTime = gpioTick();
            timeout--;
            gpioDelay(1);
        }

        if (timeout <= 0) {
            fprintf(file, "-1\n");
            fflush(file);
            fprintf(stderr, "Timeout occurred\n");
        } else {
            float distance = (endTime - startTime) * 17150; // Speed of sound is 343m/s or 0.0343cm/us. There and back.
            fprintf(file, "%f\n", distance);
            fflush(file);
        }

        gpioDelay(TRIGGER_INTERVAL);
    }

    return 0;
}

