#include <vl53l1x_api.h>

#define GPIO_RELAY 18
#define I2C_BUS 1

VL53L1X_Dev_t dev;

void cleanup(int signum) {
    digitalWrite(GPIO_RELAY, LOW);
    VL53L1X_DeInit(&dev);
    exit(0);
}

int main() {
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(GPIO_RELAY, OUTPUT);

    signal(SIGINT, cleanup);

    if (VL53L1X_Init(&dev, I2C_BUS) != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to initialize VL53L1X sensor\n");
        return 1;
    }

    if (VL53L1X_SetDistanceMode(&dev, VL53L1X_DISTANCEMODE_LONG) != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to set distance mode\n");
        return 1;
    }

    if (VL53L1X_SetTimingBudgetInMs(&dev, 100) != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to set timing budget\n");
        return 1;
    }

    while (1) {
        uint32_t distance;
        if (VL53L1X_GetDistance(&dev, &distance) != VL53L1X_ERROR_NONE) {
            fprintf(stderr, "Failed to get distance\n");
            return 1;
        }

        printf("Distance: %d cm\n", distance);

        if (distance <= 50) {
            digitalWrite(GPIO_RELAY, HIGH);
        } else {
            digitalWrite(GPIO_RELAY, LOW);
        }

        delay(100);
    }

    return 0;
}

