#include <stdio.h>
#include <signal.h>

#define MPU6050_ADDR 0x68 // MPU-6050 device address
#define SDA_PIN 2 // SDA pin
#define SCL_PIN 3 // SCL pin

int fd;

void sig_handler(int signum) {
    printf("Caught signal %d\n", signum);
    if (fd != -1) {
        close(fd);
    }
    exit(0);
}

int main() {
    if (wiringPiSetup() == -1) {
        printf("wiringPiSetup failed\n");
        return 1;
    }

    fd = wiringPiI2CSetup(MPU6050_ADDR);
    if (fd == -1) {
        printf("wiringPiI2CSetup failed\n");
        return 1;
    }

    // Setup SDA and SCL pins
    pinMode(SDA_PIN, OUTPUT);
    pinMode(SCL_PIN, OUTPUT);

    // Setup signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        int16_t x, y, z;

        // Read x, y, and z rotation rates
        x = wiringPiI2CReadReg16(fd, 0x3b);
        y = wiringPiI2CReadReg16(fd, 0x3d);
        z = wiringPiI2CReadReg16(fd, 0x3f);

        // Convert to degrees per second
        x = (x / 131.0);
        y = (y / 131.0);
        z = (z / 131.0);

        printf("X: %d, Y: %d, Z: %d\n", x, y, z);

        delay(1000); // Wait for 1 second
    }

    return 0;
}

