#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PINS {17, 18, 27, 22}
#define RELAY_COUNT 4
#define RELAY_ACTIVE_TIME_SEC 5
#define CYCLE_TIME_SEC 86400

struct gpiod_chip *chip;
struct gpiod_line *lines[RELAY_COUNT];

void cleanup(int signum) {
    for (int i = 0; i < RELAY_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    int pins[RELAY_COUNT] = GPIO_PINS;
    for (int i = 0; i < RELAY_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            return 1;
        }
        if (gpiod_line_request_output(lines[i], "watering", 1) < 0) {
            perror("Failed to set GPIO line as output");
            return 1;
        }
    }

    time_t now;
    struct tm *timeinfo;
    char buffer[80];
    FILE *file = fopen("watering_log.txt", "a");
    if (!file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        for (int i = 0; i < RELAY_COUNT; i++) {
            gpiod_line_set_value(lines[i], 0);
            sleep(RELAY_ACTIVE_TIME_SEC);
            gpiod_line_set_value(lines[i], 1);

            time(&now);
            timeinfo = localtime(&now);
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(file, "%s Relay %d activated\n", buffer, i+1);
            fflush(file);
        }
        sleep(CYCLE_TIME_SEC - RELAY_COUNT * RELAY_ACTIVE_TIME_SEC);
    }

    return 0;
}

