#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN_17 17
#define GPIO_PIN_18 18
#define GPIO_PIN_27 27
#define GPIO_PIN_22 22

#define PWM_FREQ 1000
#define PWM_RANGE 255

FILE *logFile;

void sigintHandler(int sig) {
    fclose(logFile);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    logFile = fopen("smart_lighting.log", "w");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, sigintHandler);
    signal(SIGTERM, sigintHandler);

    gpioSetMode(GPIO_PIN_17, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_18, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_27, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_22, PI_OUTPUT);

    int pwm17 = gpioHardwarePWM(GPIO_PIN_17, PWM_FREQ, 0);
    int pwm18 = gpioHardwarePWM(GPIO_PIN_18, PWM_FREQ, 0);
    int pwm27 = gpioHardwarePWM(GPIO_PIN_27, PWM_FREQ, 0);
    int pwm22 = gpioHardwarePWM(GPIO_PIN_22, PWM_FREQ, 0);

    if (pwm17 < 0 || pwm18 < 0 || pwm27 < 0 || pwm22 < 0) {
        fprintf(stderr, "Failed to initialize PWM\n");
        return 1;
    }

    for (int i = 0; i <= PWM_RANGE; i++) {
        gpioHardwarePWMWrite(GPIO_PIN_17, PWM_FREQ, i);
        gpioHardwarePWMWrite(GPIO_PIN_18, PWM_FREQ, i);
        gpioHardwarePWMWrite(GPIO_PIN_27, PWM_FREQ, i);
        gpioHardwarePWMWrite(GPIO_PIN_22, PWM_FREQ, i);

        time_t now = time(NULL);
        fprintf(logFile, "%s: PWM duty cycle set to %d\n", ctime(&now), i);
        fflush(logFile);

        gpioSleep(1);
    }

    fclose(logFile);
    gpioTerminate();

    return 0;
}

