#include <math.h>
#include <signal.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <mpu6050.h>

#define LED_PIN 17
#define I2C_SDA_PIN 2
#define I2C_SCL_PIN 3
#define BUFFER_SIZE 100
#define SAMPLE_RATE 20
#define THRESHOLD 250

int i2c_handle;
int buffer[BUFFER_SIZE][3];
int buffer_index = 0;

void handle_signal(int signum) {
    digitalWrite(LED_PIN, LOW);
    mpu6050SetClockSource(i2c_handle, MPU6050_CLOCK_KEEP);
    mpu6050SetSleepEnabled(i2c_handle, 1);
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (wiringPiSetupGpio() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(LED_PIN, OUTPUT);
    pinMode(I2C_SDA_PIN, OUTPUT);
    pinMode(I2C_SCL_PIN, OUTPUT);

    i2c_handle = wiringPiI2CSetup(MPU6050_I2C_ADDR);
    if (i2c_handle == -1) {
        printf("Failed to setup I2C\n");
        return 1;
    }

    if (mpu6050Init(i2c_handle) != 0) {
        printf("Failed to initialize MPU6050\n");
        return 1;
    }

    mpu6050SetSampleRate(i2c_handle, SAMPLE_RATE);
    mpu6050SetClockSource(i2c_handle, MPU6050_CLOCK_PLL_XGYRO);
    mpu6050SetSleepEnabled(i2c_handle, 0);

    while (1) {
        int16_t ax, ay, az;
        mpu6050GetAcceleration(&ax, &ay, &az);

        buffer[buffer_index][0] = ax;
        buffer[buffer_index][1] = ay;
        buffer[buffer_index][2] = az;

        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        double avg_x = 0, avg_y = 0, avg_z = 0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            avg_x += buffer[i][0];
            avg_y += buffer[i][1];
            avg_z += buffer[i][2];
        }
        avg_x /= BUFFER_SIZE;
        avg_y /= BUFFER_SIZE;
        avg_z /= BUFFER_SIZE;

        double magnitude = sqrt(avg_x * avg_x + avg_y * avg_y + avg_z * avg_z);

        if (magnitude > THRESHOLD) {
            digitalWrite(LED_PIN, HIGH);
        } else {
            digitalWrite(LED_PIN, LOW);
        }

        delay(50);
    }

    return 0;
}

