int main(void)
{
    int fd;
    mpu6050_data_t data;

    if (wiringPiSetup() == -1)
    {
        printf("wiringPiSetup failed\n");
        return 1;
    }

    pinMode(GPIO_LED, OUTPUT);

    fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (fd == -1)
    {
        printf("wiringPiSPISetup failed\n");
        return 1;
    }

    if (mpu6050_init(fd, GPIO_SPI) == -1)
    {
        printf("mpu6050_init failed\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1)
    {
        if (mpu6050_get_data(fd, &data) == -1)
