#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <MPU6050.h>

#define LED_PIN 21
#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define SAMPLE_RATE 100

int fd;

void sigint_handler(int sig) {
    digitalWrite(LED_PIN, LOW);
    close(fd);
    mpu6050Free(fd);
    exit(0);
}

int main() {
    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(LED_PIN, OUTPUT);

    fd = wiringPiI2CSetup(MPU6050_ADDR);
    if (fd == -1) {
        printf("Failed to setup I2C\n");
        return 1;
    }

    if (mpu6050Init(fd) != 0) {
        printf("Failed to initialize MPU6050\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    FILE *file = fopen("tilt_log.txt", "w");
    if (file == NULL) {
        printf("Failed to open file\n");
        return 1;
    }

    while (1) {
        int16_t ax, ay, az, gx, gy, gz;
        float roll, pitch;

        if (mpu6050GetAccelerometer(&ax, &ay, &az, fd) != 0) {
            printf("Failed to read accelerometer\n");
            continue;
        }

        if (mpu6050GetGyroscope(&gx, &gy, &gz, fd) != 0) {
            printf("Failed to read gyroscope\n");
            continue;
        }

        mpu6050GetRollPitch(&roll, &pitch, ax, ay, az);

        printf("Roll: %f, Pitch: %f\n", roll, pitch);

        if (fabs(roll) > 45 || fabs(pitch) > 45) {
            digitalWrite(LED_PIN, HIGH);
        } else {
            digitalWrite(LED_PIN, LOW);
        }

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(file, "%d-%02d-%02d %02d:%02d:%02d,%f,%f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, roll, pitch);
        fflush(file);

        delay(SAMPLE_RATE);
    }

    return 0;
}

