#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_GPIO 23
#define SENSOR2_GPIO 24
#define ALERT_GPIO 17
#define DEBOUNCE_TIME 500 // in ms
#define ALERT_TIME 2000 // in ms

struct gpiod_chip *chip;
struct gpiod_line *sensor1, *sensor2, *alert;
FILE *log_file;

void handle_signal(int signum) {
    fclose(log_file);
    gpiod_line_release(sensor1);
    gpiod_line_release(sensor2);
    gpiod_line_release(alert);
    gpiod_chip_close(chip);
    exit(0);
}

void callback(struct gpiod_line *line, struct gpiod_line_event event) {
    if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        time_t t = time(NULL);
        fprintf(log_file, "%s - Seismic event detected!\n", ctime(&t));
        fflush(log_file);

        gpiod_line_set_value(alert, 1);
        usleep(ALERT_TIME);
        gpiod_line_set_value(alert, 0);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    sensor1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    sensor2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    alert = gpiod_chip_get_line(chip, ALERT_GPIO);

    if (!sensor1 || !sensor2 || !alert) {
        perror("Failed to get GPIO lines");
        return 1;
    }

    if (gpiod_line_request_both_edges_events(sensor1, "seismic_detector") < 0) {
        perror("Failed to request edge events for sensor 1");
        return 1;
    }

    if (gpiod_line_request_both_edges_events(sensor2, "seismic_detector") < 0) {
        perror("Failed to request edge events for sensor 2");
        return 1;
    }

    if (gpiod_line_request_output(alert, "seismic_detector", 0) < 0) {
        perror("Failed to request output for alert pin");
        return 1;
    }

    log_file = fopen("seismic_events.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        struct gpiod_line_event_wait_data data = {
            .timeout_ns = 1000 * 1000 * DEBOUNCE_TIME, // 500ms
            .consumer = "seismic_detector",
        };

        if (gpiod_line_event_wait(sensor1, &data) < 0) {
            perror("Failed to wait for sensor 1 event");
            return 1;
        }

        if (gpiod_line_event_wait(sensor2, &data) < 0) {
            perror("Failed to wait for sensor 2 event");
            return 1;
        }

        callback(sensor1, data.event);
        callback(sensor2, data.event);
    }

    return 0;
}

