#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define PWM_FREQ 100000000
#define PWM_PERIOD 255
#define GPIO_PWM_CHANNEL 0

struct gpiod_chip *chip;
struct gpiod_line *lines[3];

void cleanup(int signum) {
    printf("Cleaning up...\n");
    gpiod_line_release(lines[0]);
    gpiod_line_release(lines[1]);
    gpiod_line_release(lines[2]);
    gpiod_chip_close(chip);
    exit(0);
}

int main(int argc, char *argv[]) {
    int i, j, duration, ret;
    char *endptr;

    if (argc != 2) {
        printf("Usage: %s <duration>\n", argv[0]);
        return 1;
    }

    duration = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || duration < 1 || duration > 3600) {
        printf("Invalid duration\n");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Open GPIO chip");
        return 1;
    }

    for (i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, 11 + i);
        if (!lines[i]) {
            perror("Get line");
            return 1;
        }

        ret = gpiod_line_request_output(lines[i], "smart-sunset", 0);
        if (ret < 0) {
            perror("Request line as output");
            return 1;
        }
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    printf("Smart sunset simulator started. Duration: %d seconds\n", duration);

    for (i = 0; i <= PWM_PERIOD; i++) {
        for (j = 0; j < 3; j++) {
            ret = gpiod_line_set_value(lines[j], 1);
            if (ret < 0) {
                perror("Set line value");
                return 1;
            }

            ret = gpiod_line_set_pwm(lines[j], GPIO_PWM_CHANNEL, PWM_FREQ, i);
            if (ret < 0) {
                perror("Set PWM value");
                return 1;
            }

            usleep(duration * 1000000 / PWM_PERIOD);

            ret = gpiod_line_set_value(lines[j], 0);
            if (ret < 0) {
                perror("Set line value");
                return 1;
            }
        }
    }

    printf("Smart sunset simulator completed\n");

    cleanup(0);

    return 0;
}

