#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>

#define MPR121_ADDR 0x5A // MPR121 I2C address
#define GPIO_PIN 17 // GPIO pin number
#define DELAY 100 // Delay in ms

int fd; // I2C file descriptor

void signal_handler(int signum) {
    // Cleanup
    close(fd);
    digitalWrite(GPIO_PIN, LOW);
    printf("Exiting...\n");
    exit(0);
}

int main() {
    FILE *log_file;
    time_t t;

    // Setup signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (wiringPiSetupGpio() == -1) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    // Initialize I2C
    fd = wiringPiI2CSetup(MPR121_ADDR);
    if (fd == -1) {
        printf("Failed to initialize I2C\n");
        return 1;
    }

    // Initialize GPIO pin
    pinMode(GPIO_PIN, OUTPUT);
    digitalWrite(GPIO_PIN, LOW);

    // Open log file
    log_file = fopen("touch_relay.log", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (1) {
        int touch_status = wiringPiI2CReadReg8(fd, 0x00);
        if (touch_status == -1) {
            time(&t);
            fprintf(log_file, "%s: Failed to read touch status\n", ctime(&t));
            continue;
        }

        if (touch_status & 0x01) {
            delay(DELAY);
            touch_status = wiringPiI2CReadReg8(fd, 0x00);
            if (touch_status == -1) {
                time(&t);
                fprintf(log_file, "%s: Failed to read touch status\n", ctime(&t));
                continue;
            }

            if (touch_status & 0x01) {
                digitalWrite(GPIO_PIN, !digitalRead(GPIO_PIN));
                time(&t);
                fprintf(log_file, "%s: Electrode 0 touched\n", ctime(&t));
            }
        }

        delay(10);
    }

    fclose(log_file);
    return 0;
}

