#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_FLAME 17
#define GPIO_BUZZER 18
#define GPIO_LED 23
#define FLAME_DETECT_THRESHOLD 3
#define FLAME_DETECT_INTERVAL 50000 // microseconds

struct gpiod_chip *chip;
struct gpiod_line *flame, *buzzer, *led;
FILE *log_file;
int flame_detect_count = 0;

void signal_handler(int signum) {
    gpiod_line_release(flame);
    gpiod_line_release(buzzer);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    flame = gpiod_chip_get_line(chip, GPIO_FLAME);
    buzzer = gpiod_chip_get_line(chip, GPIO_BUZZER);
    led = gpiod_chip_get_line(chip, GPIO_LED);

    if (!flame || !buzzer || !led) {
        perror("Failed to get GPIO line");
        return 1;
    }

    if (gpiod_line_request_input(flame, "flame_sensor") < 0) {
        perror("Failed to request GPIO line as input");
        return 1;
    }

    if (gpiod_line_request_output(buzzer, "buzzer", 0) < 0 || gpiod_line_request_output(led, "led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        return 1;
    }

    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        int value = gpiod_line_get_value(flame);
        if (value == 0) {
            flame_detect_count++;
            if (flame_detect_count == FLAME_DETECT_THRESHOLD) {
                time_t now = time(NULL);
                fprintf(log_file, "%s Flame Detected\n", ctime(&now));
                gpiod_line_set_value(buzzer, 1);
                gpiod_line_set_value(led, 1);
                flame_detect_count = 0;
            }
        } else {
            flame_detect_count = 0;
            gpiod_line_set_value(buzzer, 0);
            gpiod_line_set_value(led, 0);
        }
        usleep(FLAME_DETECT_INTERVAL);
    }

    return 0;
}

