#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define GPIO_17 17
#define GPIO_27 27

FILE *log_file;

void sigint_handler(int sig) {
    gpioWrite(GPIO_17, PI_LOW);
    gpioWrite(GPIO_27, PI_LOW);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    if (gpioSetMode(GPIO_17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 17 mode\n");
        return 1;
    }

    if (gpioSetMode(GPIO_27, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 27 mode\n");
        return 1;
    }

    if ((log_file = fopen("dispense_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: Activating solenoid 1\n", ctime(&now));
        gpioWrite(GPIO_17, PI_HIGH);
        time_sleep(0.5);

        fprintf(log_file, "%s: Activating solenoid 2\n", ctime(&now));
        gpioWrite(GPIO_27, PI_HIGH);
        time_sleep(0.5);

        fprintf(log_file, "%s: Deactivating both solenoids\n", ctime(&now));
        gpioWrite(GPIO_17, PI_LOW);
        gpioWrite(GPIO_27, PI_LOW);

        time_sleep(5);
    }

    return 0;
}

