#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>

#define ENA 24
#define ENB 25
#define MOTOR_A_FWD 17
#define MOTOR_A_BWD 18
#define MOTOR_B_FWD 22
#define MOTOR_B_BWD 23

FILE *log_file;

void stop_motors() {
    digitalWrite(MOTOR_A_FWD, LOW);
    digitalWrite(MOTOR_A_BWD, LOW);
    digitalWrite(MOTOR_B_FWD, LOW);
    digitalWrite(MOTOR_B_BWD, LOW);
}

void handle_sigint(int sig) {
    stop_motors();
    fclose(log_file);
    exit(0);
}

int main() {
    if (wiringPiSetupGpio() == -1) {
        printf("Failed to initialize GPIO library\n");
        return 1;
    }

    pinMode(ENA, PWM_OUTPUT);
    pinMode(ENB, PWM_OUTPUT);
    pinMode(MOTOR_A_FWD, OUTPUT);
    pinMode(MOTOR_A_BWD, OUTPUT);
    pinMode(MOTOR_B_FWD, OUTPUT);
    pinMode(MOTOR_B_BWD, OUTPUT);

    signal(SIGINT, handle_sigint);

    log_file = fopen("balance_log.txt", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", tm_info);

        float tilt_error = ((float)rand() / RAND_MAX) * 20.0 - 10.0;
        float distance = ((float)rand() / RAND_MAX) * 400.0 + 2.0;

        int motor_a_speed = (int)((tilt_error + 10.0) / 20.0 * 255.0);
        int motor_b_speed = (int)((tilt_error - 10.0) / 20.0 * 255.0);

        if (distance < 20.0) {
            stop_motors();
            pwmWrite(ENA, 128);
            pwmWrite(ENB, 128);
            delay(500);
        } else {
            pwmWrite(ENA, abs(motor_a_speed) > 255 ? (motor_a_speed > 0 ? 255 : -255) : motor_a_speed);
            pwmWrite(ENB, abs(motor_b_speed) > 255 ? (motor_b_speed > 0 ? 255 : -255) : motor_b_speed);
            digitalWrite(MOTOR_A_FWD, motor_a_speed > 0);
            digitalWrite(MOTOR_A_BWD, motor_a_speed < 0);
            digitalWrite(MOTOR_B_FWD, motor_b_speed > 0);
            digitalWrite(MOTOR_B_BWD, motor_b_speed < 0);
        }

        fprintf(log_file, "%s,%f,%f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
        fflush(log_file);

        delay(50);
    }

    return 0;
}

