#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define SENSOR_GPIO 4
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY 50000 // 50ms

struct gpiod_chip *chip;
struct gpiod_line *sensor_line, *relay_line;

void cleanup(int signum) {
    printf("Cleaning up...\n");
    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Opening chip");
        return 1;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        perror("Getting line");
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Getting line");
        return 1;
    }

    int request_flags = GPIOD_LINE_REQUEST_DIRECTION_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING;
    if (gpiod_line_request_both_edges_events(sensor_line, "touch-sensor") < 0) {
        perror("Requesting line");
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        perror("Requesting line");
        return 1;
    }

    while (1) {
        struct gpiod_line_event evt;
        if (gpiod_line_event_wait(sensor_line, NULL) < 0) {
            perror("Waiting for event");
            return 1;
        }

        if (gpiod_line_event_read(sensor_line, &evt) < 0) {
            perror("Reading event");
            return 1;
        }

        if (evt.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            usleep(DEBOUNCE_DELAY);
            if (gpiod_line_get_value(sensor_line) == 1) {
                gpiod_line_set_value(relay_line, 1);
                usleep(DEBOUNCE_DELAY);
                gpiod_line_set_value(relay_line, 0);
            }
        }
    }

    return 0;
}

