#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define TCS34725_ADDR 0x29
#define TCS34725_COMMAND 0x80

int fd;
FILE *file;

void cleanup(int signum) {
    printf("Cleaning up...\n");
    close(fd);
    fclose(file);
    exit(0);
}

int main() {
    unsigned char buffer[8];
    int r, g, b, c;
    time_t t;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        return 1;
    }

    if ((file = fopen("color_data.csv", "w")) == NULL) {
        perror("Failed to open file");
        return 1;
    }

    fprintf(file, "timestamp,C,R,G,B\n");

    while (1) {
        buffer[0] = TCS34725_COMMAND;
        if (write(fd, buffer, 1) != 1) {
            perror("Failed to write to the i2c bus");
            return 1;
        }

        usleep(500000); // wait for 500ms

        if (read(fd, buffer, 8) != 8) {
            perror("Failed to read from the i2c bus");
            return 1;
        }

        c = buffer[0] << 8 | buffer[1];
        r = buffer[2] << 8 | buffer[3];
        g = buffer[4] << 8 | buffer[5];
        b = buffer[6] << 8 | buffer[7];

        time(&t);
        fprintf(file, "%ld,%d,%d,%d,%d\n", t, c, r, g, b);
        fflush(file);
    }

    return 0;
}

