#define MPU6050_ADDR 0x68 // I2C address of MPU-6050
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

int main() {
    int file_i2c = open("/dev/i2c-1", O_RDWR);
    if (file_i2c < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(file_i2c, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave");
        exit(1);
    }

    // Wake up the MPU-6050
    char buf[1] = {PWR_MGMT_1, 0x00};
    if (write(file_i2c, buf, 2) != 2) {
        perror("Failed to write to the i2c bus");
        exit(1);
    }

    FILE *file = fopen("gyro_log.csv", "w");
    if (file == NULL) {
        perror("Failed to open the log file");
        exit(1);
    }

    while (1) {
        buf[0] = GYRO_XOUT_H;
        if (write(file_i2c, buf, 1) != 1) {
            perror("Failed to write to the i2c bus");
            continue;
        }

        char data[6];
        if (read(file_i2c, data, 6) != 6) {
            perror("Failed to read from the i2c bus");
            continue;
        }

        time_t now = time(NULL);
        fprintf(file, "%ld,%d,%d,%d\n", now, data[0]<<8|data[1], data[2]<<8|data[3], data[4]<<8|data[5]);
        fflush(file);

        usleep(10000); // Sleep for 10ms
    }

    fclose(file);
    close(file_i2c);
    return 0;
}

