#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

#define ADXL345_ADDR 0x53
#define GPIO_PIN 27
#define DELAY_TIME 500
#define FREEFALL_THRESHOLD 0.2
#define FREEFALL_DURATION 500

int fd;

void sigint_handler(int sig) {
    digitalWrite(GPIO_PIN, LOW);
    close(fd);
    exit(0);
}

float read_acceleration(int axis) {
    int raw_value = wiringPiI2CReadReg16(fd, axis);
    if (raw_value < 0) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return 0;
    }
    return (float)raw_value / 256.0;
}

int main() {
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error setting up wiringPi: %s\n", strerror(errno));
        return 1;
    }

    fd = wiringPiI2CSetup(ADXL345_ADDR);
    if (fd < 0) {
        fprintf(stderr, "Error setting up I2C: %s\n", strerror(errno));
        return 1;
    }

    if (wiringPiISetupInterrupt(2, INT_EDGE_FALLING) == -1) {
        fprintf(stderr, "Error setting up interrupt: %s\n", strerror(errno));
        return 1;
    }

    pinMode(GPIO_PIN, OUTPUT);

    signal(SIGINT, sigint_handler);

    while (1) {
        float x = read_acceleration(0x32);
        float y = read_acceleration(0x34);
        float z = read_acceleration(0x36);

        if (abs(x) < FREEFALL_THRESHOLD && abs(y) < FREEFALL_THRESHOLD && abs(z) < FREEFALL_THRESHOLD) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", tm_info);

            FILE *log_file = fopen("freefall.log", "a");
            if (log_file != NULL) {
                fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
                fclose(log_file);
            }

            digitalWrite(GPIO_PIN, HIGH);
            delay(FREEFALL_DURATION);
            digitalWrite(GPIO_PIN, LOW);
        }

        delay(DELAY_TIME);
    }

    return 0;
}

