#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>

#define TRIG_PIN 4
#define ECHO_PIN 18
#define MAX_DISTANCE 23200 // Maximum distance in microseconds
#define MAX_TIMEOUT 10000000 // Maximum timeout in nanoseconds

FILE *file;
pthread_mutex_t mutex;
volatile sig_atomic_t stop;

void sigint_handler(int signum) {
    stop = 1;
}

void echo_callback(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick;
    static uint32_t end_tick;

    if (level == PI_ON) {
        start_tick = tick;
    } else {
        end_tick = tick;

        uint32_t duration = end_tick - start_tick;

        if (duration > MAX_DISTANCE) {
            printf("Invalid pulse width\n");
            return;
        }

        pthread_mutex_lock(&mutex);

        if (fprintf(file, "%u,%u\n", start_tick, duration) < 0) {
            perror("fprintf");
        }

        fflush(file);

        pthread_mutex_unlock(&mutex);
    }
}

int main() {
    if (pigpio_start(NULL, NULL) < 0) {
        perror("pigpio_start");
        return 1;
    }

    if (pthread_mutex_init(&mutex, NULL) != 0) {
        perror("pthread_mutex_init");
        return 1;
    }

    file = fopen("distance_log.txt", "w");

    if (file == NULL) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioSetAlertFunc(ECHO_PIN, echo_callback);

    while (!stop) {
        gpioWrite(TRIG_PIN, 1);
        time_sleep(0.0001); // 10 microseconds
        gpioWrite(TRIG_PIN, 0);

        time_sleep(0.2); // 200 milliseconds
    }

    gpioSetAlertFunc(ECHO_PIN, NULL);

    fclose(file);

    pthread_mutex_destroy(&mutex);

    pigpio_stop();

    return 0;
}

