#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <math.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <fcntl.h>

#define I2C_BUS "/dev/i2c-1"
#define LIS3DH_ADDR 0x19
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define RETRY_LIMIT 3

int main(int argc, char *argv[])
{
    int i2c_fd, gpio_fd;
    float acc_x, acc_y, acc_z, acc_magnitude;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    // Parse command line arguments
    float freefall_threshold = 0.2, impact_threshold = 1.5;
    if (argc > 2) {
        freefall_threshold = atof(argv[1]);
        impact_threshold = atof(argv[2]);
    }

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LIS3DH_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    // Open GPIO chip
    if ((gpio_fd = gpiod_chip_open_by_name(GPIO_CHIP)) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(gpio_fd, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    // Set GPIO line as output
    if (gpiod_line_request_output(line, "lis3dh_buzzer", 0) < 0) {
        perror("Failed to set GPIO line as output");
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer data
        for (int i = 0; i < RETRY_LIMIT; i++) {
            if (read(i2c_fd, &acc_x, sizeof(acc_x)) < 0) {
                perror("Failed to read accelerometer data");
                return 1;
            }
            if (read(i2c_fd, &acc_y, sizeof(acc_y)) < 0) {
                perror("Failed to read accelerometer data");
                return 1;
            }
            if (read(i2c_fd, &acc_z, sizeof(acc_z)) < 0) {
                perror("Failed to read accelerometer data");
                return 1;
            }
            acc_magnitude = sqrt(acc_x * acc_x + acc_y * acc_y + acc_z * acc_z);
            if (acc_magnitude < freefall_threshold) {
                printf("Freefall detected\n");
                // Activate buzzer
                gpiod_line_set_value(line, 1);
                sleep(1);
                gpiod_line_set_value(line, 0);
            } else if (acc_magnitude > impact_threshold) {
                printf("Impact detected\n");
                // Activate buzzer
                gpiod_line_set_value(line, 1);
                sleep(1);
                gpiod_line_set_value(line, 0);
            }
        }
    }

    // Cleanup
    gpiod_line_release(line);
    close(gpio_fd);
    close(i2c_fd);

    return 0;
}

