#include <time.h>

#define I2C_ADDR 0x25
#define GPIO_PIN 17
#define THRESHOLD 5.0
#define DELAY 100

int fd;

void sigint_handler(int sig) {
    digitalWrite(GPIO_PIN, LOW);
    close(fd);
    printf("Exiting...\n");
    exit(0);
}

int main() {
    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(GPIO_PIN, OUTPUT);
    digitalWrite(GPIO_PIN, LOW);

    fd = wiringPiI2CSetup(I2C_ADDR);
    if (fd == -1) {
        printf("Failed to setup I2C\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        int value = wiringPiI2CReadReg8(fd, 0x01);
        if (value == -1) {
            printf("Failed to read from I2C\n");
            digitalWrite(GPIO_PIN, LOW);
            continue;
        }

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

        printf("%s: Magnetic field reading: %d\n", timestamp, value);

        if ((double)value > THRESHOLD) {
            digitalWrite(GPIO_PIN, HIGH);
            printf("%s: Relay activated\n", timestamp);
        } else {
            digitalWrite(GPIO_PIN, LOW);
            printf("%s: Relay deactivated\n", timestamp);
        }

        delay(DELAY);
    }

    return 0;
}

