#include <sys/socket.h>
#include <netinet/in.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define PORT 5000

int server_fd, new_socket;
struct sockaddr_in address;
int opt = 1;
int addrlen = sizeof(address);
char buffer[1024] = {0};
char *msg = "Hello from server";

struct gpiod_chip *chip;
struct gpiod_line *line;

void sigint_handler(int signum) {
    printf("Caught SIGINT, exiting...\n");
    close(server_fd);
    gpiod_line_release(line);
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Caught SIGTERM, exiting...\n");
    close(server_fd);
    gpiod_line_release(line);
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Open chip failed");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Get line failed");
        return -1;
    }

    int ret = gpiod_line_request_output(line, "ky-019-relay", 0);
    if (ret < 0) {
        perror("Request line as output failed");
        return -1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        perror("Socket failed");
        return -1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        return -1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("Listen failed");
        return -1;
    }

    while (1) {
        printf("\nWaiting for a connection...\n");
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("Accept failed");
            return -1;
        }

        read(new_socket, buffer, 1024);
        printf("Received: %s\n", buffer);

        if (strcmp(buffer, "ON") == 0) {
            gpiod_line_set_value(line, 1);
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            FILE *file = fopen("relay_log.txt", "a");
            fprintf(file, "[%d-%02d-%02d %02d:%02d:%02d] Relay ON\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);
            fclose(file);
        } else if (strcmp(buffer, "OFF") == 0) {
            gpiod_line_set_value(line, 0);
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            FILE *file = fopen("relay_log.txt", "a");
            fprintf(file, "[%d-%02d-%02d %02d:%02d:%02d] Relay OFF\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);
            fclose(file);
        } else {
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            FILE *file = fopen("relay_log.txt", "a");
            fprintf(file, "[%d-%02d-%02d %02d:%02d:%02d] Invalid command: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, buffer);
            fclose(file);
        }

        send(new_socket, msg, strlen(msg), 0);
        close(new_socket);
    }

    return 0;
}

