#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define GPIO_SENSOR 17
#define GPIO_ENA 22
#define GPIO_IN1 23
#define GPIO_IN2 24

#define CONS_POLLS 3

struct gpiod_chip *chip;
struct gpiod_line *sensor_line, *ena_line, *in1_line, *in2_line;

void cleanup(void) {
    gpiod_line_release(sensor_line);
    gpiod_line_release(ena_line);
    gpiod_line_release(in1_line);
    gpiod_line_release(in2_line);
    gpiod_chip_close(chip);
    closelog();
    exit(0);
}

void handle_signal(int signum) {
    syslog(LOG_INFO, "Received signal %d, stopping motor and exiting...", signum);
    gpiod_line_set_value(ena_line, 0);
    gpiod_line_set_value(in1_line, 0);
    gpiod_line_set_value(in2_line, 0);
    cleanup();
}

int main(void) {
    int i, sensor_value, prev_sensor_value, consecutive_polls = 0;

    openlog("rain_window", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Starting rain window program");

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return 1;
    }

    sensor_line = gpiod_chip_get_line(chip, GPIO_SENSOR);
    ena_line = gpiod_chip_get_line(chip, GPIO_ENA);
    in1_line = gpiod_chip_get_line(chip, GPIO_IN1);
    in2_line = gpiod_chip_get_line(chip, GPIO_IN2);

    if (!sensor_line || !ena_line || !in1_line || !in2_line) {
        syslog(LOG_ERR, "Failed to get GPIO lines");
        return 1;
    }

    if (gpiod_line_request_input(sensor_line, "rain_window") < 0) {
        syslog(LOG_ERR, "Failed to request input on sensor line");
        return 1;
    }

    if (gpiod_line_request_output(ena_line, "rain_window", 0) < 0) {
        syslog(LOG_ERR, "Failed to request output on ENA line");
        return 1;
    }

    if (gpiod_line_request_output(in1_line, "rain_window", 0) < 0) {
        syslog(LOG_ERR, "Failed to request output on IN1 line");
        return 1;
    }

    if (gpiod_line_request_output(in2_line, "rain_window", 0) < 0) {
        syslog(LOG_ERR, "Failed to request output on IN2 line");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    prev_sensor_value = 1;
    while (1) {
        sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value && !prev_sensor_value) {
            syslog(LOG_INFO, "Rain detected, starting motor");
            gpiod_line_set_value(ena_line, 1);
            gpiod_line_set_value(in1_line, 1);
            gpiod_line_set_value(in2_line, 0);
            usleep(5000000);
            gpiod_line_set_value(ena_line, 0);
            gpiod_line_set_value(in1_line, 0);
            gpiod_line_set_value(in2_line, 0);
            consecutive_polls = 0;
        } else if (sensor_value) {
            consecutive_polls++;
        } else {
            consecutive_polls = 0;
        }
        prev_sensor_value = sensor_value;
        if (consecutive_polls >= CONS_POLLS) {
            syslog(LOG_INFO, "Sensor read dry for %d consecutive polls, stopping motor", CONS_POLLS);
            gpiod_line_set_value(ena_line, 0);
            gpiod_line_set_value(in1_line, 0);
            gpiod_line_set_value(in2_line, 0);
            consecutive_polls = 0;
        }
        usleep(200000);
    }

    return 0;
}

