#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22
#define SERVO_PIN 18
#define DEBOUNCE_DELAY 50000 // 50ms

struct gpiod_chip *chip;
struct gpiod_line *lock_button, *unlock_button;
struct gpiod_line_request_config req_config;

void stop_servo(void) {
    if (gpiod_line_set_value(lock_button, 0) < 0) {
        perror("Failed to set value");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_set_value(unlock_button, 0) < 0) {
        perror("Failed to set value");
        exit(EXIT_FAILURE);
    }
    gpiod_line_release(lock_button);
    gpiod_line_release(unlock_button);
    gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

int main(void) {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open chip");
        return EXIT_FAILURE;
    }

    lock_button = gpiod_chip_get_line(chip, LOCK_BUTTON);
    unlock_button = gpiod_chip_get_line(chip, UNLOCK_BUTTON);

    req_config = gpiod_line_request_config_input("door-lock");
    if (gpiod_line_request(lock_button, &req_config) < 0) {
        perror("Failed to request line");
        return EXIT_FAILURE;
    }
    if (gpiod_line_request(unlock_button, &req_config) < 0) {
        perror("Failed to request line");
        return EXIT_FAILURE;
    }

    signal(SIGINT, stop_servo);
    signal(SIGTERM, stop_servo);

    while (1) {
        if (gpiod_line_get_value(lock_button) == 0) {
            usleep(DEBOUNCE_DELAY);
            if (gpiod_line_get_value(lock_button) == 0) {
                printf("Locking...\n");
                if (gpiod_line_set_value(lock_button, 1) < 0) {
                    perror("Failed to set value");
                    return EXIT_FAILURE;
                }
                usleep(2000);
                if (gpiod_line_set_value(lock_button, 0) < 0) {
                    perror("Failed to set value");
                    return EXIT_FAILURE;
                }
            }
        }

        if (gpiod_line_get_value(unlock_button) == 0) {
            usleep(DEBOUNCE_DELAY);
            if (gpiod_line_get_value(unlock_button) == 0) {
                printf("Unlocking...\n");
                if (gpiod_line_set_value(unlock_button, 1) < 0) {
                    perror("Failed to set value");
                    return EXIT_FAILURE;
                }
                usleep(1000);
                if (gpiod_line_set_value(unlock_button, 0) < 0) {
                    perror("Failed to set value");
                    return EXIT_FAILURE;
                }
            }
        }
    }

    return EXIT_SUCCESS;
}

