code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define PIR_GPIO 4
#define RELAY_GPIO 17
#define TIMEOUT_MS 60000

struct gpiod_chip *chip;
struct gpiod_line *pir_line, *relay_line;

void cleanup(int signum) {
    gpiod_line_set_value(relay_line, 0);
    gpiod_line_release(pir_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line) {
        perror("Failed to get PIR GPIO line");
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Failed to get RELAY GPIO line");
        return 1;
    }

    int ret = gpiod_line_request_input(pir_line, "motion-detector");
    if (ret < 0) {
        perror("Failed to request PIR GPIO line as input");
        return 1;
    }

    ret = gpiod_line_request_output(relay_line, "relay", 0);
    if (ret < 0) {
        perror("Failed to request RELAY GPIO line as output");
        return 1;
    }

    FILE *file = fopen("security_log.txt", "a");
    if (!file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        ret = gpiod_line_event_wait(pir_line, TIMEOUT_MS);
        if (ret < 0) {
            perror("Failed to wait for GPIO event");
            return 1;
        }

        if (ret > 0) {
            time_t now = time(NULL);
            fprintf(file, "%s: Motion detected\n", ctime(&now));
            fflush(file);

            gpiod_line_set_value(relay_line, 1);
            usleep(6000000);
            gpiod_line_set_value(relay_line, 0);

            now = time(NULL);
            fprintf(file, "%s: Motion stopped\n", ctime(&now));
            fflush(file);
        }
    }

    fclose(file);
    gpiod_line_release(pir_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);

    return 0;
}

