#include <wiringPiI2C.h>

#define MPR121_ADDR 0x5A // MPR121 I2C address
#define GPIO_PIN 17 // GPIO pin number
#define ELE_0 0 // Electrode 0

int fd;

void handle_signal(int signum) {
    digitalWrite(GPIO_PIN, LOW);
    close(fd);
    exit(0);
}

int main() {
    // Setup GPIO
    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(GPIO_PIN, OUTPUT);
    digitalWrite(GPIO_PIN, LOW);

    // Setup I2C
    fd = wiringPiI2CSetup(MPR121_ADDR);
    if (fd == -1) {
        printf("Failed to setup I2C\n");
        return 1;
    }

    // Soft reset
    wiringPiI2CWriteReg8(fd, 0x2B, 0xA5);
    delay(10);

    // Setup electrode filtering
    wiringPiI2CWriteReg8(fd, 0x24, 0x01); // MHD
    wiringPiI2CWriteReg8(fd, 0x25, 0x01); // NHD
    wiringPiI2CWriteReg8(fd, 0x26, 0x01); // NCL
    wiringPiI2CWriteReg8(fd, 0x27, 0x01); // FDL

    // Setup debounce
    wiringPiI2CWriteReg8(fd, 0x2D, 0x10); // 16ms debounce

    // Setup FFI, SFI, CDT
    wiringPiI2CWriteReg8(fd, 0x2E, 0x00); // FFI
    wiringPiI2CWriteReg8(fd, 0x2F, 0x00); // SFI
    wiringPiI2CWriteReg8(fd, 0x30, 0x00); // CDT

    // Enable electrodes
    wiringPiI2CWriteReg8(fd, 0x22, 0x7F); // Enable all electrodes

    // Setup signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        int electrode_state = wiringPiI2CReadReg8(fd, 0x00);
        if (electrode_state & (1 << ELE_0)) {
            delay(200); // Debounce
            if (wiringPiI2CReadReg8(fd, 0x00) & (1 << ELE_0)) {
                digitalWrite(GPIO_PIN, !digitalRead(GPIO_PIN));
            }
        }
    }

    return 0;
}

