#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <event.h>
#include <syslog.h>

#define SERVO_GPIO 17
#define PIR_GPIO 4
#define PORT 5000

void sigint_handler(int sig);
void read_pir(int fd, short event, void *arg);
void write_servo(int angle);
void log_message(const char *format, ...);

int main(void)
{
    openlog("security", LOG_USER, LOG_DAEMON);
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (gpioInitialise() < 0)
    {
        log_message("Failed to initialize GPIO");
        return 1;
    }

    struct event_base *base = event_base_new();
    struct event *ev = event_new(base, -1, EV_READ|EV_PERSIST, read_pir, NULL);
    event_base_set(base, ev);
    event_add(ev, NULL);

    struct sockaddr_in sin;
    sin.sin_family = AF_INET;
    sin.sin_port = htons(PORT);
    sin.sin_addr.s_addr = 0;

    int s = socket(AF_INET, SOCK_STREAM, 0);
    if (bind(s, (struct sockaddr *)&sin, sizeof(sin)) < 0)
    {
        log_message("Failed to bind socket");
        return 1;
    }

    listen(s, 5);
    event_base_dispatch(base);

    return 0;
}

void sigint_handler(int sig)
{
    gpioTerminate();
    closelog();
    exit(0);
}

void read_pir(int fd, short event, void *arg)
{
    char buf[10];
    int len = read(fd, buf, sizeof(buf) - 1);
    if (len > 0)
    {
        buf[len] = '\0';
        log_message("Received command: %s", buf);
        if (strcmp(buf, "PIR") == 0)
        {
            int pir = gpioRead(PIR_GPIO);
            log_message("PIR: %d", pir);
            // send response
        }
        else
        {
            int angle = atoi(buf + 10); // assuming the command is in the form "servo <angle>"
            write_servo(angle);
        }
    }
}

void write_servo(int angle)
{
    // assuming a 1ms pulse corresponds to 0 degrees and a 2ms pulse corresponds to 180 degrees
    int pulse_width = (angle * 180 / 1000) + 1000;
    gpioServo(SERVO_GPIO, pulse_width);
    log_message("Set servo to %d degrees", angle);
}

void log_message(const char *format, ...)
{
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    va_end(args);

    va_start(args, format);
    vsyslog(LOG_USER, format, args);
    va_end(args);

    va_start(args, format);
    FILE *log_file = fopen("security.log", "a");
    if (log_file != NULL)
    {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        fprintf(log_file, "%s: ", timestamp);
        vfprintf(log_file, format, args);
        fclose(log_file);
    }
    va_end(args);
}

