#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <bcm2835.h>
#include <time.h>

#define BH1750_ADDR 0x23
#define BH1750_CMD_POWER_DOWN 0x00
#define BH1750_CMD_POWER_ON 0x01
#define BH1750_CMD_RESET 0x07
#define BH1750_CMD_CONTINUOUS_H_RES_MODE 0x10

#define GPIO_RELAY 23

FILE *log_file;

void sig_handler(int signum) {
    bcm2835_i2c_end();
    fclose(log_file);
    bcm2835_gpio_write(GPIO_RELAY, LOW);
    bcm2835_close();
    exit(0);
}

int main() {
    if (!bcm2835_init()) {
        printf("bcm2835_init failed. Are you running as root?\n");
        return 1;
    }

    if (!bcm2835_i2c_begin()) {
        printf("bcm2835_i2c_begin failed\n");
        return 1;
    }

    bcm2835_i2c_setSlaveAddress(BH1750_ADDR);
    bcm2835_i2c_set_baudrate(100000);

    bcm2835_gpio_fsel(GPIO_RELAY, BCM2835_GPIO_FSEL_OUTP);

    log_file = fopen("grow_log.txt", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    char cmd = BH1750_CMD_POWER_ON;
    bcm2835_i2c_write(&cmd, 1);
    bcm2835_delay(120);

    while (1) {
        char data[2];
        bcm2835_i2c_read(data, 2);
        if (bcm2835_i2c_getError() != BCM2835_I2C_REASON_OK) {
            printf("I2C read error\n");
            continue;
        }

        int lux = (data[0] << 8) | data[1];
        time_t now = time(NULL);
        fprintf(log_file, "%ld, %d\n", now, lux);
        if (ferror(log_file)) {
            printf("Failed to write to log file\n");
            return 1;
        }

        if (lux < 150) {
            bcm2835_gpio_write(GPIO_RELAY, HIGH);
        } else {
            bcm2835_gpio_write(GPIO_RELAY, LOW);
        }

        bcm2835_delay(2000);
    }

    return 0;
}

