#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <syslog.h>

#define DOUT 23
#define SCK 24
#define LOCK 25
#define TARE_READINGS 10
#define AVG_READINGS 5
#define TIMEOUT 1000000

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
}

uint32_t read_hx711() {
    uint32_t value = 0;
    gpioSetMode(SCK, PI_OUTPUT);
    gpioWrite(SCK, 0);

    gpioSetMode(DOUT, PI_INPUT);

    for (int i = 0; i < 24; i++) {
        gpioWrite(SCK, 1);
        gpioDelay(1);
        value <<= 1;
        if (gpioRead(DOUT)) value |= 1;
        gpioWrite(SCK, 0);
        gpioDelay(1);
    }

    gpioSetMode(DOUT, PI_OUTPUT);
    return value;
}

int main(int argc, char *argv[]) {
    int threshold = 1000;
    float scale = 1.0;
    int duration = 500;

    openlog("hx711_monitor", LOG_PID, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        closelog();
        return 1;
    }

    gpioSetMode(LOCK, PI_OUTPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    for (int i = 0; i < TARE_READINGS; i++) {
        read_hx711();
    }

    while (!stop) {
        uint32_t sum = 0;
        for (int i = 0; i < AVG_READINGS; i++) {
            sum += read_hx711();
        }
        uint32_t avg = sum / AVG_READINGS;
        float weight = avg * scale;

        syslog(LOG_INFO, "Measured weight: %f", weight);

        if (weight > threshold) {
            gpioWrite(LOCK, 1);
            gpioDelay(100000); // 200ms
            gpioWrite(LOCK, 0);
        }

        sleep(duration / 1000);
    }

    gpioTerminate();
    closelog();

    return 0;
}

