#include <signal.h>
#include <syslog.h>
#include <gpiod.h>
#include <MQTTClient.h>

#define ADDRESS     "tcp://localhost:1883"
#define CLIENTID    "relay_controller_1"
#define TOPIC       "home/lights/control"
#define QOS         0
#define TIMEOUT     60
#define GPIO_CHIP   "gpiochip0"
#define GPIO_LINE   17

volatile MQTTClient client;
volatile struct gpiod_chip *chip;
volatile struct gpiod_line *line;

void handle_signal(int signal) {
    syslog(LOG_INFO, "Received signal %d, stopping loop", signal);
    MQTTClient_disconnect(client, 1000);
    gpiod_line_set_value(line, 0);
    gpiod_chip_close(chip);
    MQTTClient_destroy(&client);
    closelog();
    exit(0);
}

int main(int argc, char* argv[]) {
    openlog("mqtt_relay", LOG_PID, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (line == NULL) {
        syslog(LOG_ERR, "Failed to get GPIO line");
        return 1;
    }

    int ret = gpiod_line_request_output(line, CLIENTID, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set GPIO line as output");
        return 1;
    }

    MQTTClient_create(&client, ADDRESS, CLIENTID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
