#include <pigpio.h>
#include <stdio.h>
#include <signal.h>
#include <stdint.h>

#define PWM_FREQ 10000
#define PWM_RANGE 255
#define ENCODER_TICKS_PER_REV 64
#define ENCODER_POLL_INTERVAL 100 // in ms
#define ENCODER_STALL_TIMEOUT 2000 // in ms

uint32_t encoderA = 0, encoderB = 0;
uint32_t lastEncoderA = 0, lastEncoderB = 0;
uint32_t lastEncoderATime = 0, lastEncoderBTime = 0;

void encoderAISR(int gpio, int level, uint32_t tick) {
    if (gpio == BCM_GPIO_4) {
        if (level == PI_ON) {
            encoderA++;
        }
    }
}

void encoderBISR(int gpio, int level, uint32_t tick) {
    if (gpio == BCM_GPIO_5) {
        if (level == PI_ON) {
            encoderB++;
        }
    }
}

void controlLoop() {
    while (1) {
        // Calculate RPM
        uint32_t rpmA = (encoderA - lastEncoderA) * 1000 / (tickDiff(lastEncoderATime, tick) / 1000);
        uint32_t rpmB = (encoderB - lastEncoderB) * 1000 / (tickDiff(lastEncoderBTime, tick) / 1000);

        // Calculate error
        int32_t error = rpmA - rpmB;

        // Calculate PWM duty cycle
        int32_t dutyCycle = error * PWM_RANGE / 100;
        if (dutyCycle < 0) dutyCycle = 0;
        else if (dutyCycle > PWM_RANGE) dutyCycle = PWM_RANGE;

        // Set PWM duty cycle
        gpioPWM(BCM_GPIO_17, dutyCycle);
        gpioPWM(BCM_GPIO_22, dutyCycle);

        // Print RPM and duty cycle
        printf("RPM A: %d, RPM B: %d, Duty cycle: %d\n", rpmA, rpmB, dutyCycle);

        // Check for encoder stall
        if (tickDiff(lastEncoderATime, tick) > ENCODER_STALL_TIMEOUT) {
            printf("Encoder A stall detected\n");
        }
        if (tickDiff(lastEncoderBTime, tick) > ENCODER_STALL_TIMEOUT) {
            printf("Encoder B stall detected\n");
        }

        // Update last encoder values and time
        lastEncoderA = encoderA;
        lastEncoderB = encoderB;
        lastEncoderATime = tick;
        lastEncoderBTime = tick;

        // Sleep for control loop interval
        time_sleep(ENCODER_POLL_INTERVAL / 1000.0);
    }
}

void sigintHandler(int sig) {
    // Stop motors
    gpioWrite(BCM_GPIO_17, PI_OFF);
    gpioWrite(BCM_GPIO_18, PI_OFF);
    gpioWrite(BCM_GPIO_22, PI_OFF);
    gpioWrite(BCM_GPIO_23, PI_OFF);

    // Release resources
    gpioTerminate();

    // Exit program
    exit(0);
}

int main() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up encoder interrupts
    gpioSetAlertFunc(BCM_GPIO_4, encoderAISR);
    gpioSetAlertFunc(BCM_GPIO_5, encoderBISR);

    // Set up PWM
    gpioSetPWMfrequency(BCM_GPIO_17, PWM_FREQ);
    gpioSetPWMfrequency(BCM_GPIO_22, PWM_FREQ);

    // Set up motor control pins
    gpioSetMode(BCM_GPIO_17, PI_OUTPUT);
    gpioSetMode(BCM_GPIO_18, PI_OUTPUT);
    gpioSetMode(BCM_GPIO_22, PI_OUTPUT);
    gpioSetMode(BCM_GPIO_23, PI_OUTPUT);

    // Set up SIGINT handler
    signal(SIGINT, sigintHandler);

    // Start control loop
    controlLoop();

    return 0;
}

