#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>

#define RELAY_PIN 17
#define I2C_ADDR 0x23
#define I2C_BUS 1
#define BH1750_CMD 0x21

int fd;

void handle_signal(int signum) {
    printf("Exiting...\n");
    digitalWrite(RELAY_PIN, LOW);
    close(fd);
    exit(0);
}

int main() {
    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(RELAY_PIN, OUTPUT);
    digitalWrite(RELAY_PIN, LOW);

    fd = wiringPiI2CSetup(I2C_ADDR);
    if (fd == -1) {
        printf("Failed to setup I2C\n");
        return 1;
    }

    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        printf("Failed to register signal handler\n");
        return 1;
    }

    FILE *file = fopen("chicken_coop_log.txt", "w");
    if (file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    while (1) {
        wiringPiI2CWrite(fd, BH1750_CMD);
        delay(200);
        int lux = wiringPiI2CRead(fd);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, 20, "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(file, "%s: Lux = %d, Relay = %s\n", time_str, lux, digitalRead(RELAY_PIN) ? "ON" : "OFF");
        fflush(file);

        if (lux < 50) {
            if (!digitalRead(RELAY_PIN)) {
                digitalWrite(RELAY_PIN, HIGH);
                fprintf(file, "%s: Relay turned ON\n", time_str);
                fflush(file);
            }
        } else if (lux > 200) {
            if (digitalRead(RELAY_PIN)) {
                digitalWrite(RELAY_PIN, LOW);
                fprintf(file, "%s: Relay turned OFF\n", time_str);
                fflush(file);
            }
        }

        delay(5000);
    }

    return 0;
}

