#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY 50000 // 50ms

struct gpiod_chip *chip;
struct gpiod_line *touch_sensor, *relay;

void handle_sigint(int sig) {
    printf("Caught SIGINT, turning off the relay and exiting...\n");
    gpiod_line_set_value(relay, 0);
    gpiod_line_release(touch_sensor);
    gpiod_line_release(relay);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    touch_sensor = gpiod_chip_get_line(chip, TOUCH_SENSOR_GPIO);
    if (!touch_sensor) {
        fprintf(stderr, "Failed to get touch sensor line\n");
        return 1;
    }

    relay = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay) {
        fprintf(stderr, "Failed to get relay line\n");
        return 1;
    }

    if (gpiod_line_request_input(touch_sensor, "touch_sensor") < 0) {
        fprintf(stderr, "Failed to request touch sensor input\n");
        return 1;
    }

    if (gpiod_line_request_output(relay, "relay", 0) < 0) {
        fprintf(stderr, "Failed to request relay output\n");
        return 1;
    }

    int prev_touch_state = 0;
    int touch_state;
    int relay_state = 0;
    struct timespec debounce_start, debounce_end;

    while (1) {
        touch_state = gpiod_line_get_value(touch_sensor);

        if (touch_state != prev_touch_state) {
            clock_gettime(CLOCK_MONOTONIC, &debounce_start);

            while (1) {
                touch_state = gpiod_line_get_value(touch_sensor);
                if (touch_state != prev_touch_state) {
                    clock_gettime(CLOCK_MONOTONIC, &debounce_end);
                    long debounce_time = (debounce_end.tv_sec - debounce_start.tv_sec) * 1000000 + (debounce_end.tv_nsec - debounce_start.tv_nsec) / 1000;

                    if (debounce_time >= DEBOUNCE_DELAY && prev_touch_state == 1) {
                        relay_state = relay_state ? 0 : 1;
                        gpiod_line_set_value(relay, relay_state);
                        char timestamp[20];
                        time_t t = time(NULL);
                        strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&t));
                        printf("%s: Relay is %s\n", timestamp, relay_state ? "ON" : "OFF");
                        break;
                    }
                }
                usleep(10000); // 10ms
            }

            prev_touch_state = touch_state;
        }

        usleep(10000); // 10ms
    }

    return 0;
}

