    int relay_state = 0;
    struct timespec debounce_start, debounce_end;

    while (1) {
        touch_state = gpiod_line_get_value(touch_sensor);

        if (touch_state != prev_touch_state) {
            clock_gettime(CLOCK_MONOTONIC, &debounce_start);

            while (1) {
                touch_state = gpiod_line_get_value(touch_sensor);
                if (touch_state != prev_touch_state) {
                    clock_gettime(CLOCK_MONOTONIC, &debounce_end);
                    long debounce_time = (debounce_end.tv_sec - debounce_start.tv_sec) * 1000000 + (debounce_end.tv_nsec - debounce_start.tv_nsec) / 1000;

                    if (debounce_time >= DEBOUNCE_DELAY && prev_touch_state == 1) {
                        relay_state = relay_state ? 0 : 1;
                        gpiod_line_set_value(relay, relay_state);
                        char timestamp[20];
                        time_t t = time(NULL);
                        strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&t));
                        printf("%s: Relay is %s\n", timestamp, relay_state ? "ON" : "OFF");
                        break;
                    }
                }
                usleep(10000); // 10ms
            }

            prev_touch_state = touch_state;
        }

        usleep(10000); // 10ms
    }

    return 0;
}
```

This program will continuously check the touch sensor and if it detects a touch, it will wait for 50ms for debouncing, then toggle the relay state. The state of the relay will be logged with an ISO-8601 timestamp. If the program is interrupted by a SIGINT signal, it will turn off the relay and exit.

Please note that you need to have the libgpiod library installed and the program needs to be run with root privileges to access the GPIO pins.

Also, the GPIO pin numbers and the debounce delay are hardcoded for simplicity. You may want to make them configurable.

