        if (flowRate > FLOW_RATE_THRESHOLD && valveState == HIGH)
        {
            gpioWrite(VALVE_GPIO, LOW);
            valveState = LOW;
            time_t now = time(NULL);
            fprintf(logFile, "[%s] Valve turned off\n", ctime(&now));
            fflush(logFile);
        }
        else if (flowRate < (FLOW_RATE_THRESHOLD - HYSTERESIS) && valveState == LOW)
        {
