#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_TOUCH 4
#define GPIO_RELAY 17
#define DEBOUNCE_DEFAULT 50

struct gpiod_chip *chip;
struct gpiod_line *touch, *relay;

void handle_signal(int signum) {
    gpiod_line_release(touch);
    gpiod_line_release(relay);
    gpiod_chip_close(chip);
    exit(0);
}

int main(int argc, char *argv[]) {
    int debounce = DEBOUNCE_DEFAULT;
    if (argc > 1 && argv[1][0] == '-' && argv[1][1] == 'd') {
        debounce = atoi(argv[1] + 2);
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    touch = gpiod_chip_get_line(chip, GPIO_TOUCH);
    if (!touch) {
        perror("Failed to get GPIO line");
        return 1;
    }

    relay = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!relay) {
        perror("Failed to get GPIO line");
        return 1;
    }

    if (gpiod_line_request_input(touch, "touch") < 0) {
        perror("Failed to request GPIO line as input");
        return 1;
    }

    if (gpiod_line_request_output(relay, "relay", 0) < 0) {
        perror("Failed to request GPIO line as output");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_state = 0;
    while (1) {
        int state = gpiod_line_get_value(touch);
        if (state && !last_state) {
            sleep(debounce / 1000);
            state = gpiod_line_get_value(touch);
            if (state && !last_state) {
                last_state = state;
                gpiod_line_set_value(relay, !gpiod_line_get_value(relay));
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                char buffer[20];
                strftime(buffer, 20, "%F %T", tm_info);
                printf("%s Relay: %s\n", buffer, gpiod_line_get_value(relay) ? "ON" : "OFF");
            }
        } else {
            last_state = state;
        }
    }

    return 0;
}

