        getchar();  // consume the newline character

        if (c == '+') {
            angle += 100;
            if (angle > SERVO_MAX) angle = SERVO_MAX;
        } else if (c == '-') {
            angle -= 100;
            if (angle < SERVO_MIN) angle = SERVO_MIN;
        } else if (c == 'q') {
            break;
        } else {
            continue;
        }

        printf("Setting angle to %d\n", angle);

        if (gpioServo(SERVO_PIN, angle) < 0) {
