    if (!touch_sensor) {
        perror("Failed to get touch sensor line");
        gpiod_chip_close(chip);
        return 1;
    }

    relay = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay) {
        perror("Failed to get relay line");
        gpiod_line_release(touch_sensor);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(touch_sensor, "touch_sensor") < 0) {
