        touch_sensor_value = gpiod_line_get_value(touch_sensor);
        if (touch_sensor_value < 0) {
            perror("Failed to read touch sensor value");
            break;
        }

        if (touch_sensor_value) {
            if (!release_start_time_ms) {
                release_start_time_ms = gpiod_get_time_ns() / 1000000;
            } else if ((gpiod_get_time_ns() / 1000000) - release_start_time_ms > RELEASE_TIMEOUT_MS) {
                gpiod_line_set_value(relay, 0);
                release_start_time_ms = 0;
