#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define GPIO_VALVE 18
#define GPIO_DIRECTION 23
#define GPIO_FLOW 24
#define PWM_RANGE 255

volatile int flow_count = 0;
volatile unsigned int last_flow_time = 0;

void flow_isr(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        flow_count++;
    }
}

void handle_signal(int signum) {
    gpioWrite(GPIO_VALVE, 0);
    gpioWrite(GPIO_DIRECTION, 0);
    fclose(fopen("flow_log.csv", "a"));
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s -t target_flow_rate\n", argv[0]);
        return 1;
    }

    double target_flow_rate = atof(argv[1]);
    if (target_flow_rate <= 0) {
        printf("Invalid target flow rate\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO library\n");
        return 1;
    }

    gpioSetMode(GPIO_VALVE, PI_OUTPUT);
    gpioSetMode(GPIO_DIRECTION, PI_OUTPUT);
    gpioSetMode(GPIO_FLOW, PI_INPUT);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpioWrite(GPIO_DIRECTION, 1);

    gpioSetAlertFunc(GPIO_FLOW, flow_isr);

    FILE *log_file = fopen("flow_log.csv", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    while (1) {
        unsigned int current_time = time(NULL);
        if (current_time - last_flow_time >= 100) {
            double flow_rate = (double)flow_count / 10;
            flow_count = 0;
            last_flow_time = current_time;

            double valve_position = flow_rate / target_flow_rate;
            if (valve_position > 1.0) {
                valve_position = 1.0;
            }

            int duty_cycle = (int)(valve_position * PWM_RANGE);
            gpioHardwarePWM(GPIO_VALVE, 100000, duty_cycle * 100000);

            fprintf(log_file, "%u,%f,%f\n", current_time, flow_rate, valve_position);
            fflush(log_file);
        }
    }

    return 0;
}

