    close(fd);
    exit(0);
}

int main() {
    // Set up signal handling
    signal(SIGINT, handle_signal);

    // Initialize GPIO
    if (wiringPiSetupGpio() == -1) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    // Set up GPIO pin
    pinMode(GPIO_PIN, OUTPUT);

    // Initialize I2C
    fd = wiringPiI2CSetup(MPR121_ADDR);
    if (fd == -1) {
        printf("Failed to initialize I2C\n");
        return 1;
    }

    // Soft reset
    wiringPiI2CWriteReg8(fd, 0x2B, 0x40);
    delay(10);

    // Configure filtering parameters
    wiringPiI2CWriteReg8(fd, 0x2A, 0x40);
    delay(10);

    // Set touch and release thresholds
    for (int i = 0; i < 12; i++) {
        wiringPiI2CWriteReg8(fd, 0x02 + i, 0x00);
        wiringPiI2CWriteReg8(fd, 0x12 + i, 0x00);
    }
    delay(10);

    // Enable run mode
    wiringPiI2CWriteReg8(fd, 0x2B, 0x00);
    delay(10);

    // Main loop
    while (1) {
        for (int i = 0; i < 12; i++) {
            int touch_status = wiringPiI2CReadReg8(fd, 0x00 + i);
            if (touch_status & (1 << i)) {
                // Touch detected
                digitalWrite(GPIO_PIN, HIGH);
                FILE *file = fopen(FILE_NAME, "a");
                if (file != NULL) {
                    time_t now = time(NULL);
                    fprintf(file, "%s", ctime(&now));
                    fclose(file);
                }
            } else {
                // No touch detected
                digitalWrite(GPIO_PIN, LOW);
            }
        }
        delay(50);
    }

    return 0;
}

