    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN);

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, PI_OFF);

    time_t lastUnlockTime = 0;

    while (1) {
        gpioDelay(50000); // Delay for 50ms

        int pirState = gpioRead(PIR_PIN);
        if (pirState == PI_ON && time(NULL) - lastUnlockTime > RATE_LIMIT_TIME) {
            lastUnlockTime = time(NULL);

            fprintf(logFile, "%ld: Motion detected\n", lastUnlockTime);

            gpioWrite(RELAY_PIN, PI_ON);
            time_sleep(0.5); // Unlock for 500ms
            gpioWrite(RELAY_PIN, PI_OFF);

            fprintf(logFile, "%ld: Door unlocked\n", time(NULL));
        }
    }

    return 0;
}

