        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    srand(time(NULL));

    if (gpioSetMode(MOTOR1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for motor 1\n");
        return 1;
    }

    if (gpioSetMode(MOTOR2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for motor 2\n");
        return 1;
    }

    while (!shutdown) {
        int steps = rand() % 11 + 5;

        for (int i = 0; i < steps && !shutdown; i++) {
            int duty1 = rand() % (MAX_DUTY - MIN_DUTY + 1) + MIN_DUTY;
            int duty2 = rand() % (MAX_DUTY - MIN_DUTY + 1) + MIN_DUTY;
            int delay = rand() % (MAX_DELAY - MIN_DELAY + 1) + MIN_DELAY;

            gpioPWM(MOTOR1, duty1);
            gpioPWM(MOTOR2, duty2);

            time_sleep(delay / 1000.0);
        }
    }

    gpioPWM(MOTOR1, 0);
    gpioPWM(MOTOR2, 0);

    gpioTerminate();

    return 0;
}
