#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <softPwm.h>
#include <stdio.h>
#include <stdlib.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>

#define SENSOR_PIN 4
#define MOTOR_PWM_PIN 27
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18

#define PWM_FREQ 1000
#define PWM_DUTY_CYCLE 150

int sensor_reading = 0;
int consecutive_low_readings = 0;

void stop_motor() {
    digitalWrite(MOTOR_IN1_PIN, LOW);
    digitalWrite(MOTOR_IN2_PIN, LOW);
    softPwmWrite(MOTOR_PWM_PIN, 0);
}

void handle_signal(int signum) {
    syslog(LOG_INFO, "Received signal %d, stopping motor", signum);
    stop_motor();
    closelog();
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    openlog("window_control", LOG_PID, LOG_USER);

    if (wiringPiSetupGpio() == -1) {
        syslog(LOG_ERR, "Failed to setup wiringPi: %s", strerror(errno));
        return 1;
    }

    if (wiringPiISetupI2C(-1) == -1) {
        syslog(LOG_ERR, "Failed to setup I2C: %s", strerror(errno));
        return 1;
    }

    pinMode(SENSOR_PIN, INPUT);
    pinMode(MOTOR_PWM_PIN, OUTPUT);
    pinMode(MOTOR_IN1_PIN, OUTPUT);
    pinMode(MOTOR_IN2_PIN, OUTPUT);

    softPwmCreate(MOTOR_PWM_PIN, 0, 255);

    while (1) {
        for (int i = 0; i < 5; i++) {
            delay(50);
            sensor_reading = digitalRead(SENSOR_PIN);
            if (sensor_reading == LOW) {
                consecutive_low_readings++;
            } else {
                consecutive_low_readings = 0;
            }
        }

        if (consecutive_low_readings >= 3) {
            syslog(LOG_INFO, "Rain detected, closing window");
            digitalWrite(MOTOR_IN1_PIN, HIGH);
            digitalWrite(MOTOR_IN2_PIN, LOW);
            softPwmWrite(MOTOR_PWM_PIN, PWM_DUTY_CYCLE);
            delay(5000);
            stop_motor();
            syslog(LOG_INFO, "Window closed");
        }

        consecutive_low_readings = 0;
        delay(60000);
    }

    return 0;
}

