#include <wiringPi.h>
#include <time.h>
#include <stdio.h>
#include <signal.h>
#include <stdlib.h>

#define DT 23
#define SCK 24
#define LOCK 17

void writeSCK(int val) {
    digitalWrite(SCK, val);
    delay(1);
}

int readDT() {
    return digitalRead(DT);
}

void logEvent(char* event) {
    FILE *file = fopen("stock_events.txt", "a");
    if (file == NULL) {
        printf("Error opening file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(file, "%d-%02d-%02d %02d:%02d:%02d - %s\n",
        tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
        tm.tm_hour, tm.tm_min, tm.tm_sec, event);

    fclose(file);
}

void signalHandler(int signum) {
    digitalWrite(LOCK, 0);
    exit(0);
}

int main() {
    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(DT, INPUT);
    pinMode(SCK, OUTPUT);
    pinMode(LOCK, OUTPUT);

    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    while (1) {
        unsigned long data = 0;
        int i;

        for (i = 0; i < 24; i++) {
            writeSCK(1);
            data <<= 1;
            if (readDT()) data |= 1;
            writeSCK(0);
        }

        float weight = (data * 1.0) / 700;

        if (weight < 100.0) {
            digitalWrite(LOCK, 1);
            delay(5000);
            digitalWrite(LOCK, 0);
        }

        char buffer[50];
        sprintf(buffer, "Weight: %.2f g", weight);
        logEvent(buffer);

        delay(1000);
    }

    return 0;
}

