#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR_GPIO 16
#define RELAY_GPIO 20
#define LOG_FILE "relay_events.log"

struct gpiod_chip *chip;
struct gpiod_line *sensor_line, *relay_line;
FILE *log_fp;

void cleanup(int signum) {
    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    fclose(log_fp);
    exit(0);
}

int main(void) {
    int sensor_val, relay_val;
    struct timespec ts;
    char timestamp[30];

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        perror("Failed to get sensor line");
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Failed to get relay line");
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Failed to open log file");
        return 1;
    }

    if (gpiod_line_request_input(sensor_line, "obstacle_detector") < 0) {
        perror("Failed to request sensor line");
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "relay_control", 0) < 0) {
        perror("Failed to request relay line");
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        sensor_val = gpiod_line_get_value(sensor_line);
        if (sensor_val < 0) {
            perror("Failed to read sensor value");
            return 1;
        }

        if (sensor_val == 0) {
            relay_val = gpiod_line_get_value(relay_line);
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
            fprintf(log_fp, "%s: Relay turned ON\n", timestamp);
            fflush(log_fp);
            if (gpiod_line_set_value(relay_line, relay_val ? 0 : 1) < 0) {
                perror("Failed to write to relay line");
                return 1;
            }
        }
    }

    return 0;
}

