#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NUM 18
#define CONFIG_FILE "watering.conf"

volatile sig_atomic_t interrupt_received = 0;

void signal_handler(int signum) {
    interrupt_received = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int duration;
    FILE *file;
    char line_str[256];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_NUM);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line, "watering_program", 0) < 0) {
        fprintf(stderr, "Failed to set GPIO line as output\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    file = fopen(CONFIG_FILE, "r");
    if (!file) {
        fprintf(stderr, "Failed to open configuration file\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (!fgets(line_str, sizeof(line_str), file)) {
        fprintf(stderr, "Empty configuration file\n");
        fclose(file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (sscanf(line_str, "duration=%d", &duration) != 1 || duration < 1 || duration > 3600) {
        fprintf(stderr, "Invalid duration in configuration file\n");
        fclose(file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    fclose(file);

    printf("Starting watering for %d seconds\n", duration);

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to activate valve\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    sleep(duration);

    printf("Watering complete\n");

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to deactivate valve\n");
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

