#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <stdio.h>

#define LEFT_SENSOR_GPIO 4
#define MIDDLE_SENSOR_GPIO 17
#define RIGHT_SENSOR_GPIO 27
#define LEFT_MOTOR_GPIO 22
#define RIGHT_MOTOR_GPIO 23

#define PWM_FREQ 1000
#define BASE_SPEED 150

FILE *log_file;

void stop_motors(void)
{
    gpioPWM(LEFT_MOTOR_GPIO, 0);
    gpioPWM(RIGHT_MOTOR_GPIO, 0);
}

void signal_handler(int signum)
{
    stop_motors();
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main(void)
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    log_file = fopen("trace_log.txt", "w");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LEFT_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(LEFT_MOTOR_GPIO, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_GPIO, PI_OUTPUT);

    gpioSetPWMrange(LEFT_MOTOR_GPIO, 255);
    gpioSetPWMrange(RIGHT_MOTOR_GPIO, 255);

    gpioSetPWMfrequency(LEFT_MOTOR_GPIO, PWM_FREQ);
    gpioSetPWMfrequency(RIGHT_MOTOR_GPIO, PWM_FREQ);

    while (1)
    {
        int left_sensor = gpioRead(LEFT_SENSOR_GPIO);
        int middle_sensor = gpioRead(MIDDLE_SENSOR_GPIO);
        int right_sensor = gpioRead(RIGHT_SENSOR_GPIO);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, 20, "%Y-%m-%dT%H:%M:%S", tm_info);

        fprintf(log_file, "%s,%d,%d,%d,", timestamp, left_sensor, middle_sensor, right_sensor);

        if (middle_sensor == 0)
        {
            gpioPWM(LEFT_MOTOR_GPIO, BASE_SPEED);
            gpioPWM(RIGHT_MOTOR_GPIO, BASE_SPEED);
        }
        else if (left_sensor == 0)
        {
            gpioPWM(LEFT_MOTOR_GPIO, BASE_SPEED / 2);
            gpioPWM(RIGHT_MOTOR_GPIO, BASE_SPEED);
        }
        else if (right_sensor == 0)
        {
            gpioPWM(LEFT_MOTOR_GPIO, BASE_SPEED);
            gpioPWM(RIGHT_MOTOR_GPIO, BASE_SPEED / 2);
        }
        else
        {
            stop_motors();
        }

        fprintf(log_file, "%d,%d\n", gpioGetPWMdutycycle(LEFT_MOTOR_GPIO), gpioGetPWMdutycycle(RIGHT_MOTOR_GPIO));

        time_sleep(0.01);
    }

    return 0;
}

