#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <wiringPi.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define RELAY_PIN 23

int fd;

void handle_signal(int signum) {
    close(fd);
    digitalWrite(RELAY_PIN, LOW);
    wiringPiTerminate();
    exit(0);
}

int main() {
    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    pinMode(RELAY_PIN, OUTPUT);

    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        printf("Failed to open I2C device\n");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        printf("Failed to acquire bus access or talk to slave\n");
        return 1;
    }

    signal(SIGINT, handle_signal);

    FILE *log_file = fopen("grow_log.txt", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    while (1) {
        char buf[2] = {0};
        if (write(fd, buf, 1) != 1) {
            time_t now = time(NULL);
            fprintf(log_file, "%ld: Failed to write to I2C device\n", now);
            continue;
        }

        usleep(180000);

        if (read(fd, buf, 2) != 2) {
            time_t now = time(NULL);
            fprintf(log_file, "%ld: Failed to read from I2C device\n", now);
            continue;
        }

        int lux = (buf[0] << 8) | buf[1];
        time_t now = time(NULL);
        fprintf(log_file, "%ld: Lux = %d\n", now, lux);

        if (lux < 150) {
            digitalWrite(RELAY_PIN, HIGH);
            fprintf(log_file, "%ld: Relay turned ON\n", now);
        } else {
            digitalWrite(RELAY_PIN, LOW);
            fprintf(log_file, "%ld: Relay turned OFF\n", now);
        }
    }

    fclose(log_file);
    return 0;
}

