            fprintf(log_file, "%ld: Failed to write to I2C device\n", now);
            continue;
        }

        usleep(180000);

        if (read(fd, buf, 2) != 2) {
            time_t now = time(NULL);
            fprintf(log_file, "%ld: Failed to read from I2C device\n", now);
            continue;
        }

        int lux = (buf[0] << 8) | buf[1];
        time_t now = time(NULL);
        fprintf(log_file, "%ld: Lux = %d\n", now, lux);

        if (lux < 150) {
            digitalWrite(RELAY_PIN, HIGH);
            fprintf(log_file, "%ld: Relay turned ON\n", now);
        } else {
            digitalWrite(RELAY_PIN, LOW);
            fprintf(log_file, "%ld: Relay turned OFF\n", now);
        }
    }

    fclose(log_file);
    return 0;
}
```

This program continuously reads from the BH1750 light sensor and writes the lux value and relay state to a log file. If a read or write operation fails, it logs the error and continues without crashing. The program will terminate gracefully when a SIGINT signal is received.

Please note that the BH1750 sensor requires a 180ms measurement delay, so the `usleep(180000)` call is used to ensure this delay.

Also, the relay control is done using the `digitalWrite` function from the `wiringPi` library. The relay is controlled by setting the GPIO pin to HIGH or LOW.

Finally, the program logs the current time and the lux value to the log file using the `fprintf` function. The log file is opened and closed at the beginning and end of the program, respectively.

