    mraa_gpio_close(SOUND_SENSOR_PIN);
    mraa_gpio_close(ALARM_LED_PIN);
    zmq_close(publisher);
    zmq_close(subscriber);
    zmq_ctx_destroy(context);
    exit(0);
}

int main(int argc, char* argv[]) {
    if (argc != 2 || (strcmp(argv[1], "sound_sensor") != 0 && strcmp(argv[1], "alarm_node") != 0)) {
        printf("Usage: %s [sound_sensor|alarm_node]\n", argv[0]);
        return 1;
    }

    wiringPiSetup();
    mraa_init();

    mraa_gpio_context sound_sensor = mraa_gpio_init(SOUND_SENSOR_PIN);
    mraa_gpio_context alarm_led = mraa_gpio_init(ALARM_LED_PIN);

    mraa_gpio_dir(sound_sensor, MRAA_GPIO_IN);
    mraa_gpio_dir(alarm_led, MRAA_GPIO_OUT);

    context = zmq_ctx_new();
    publisher = zmq_socket(context, ZMQ_PUB);
    subscriber = zmq_socket(context, ZMQ_SUB);

    zmq_bind(publisher, "tcp://*:5555");
    zmq_connect(subscriber, "tcp://localhost:5555");

    zmq_setsockopt(subscriber, ZMQ_SUBSCRIBE, "SOUND_ALERTS", strlen("SOUND_ALERTS"));

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (strcmp(argv[1], "sound_sensor") == 0) {
        while (1) {
            if (mraa_gpio_read(sound_sensor) == 0) {
                zmq_send(publisher, "SOUND_ALERTS", strlen("SOUND_ALERTS"), 0);
            }
            delay(10);
        }
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        while (1) {
            char message[10];
            zmq_recv(subscriber, message, sizeof(message), 0);
            if (strcmp(message, "SOUND_ALERTS") == 0) {
                mraa_gpio_write(alarm_led, 1);
                delay(1000);
                mraa_gpio_write(alarm_led, 0);
            }
        }
    }

    return 0;
}

