}

float readSensor(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        return NAN;
    }
    if (write(fd, &BH1750_CMD, 1) != 1) {
        return NAN;
    }
    usleep(180000);
    unsigned char buf[2];
    if (read(fd, buf, 2) != 2) {
        return NAN;
    }
    return (buf[0] << 8) | buf[1];
}

int main() {
    signal(SIGINT, sigintHandler);
    signal(SIGTERM, sigintHandler);

    if (wiringPiSetup() == -1) {
        return 1;
    }

    i2cFd1 = wiringPiI2CSetup(I2C_ADDR1);
    i2cFd2 = wiringPiI2CSetup(I2C_ADDR2);
    i2cFd3 = wiringPiI2CSetup(I2C_ADDR3);
    i2cFd4 = wiringPiI2CSetup(I2C_ADDR4);

    udpFd = socket(AF_INET, SOCK_DGRAM, 0);
    memset(&udpAddr, 0, sizeof(udpAddr));
    udpAddr.sin_family = AF_INET;
    udpAddr.sin_port = htons(UDP_PORT);
    udpAddr.sin_addr.s_addr = inet_addr(UDP_ADDR);

    while (!terminate) {
        char msg[256];
        sprintf(msg, "1,%.1f;2,%.1f;3,%.1f;4,%.1f",
                readSensor(i2cFd1, I2C_ADDR1),
                readSensor(i2cFd2, I2C_ADDR2),
                readSensor(i2cFd3, I2C_ADDR3),
                readSensor(i2cFd4, I2C_ADDR4));
        sendto(udpFd, msg, strlen(msg), 0, (struct sockaddr*)&udpAddr, sizeof(udpAddr));
        sleep(1);
    }

    close(i2cFd1);
    close(i2cFd2);
    close(i2cFd3);
    close(i2cFd4);
    close(udpFd);

    return 0;
}
