#include <wiringPiI2C.h>
#include <wiringPi.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <signal.h>

#define BH1750_ADDR 0x23
#define BH1750_POWER_DOWN 0x00
#define BH1750_POWER_ON 0x01
#define BH1750_RESET 0x07
#define BH1750_TO_ONE 0x20
#define BH1750_TO_TWO 0x40
#define BH1750_TO_FOUR 0x60
#define BH1750_TO_EIGHT 0x80

int fd;
int res;
float lux;
char buffer[256];
struct sockaddr_in si_other;
int sock;

void sig_handler(int signum) {
    printf("Caught signal %d\n", signum);
    close(fd);
    close(sock);
    exit(0);
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (wiringPiSetup() == -1) {
        printf("wiringPiSetup failed\n");
        return 1;
    }

    fd = wiringPiI2CSetup(BH1750_ADDR);
    if (fd == -1) {
        printf("wiringPiI2CSetup failed\n");
        return 1;
    }

    res = wiringPiI2CWrite(fd, BH1750_POWER_ON);
    if (res == -1) {
        printf("wiringPiI2CWrite failed\n");
        return 1;
    }

    res = wiringPiI2CWrite(fd, BH1750_TO_ONE);
    if (res == -1) {
        printf("wiringPiI2CWrite failed\n");
        return 1;
    }

    if ((sock = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP)) == -1) {
        printf("Failed to create socket\n");
        return 1;
    }

    memset((char *) &si_other, 0, sizeof(si_other));
    si_other.sin_family = AF_INET;
    si_other.sin_port = htons(5000);
    if (inet_aton("239.255.255.250", &si_other.sin_addr) == 0) {
        printf("Failed to convert address\n");
        return 1;
    }

    while (1) {
        usleep(1000000);

        res = wiringPiI2CRead(fd);
        if (res == -1) {
            printf("wiringPiI2CRead failed\n");
            continue;
        }

        lux = (float)res / 1.2;
        sprintf(buffer, "%f", lux);

        if (sendto(sock, buffer, strlen(buffer), 0, (struct sockaddr *) &si_other, sizeof(si_other)) == -1) {
            printf("Failed to send data\n");
            continue;
        }
    }

    return 0;
}

