#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <termios.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT 2

int uart_fd;

void handle_signal(int signum) {
    printf("Shutting down...\n");
    close(uart_fd);
    exit(0);
}

int main() {
    struct termios options;
    fd_set readfds;
    char buffer[256];
    char *line;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("Failed to open UART device");
        return 1;
    }

    tcgetattr(uart_fd, &options);
    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_iflag = IGNPAR;
    options.c_cc[VTIME] = 0.5;
    options.c_cc[VMIN] = 0;

    ret = tcsetattr(uart_fd, TCSANOW, &options);
    if (ret == -1) {
        perror("Failed to set UART attributes");
        return 1;
    }

    while (1) {
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        ret = select(uart_fd + 1, &readfds, NULL, NULL, NULL);
        if (ret == -1) {
            perror("Failed to select on UART");
            return 1;
        } else if (ret == 0) {
            printf("UART timeout\n");
            continue;
        }

        ret = read(uart_fd, buffer, sizeof(buffer) - 1);
        if (ret == -1) {
            perror("Failed to read from UART");
            return 1;
        }

        buffer[ret] = '\0';
        line = strtok(buffer, "\n");
        while (line != NULL) {
            char *timestamp_str, *range_str;
            time_t timestamp;
            double range;

            timestamp_str = strtok(line, ",");
            range_str = strtok(NULL, ",");

            if (timestamp_str != NULL && range_str != NULL) {
                timestamp = atol(timestamp_str);
                range = atof(range_str);

                printf("Timestamp: %s, Range: %.2f meters\n", ctime(&timestamp), range);
            }

            line = strtok(NULL, "\n");
        }
    }

    return 0;
}

