#include <stdio.h>
#include <stdlib.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <serialport.h>
#include <signal.h>

#define LEFT_PIN 4
#define MIDDLE_PIN 17
#define RIGHT_PIN 27

#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200

int uart_fd;

void sigint_handler(int sig) {
    printf("Exiting...\n");
    close(uart_fd);
    sp_close(uart_fd);
    exit(0);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        printf("Failed to initialize wiringPi\n");
        return 1;
    }

    // Set up GPIO pins
    pinMode(LEFT_PIN, INPUT);
    pinMode(MIDDLE_PIN, INPUT);
    pinMode(RIGHT_PIN, INPUT);

    // Enable pull-up resistors
    pullUpDnControl(LEFT_PIN, PUD_UP);
    pullUpDnControl(MIDDLE_PIN, PUD_UP);
    pullUpDnControl(RIGHT_PIN, PUD_UP);

    // Initialize UART
    struct sp_port *port;
    if (sp_get_port_by_name(UART_DEVICE, &port) != SP_OK) {
        printf("Failed to open UART device\n");
        return 1;
    }

    if (sp_open(port, BAUD_RATE, SP_MODE_READ_WRITE) != SP_OK) {
        printf("Failed to open UART port\n");
        return 1;
    }

    uart_fd = sp_get_fd(port);

    // Main loop
    while (1) {
        int left_state = digitalRead(LEFT_PIN);
        int middle_state = digitalRead(MIDDLE_PIN);
        int right_state = digitalRead(RIGHT_PIN);

        printf("%d %d %d\n", left_state, middle_state, right_state);

        if (left_state == 0 && middle_state == 0 && right_state == 0) {
            char *message = "EMERGENCY STOP!\n";
            if (sp_write(port, message, strlen(message)) != SP_OK) {
                printf("Failed to write to UART device\n");
            }
        }

        delay(100);
    }

    return 0;
}

